import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class Wanderer {
    volatile boolean asleep = false;

    void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    void countSomeSheep() {
        // Simulate comet surveying
    }

    public static void main(String[] args) {
        Wanderer wanderer = new Wanderer();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            while (!wanderer.asleep) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        executor.submit(wanderer::tryToSleep);

        new Thread(() -> {
            try {
                Thread.sleep(5000);
                wanderer.asleep = true;
                System.out.println("Wanderer is now asleep.");
                executor.shutdown();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }).start();

        try {
            while (!wanderer.asleep) {
                Thread.sleep(100);
