import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

public class CosmicCats {
    private final Set<String> cats;

    public CosmicCats() {
        Set<String> temp = new HashSet<>();
        temp.add("Whiskers");
        temp.add("Paws");
        temp.add("Claw");
        this.cats = Collections.unmodifiableSet(temp);
    }

    public boolean containsId(String id) {
        return cats.contains(id);
    }

    public String displayIds() {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (String cat : cats) {
            sb.append(cat).append(", ");
        }
        if (!cats.isEmpty()) {
            sb.setLength(sb.length() - 2);
        }
        sb.append("]");
        return sb.toString();
    }

    public static void main(String[] args) throws InterruptedException {
        CosmicCats cosmicCats = new CosmicCats();

        Runnable task1 = () -> {
            System.out.println("Is Whiskers a cat? " + cosmicCats.containsId("Whiskers"));
            System.out.println("Is Paws a cat? " + cosmicCats.containsId("Paws"));
            System.out.println("Is Claw a cat? " + cosmicCats.containsId("Claw"));
        };

        Runnable task2 = () -> {
            System.out.println("List of cats: " + cosmicCats.displayIds());
        };

        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(2);
        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(100);
        }
    }
}

