import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CosmicCats {
    private final Set<String> cats;

    private CosmicCats() {
        Set<String> catSet = new HashSet<>();
        catSet.add("Whiskers");
        catSet.add("Paws");
        catSet.add("Claw");
        this.cats = Collections.unmodifiableSet(catSet);
    }

    public static CosmicCats getInstance() {
        return Holder.INSTANCE;
    }

    private static class Holder {
        private static final CosmicCats INSTANCE = new CosmicCats();
    }

    public boolean isCosmicCat(String identifier) {
        return cats.contains(identifier);
    }

    public String displayCats() {
        StringBuilder sb = new StringBuilder();
        for (String cat : cats) {
            sb.append("- ").append(cat).append("\n");
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        CosmicCats cosmicCats = CosmicCats.getInstance();

        Runnable checkWhiskers = () -> {
            boolean isCosmic = cosmicCats.isCosmicCat("Whiskers");
            System.out.println("Whiskers is a cosmic cat: " + isCosmic);
        };

        Runnable checkPaws = () -> {
            boolean isCosmic = cosmicCats.isCosmicCat("Paws");
            System.out.println("Paws is a cosmic cat: " + isCosmic);
        };

        Runnable displayTask = () -> {
            String result = cosmicCats.displayCats();
            System.out.println("List of Cosmic Cats:");
            System.out.print(result);
        };

        executor.execute(checkWhiskers);
        executor.execute(checkPaws);
        executor.execute(displayTask);

        executor.shutdown();
    }
}

