import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class StellarSprites {
    private final Set<String> tags;

    public StellarSprites() {
        Set<String> mutableSet = new HashSet<>();
        mutableSet.add("Flare");
        mutableSet.add("Glint");
        mutableSet.add("Spark");
        this.tags = Collections.unmodifiableSet(mutableSet);
    }

    public boolean isSpriteTag(String tag) {
        return tags.contains(tag);
    }

    public String listSprites() {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (String tag : tags) {
            sb.append(tag).append(", ");
        }
        if (sb.length() > 1) {
            sb.setLength(sb.length() - 2);
        }
        sb.append("]");
        return sb.toString();
    }

    public static void main(String[] args) {
        StellarSprites sprites = new StellarSprites();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            System.out.println("Task 1: Check Flare - " + sprites.isSpriteTag("Flare"));
            System.out.println("Task 1: List Sprites - " + sprites.listSprites());
        };

        Runnable task2 = () -> {
            System.out.println("Task 2: Check Glint - " + sprites.isSpriteTag("Glint"));
            System.out.println("Task 2: List Sprites - " + sprites.listSprites());
        };

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
    }
}

import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

public class StellarSprites {
    private final Set<String> tags;

    public StellarSprites() {
        this.tags = Collections.unmodifiableSet(new HashSet<>(List.of("Flare", "Glint", "Spark")));
    }

    public boolean isSpriteTag(String tag) {
        return tags.contains(tag);
    }

    public String getTagsListString() {
        return tags.stream().collect(Collectors.joining(", ", "[", "]"));
    }

    public static void main(String[] args) {
        StellarSprites sprites = new StellarSprites();
        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(2);

        try {
            for (String tag : List.of("Flare", "Glint")) {
                int finalTagIndex = tag.hashCode();
                executor.execute(() -> {
                    System.out.println("Checking tag: " + Thread.currentThread().getName());
                    String result = sprites.isSpriteTag(String.valueOf(finalTagIndex)) ? "Valid" : "Invalid";
                    System.out.println(result);
                });
            }

            boolean sparkCheck = sprites.isSpriteTag("Spark");
            System.out.println("Spark check in main thread: " + (sparkCheck ? "Valid" : "Invalid"));
        } finally {
            executor.shutdown();
            try {
                if (!executor.awaitTermination(1, java.util.concurrent.TimeUnit.SECONDS)) {
                    executor.shutdownNow();
                }
            } catch (InterruptedException e) {
                executor.shutdownNow();
                Thread.currentThread().interrupt();
            }
        }

        System.out.println("All tags: " + sprites.getTagsListString());
    }
}

import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class StellarSprites {
    private final Set<String> tags;

    public StellarSprites() {
        this.tags = Collections.unmodifiableSet(java.util.HashSet.of("Flare", "Glint", "Spark"));
    }

    public boolean contains(String tag) {
        return tags.contains(tag);
    }

    public String toStringList() {
        List<String> list = java.util.stream.Collectors.toList();
        for (String tag : tags) {
            list.add(tag);
        }
        return String.join(", ", list);
    }

    public static void main(String[] args) {
        final StellarSprites sprites = new StellarSprites();
        final List<String> sharedList = Collections.synchronizedList(java.util.Arrays.asList(sprites.toStringList().split(", ")));
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            for (int i = 0; i < 3; i++) {
                synchronized (sharedList) {
                    sharedList.add("NewTag" + Thread.currentThread().getName() + "-" + i);
                }
                System.out.println(Thread.currentThread().getName() + " added new tag: NewTag" + Thread.currentThread().getName() + "-" + i);
            }
        };

        Runnable task2 = () -> {
            for (int i = 0; i < 3; i++) {
                synchronized (sharedList) {
                    if (i % 2 == 0) {
                        String tag = "NewTag" + Thread.currentThread().getName() + "-" + i;
                        System.out.println(Thread.currentThread().getName() + " checking: " + sprites.contains(tag));
                    }
                }
            }
        };

        executor.execute(task1);
        executor.execute(task2);

        executor.shutdown();
    }
}

