        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            for (int i = 0; i < 3; i++) {
                synchronized (sharedList) {
                    sharedList.add("NewTag" + Thread.currentThread().getName() + "-" + i);
                }
                System.out.println(Thread.currentThread().getName() + " added new tag: NewTag" + Thread.currentThread().getName() + "-" + i);
