import java.util.Collections;
import java.util.ConcurrentSkipListMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DelegatingDeviceTracker {
    private final Map<String, String> devicePositions;

    public DelegatingDeviceTracker(Map<String, String> initialPositions) {
        this.devicePositions = new ConcurrentHashMap<>(initialPositions);
    }

    public String getPosition(String deviceId) {
        return devicePositions.get(deviceId);
    }

    public boolean updatePosition(String deviceId, String newPosition) {
        if (devicePositions.containsKey(deviceId)) {
            devicePositions.put(deviceId, newPosition);
            return true;
        }
        return false;
    }

    public Map<String, String> getAllPositions() {
        return Collections.unmodifiableMap(devicePositions);
    }

    public Map<String, String> getSnapshot() {
        Map<String, String> snapshot = new ConcurrentHashMap<>();
        snapshot.putAll(devicePositions);
        return Collections.unmodifiableMap(snapshot);
    }

    public static void main(String[] args) {
        // Initial positions
        Map<String, String> initialPositions = Map.of(
            "gadget1", "room1",
            "gadget2", "room2"
        );

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPositions);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Thread 1: Update positions
        executor.execute(() -> {
            for (int i = 0; i < 5; i++) {
                boolean success = tracker.updatePosition("gadget1", "room" + (i+3));
                System.out.println("Updated gadget1 to room" + (i+3) + ": " + success);
                try { Thread.sleep(100); } catch (InterruptedException e) {}
            }
        });

        // Thread 2: Query positions
        executor.execute(() -> {
            for (int i = 0; i < 5; i++) {
                String position = tracker.getPosition("gadget2");
                System.out.println("Current position of gadget2: " + position);
                try { Thread.sleep(100); } catch (InterruptedException e) {}
            }
        });

        // Get a snapshot after some operations
        executor.execute(() -> {
            Map<String, String> snapshot = tracker.getSnapshot();
            System.out.println("\nSnapshot of device positions:");
            snapshot.forEach((device, pos) -> 
                System.out.println(device + " is at " + pos)
            );
        });

        // Shutdown the executor after all tasks are completed
        executor.shutdownNow();
    }
}

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DelegatingDeviceTracker {
    private final Map<String, Point> positions = new ConcurrentHashMap<>();

    public DelegatingDeviceTracker(Map<String, Point> initialPositions) {
        this.positions.putAll(initialPositions);
    }

    public Point getPosition(String gadgetID) {
        return positions.get(gadgetID);
    }

    public void updatePosition(String gadgetID, Point newPosition) {
        if (!positions.containsKey(gadgetID)) {
            throw new IllegalArgumentException("Gadget not found");
        }
        positions.replace(gadgetID, newPosition);
    }

    public Map<String, Point> getAllPositionsLive() {
        return Collections.unmodifiableMap(positions);
    }

    public Map<String, Point> getAllPositionsSnapshot() {
        Map<String, Point> snapshot = new HashMap<>(positions.size());
        snapshot.putAll(positions);
        return Collections.unmodifiableMap(snapshot);
    }

    public static void main(String[] args) {
        // Initial positions
        Map<String, Point> initialPositions = new HashMap<>();
        initialPositions.put("Gadget1", new Point(0, 0));
        initialPositions.put("Gadget2", new Point(5, 5));

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPositions);

        // Create a fixed thread pool with 2 threads
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Task to update positions
        Runnable updateTask = () -> {
            for (int i = 0; i < 5; i++) {
                try {
                    String gadgetID = "Gadget" + (i % 2 + 1);
                    Point newPosition = new Point((int) Math.random() * 10, (int) Math.random() * 10);
                    tracker.updatePosition(gadgetID, newPosition);
                    System.out.println("Updated " + gadgetID + " to " + newPosition);
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        // Task to fetch and print positions
        Runnable fetchTask = () -> {
            for (int i = 0; i < 5; i++) {
                try {
                    System.out.println("\nLive view:");
                    Map<String, Point> livePositions = tracker.getAllPositionsLive();
                    livePositions.forEach((id, pos) -> 
                        System.out.println(id + " is at (" + pos.x + ", " + pos.y + ")"));

                    System.out.println("\nSnapshot view:");
                    Map<String, Point> snapshotPositions = tracker.getAllPositionsSnapshot();
                    snapshotPositions.forEach((id, pos) ->
                        System.out.println(id + " is at (" + pos.x + ", " + pos.y + ")"));

                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        // Submit tasks to executor
        executor.submit(updateTask);
        executor.submit(fetchTask);

        // Shutdown executor after completion
        executor.shutdown();
        try {
            executor.awaitTermination(1, java.util.concurrent.TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    static class Point {
        int x;
        int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }
}

