                    System.out.println("\nSnapshot view:");
                    Map<String, Point> snapshotPositions = tracker.getAllPositionsSnapshot();
                    snapshotPositions.forEach((id, pos) ->
                        System.out.println(id + " is at (" + pos.x + ", " + pos.y + ")"));

