import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DelegatingParcelTracker {
    private final Map<String, String> positionMap;

    public DelegatingParcelTracker(Map<String, String> initialPositions) {
        this.positionMap = new ConcurrentHashMap<>(initialPositions);
    }

    public String getPosition(String packageId) {
        return positionMap.get(packageId);
