    public boolean assignPosition(String packageId, String newPosition) {
        return positionMap.replace(packageId, newPosition) != null;
    }

    public Map<String, String> getAllPositions() {
        return Collections.unmodifiableMap(positionMap);
    }

    public Map<String, String> getAllPositionsSnapshot() {
        Map<String, String> snapshot = new HashMap<>(positionMap.size());
        for (Map.Entry<String, String> entry : positionMap.entrySet()) {
            snapshot.put(entry.getKey(), entry.getValue());
        }
        return Collections.unmodifiableMap(snapshot);
    }

    public static void main(String[] args) {
        // Initial package positions
        Map<String, String> initialPositions = new HashMap<>();
        initialPositions.put("PKG1", "Warehouse");
        initialPositions.put("PKG2", "In Transit");

