import java.util.Collections;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class DelegatingParcelTracker {

    private final Map<String, String> packagePositions;

    public DelegatingParcelTracker(Map<String, String> initialPositions) {
        this.packagePositions = new ConcurrentHashMap<>(initialPositions);
    }

    public String getPosition(String id) {
        return packagePositions.get(id);
