        Thread thread2 = new Thread(updateTask);

        thread1.start();
        thread2.start();

        thread1.join();
        thread2.join();

        System.out.println("Live Map: " + tracker.getLiveMap());
        System.out.println("Snapshot: " + tracker.getSnapshot());
