        this.robotCoordinates = new ConcurrentHashMap<>(initialCoordinates);
    }

    public Coordinates getCoordinates(String robotId) {
        return robotCoordinates.get(robotId);
    }

    public boolean updateCoordinates(String robotId, Coordinates newCoordinates) {
        if (robotCoordinates.containsKey(robotId)) {
            robotCoordinates.put(robotId, newCoordinates);
            return true;
        }
        return false;
    }

    public ConcurrentHashMap<String, Coordinates> getAllCoordinatesLiveView() {
        return (ConcurrentHashMap<String, Coordinates>) Collections.unmodifiableMap(robotCoordinates);
    }

    public ConcurrentHashMap<String, Coordinates> getAllCoordinatesSnapshot() {
        return new ConcurrentHashMap<>(robotCoordinates);
    }

    public static void main(String[] args) throws InterruptedException {
        // Initial robot coordinates
        ConcurrentHashMap<String, Coordinates> initial = new ConcurrentHashMap<>();
        initial.put("Robot1", new Coordinates(0, 0));
        initial.put("Robot2", new Coordinates(5, 5));

        DelegatingRobotTracker tracker = new DelegatingRobotTracker(initial);

        // Create fixed thread pool with two threads
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Runnable task to demonstrate concurrent access
        Runnable task = () -> {
            try {
                String currentThread = Thread.currentThread().getName();

                // Get initial coordinates
                Coordinates coords = tracker.getCoordinates("Robot1");
                System.out.println(currentThread + " - Initial position of Robot1: " + coords);

                // Attempt to update coordinates (only succeeds if robot exists)
