import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class QuantumQuokkas {
    private final String[] quokkaLabels = {"Zig", "Zag", "Zog"};

    public boolean isQuokka(String label) {
        for (String q : quokkaLabels) {
            if (q.equals(label)) {
                return true;
            }
        }
        return false;
    }

    public String getQuokkaLabels() {
        return String.join(", ", quokkaLabels);
    }

    public static void main(String[] args) throws InterruptedException {
        final QuantumQuokkas quokkas = new QuantumQuokkas();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            System.out.println("Is 'Zig' a Quokka? " + quokkas.isQuokka("Zig"));
            System.out.println("Is 'Zag' a Quokka? " + quokkas.isQuokka("Zag"));
            System.out.println("Is 'Zog' a Quokka? " + quokkas.isQuokka("Zog"));
        };

        Runnable task2 = () -> {
            System.out.println("Quokka labels: " + quokkas.getQuokkaLabels());
            System.out.println("Is 'Zap' a Quokka? " + quokkas.isQuokka("Zap"));
        };

        executor.submit(task1);
        executor.submit(task2);
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
    }
}

