import java.util.concurrent.CountDownLatch;

public class MysticMantas {
    private final String[] tags;

    public MysticMantas() {
        this.tags = new String[]{"Glimmer", "Ripple", "Twist"};
    }

    public boolean isManta(String tag) {
        for (String t : tags) {
            if (t.equals(tag)) {
                return true;
            }
        }
        return false;
    }

    public String getMantaTags() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < tags.length; i++) {
            sb.append(tags[i]);
            if (i < tags.length - 1) {
                sb.append(", ");
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) throws InterruptedException {
        final MysticMantas mantaTags = new MysticMantas();
        CountDownLatch latch = new CountDownLatch(2);

        Runnable task1 = () -> {
            System.out.println("Is 'Glimmer' a manta? " + mantaTags.isManta("Glimmer"));
            System.out.println("Is 'Spark' a manta? " + mantaTags.isManta("Spark"));
            latch.countDown();
        };

        Runnable task2 = () -> {
            System.out.println("Is 'Ripple' a manta? " + mantaTags.isManta("Ripple"));
            System.out.println("Is 'Shine' a manta? " + mantaTags.isManta("Shine"));
            latch.countDown();
        };

        Thread thread1 = new Thread(task1);
        Thread thread2 = new Thread(task2);

        thread1.start();
        thread2.start();

        latch.await();

        System.out.println("All manta tags: " + mantaTags.getMantaTags());
    }
}

