import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public final class ThreeStooges {
private static final List<String> STOOGES =
Collections.unmodifiableList(Arrays.asList("Moe", "Larry", "Curly"));
private static final Set<String> STOOGES_SET = new HashSet<>(STOOGES);

public boolean isStooge(String name) {
return STOOGES_SET.contains(name);
}

public String getStoogeNames() {
return STOOGES.toString();
}

public static void main(String[] args) {
final ThreeStooges stooges = new ThreeStooges();

ExecutorService executor = Executors.newFixedThreadPool(2);

String[] namesToCheck = {"Moe", "Shemp", "Larry", "Curly", "John", "Curly", "Moe"};

for (int i = 0; i < namesToCheck.length; i++) {
final int taskId = i;
final String name = namesToCheck[i];
executor.submit(new StoogeCheckerTask(stooges, name, taskId));
}

executor.shutdown();
}
}

class StoogeCheckerTask implements Runnable {
private final ThreeStooges stooges;
private final String name;
private final int taskId;

public StoogeCheckerTask(ThreeStooges stooges, String name, int taskId) {
this.stooges = stooges;
this.name = name;
this.taskId = taskId;
}

@Override
public void run() {
System.out.println("Task ID: " + taskId + " - Checking name: " + name);
boolean result = stooges.isStooge(name);
System.out.println("Task ID: " + taskId + " - Is '" + name + "' a stooge? " + result);
}
}

