import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.ExecutionException;

public class LockerManager {
    public static void main(String[] args) {
        Locker source = new Locker("Source", 100);
        Locker target = new Locker("Target", 0);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (int i = 0; i < 5; i++) {
            int quantity = new Random().nextInt(10) + 1;
            Future<Boolean> future = executor.submit(() -> moveParcels(
                source, target, quantity, 100, TimeUnit.MILLISECONDS
            ));

            try {
                Boolean result = future.get();
                System.out.println("Move completed: " + (result != null && result));
            } catch (InterruptedException | ExecutionException e) {
                System.err.println("Error during move operation: " + e.getMessage());
            }
        }

        executor.shutdown();
    }

    public static class Locker {
        private final String name;
        private final ReentrantLock lock = new ReentrantLock();
        private final AtomicInteger count;

        public Locker(String name, int initialCount) {
            this.name = name;
            this.count = new AtomicInteger(initialCount);
        }

        public String getName() {
            return name;
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public int getCount() {
            return count.get();
        }

        public void increment(int value) {
            count.addAndGet(value);
        }

        public void decrement(int value) {
            count.addAndGet(-value);
        }
    }

    public static class ParcelCount {
        private final Locker source;
        private final Locker target;

        public ParcelCount(Locker source, Locker target) {
            this.source = source;
            this.target = target;
        }

        public String toString() {
            return String.format("Source (%s): %d, Target (%s): %d",
                source.getName(), source.getCount(),
                target.getName(), target.getCount());
        }
    }

    public static class NotEnoughItemsException extends RuntimeException {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    private static int calculateFixedDelay(int attempts, int baseDelay) {
        return baseDelay * attempts;
    }

    private static int calculateRandomPause(int minPause, int maxPause) {
        Random random = new Random();
        return random.nextInt(maxPause - minPause + 1) + minPause;
    }

    public static boolean moveParcels(Locker source, Locker target, int quantity,
                                     long timeout, TimeUnit unit) {
        ReentrantLock sourceLock = source.getLock();
        ReentrantLock targetLock = target.getLock();

        try {
            long nanosTimeout = unit.toNanos(timeout);
            long deadline = System.nanoTime() + nanosTimeout;

            while (System.nanoTime() < deadline) {
                if (sourceLock.tryLock() && targetLock.tryLock()) {
                    if (source.getCount() >= quantity) {
                        source.decrement(quantity);
                        target.increment(quantity);
                        System.out.println("Moved " + quantity + " items from " +
                                         source.getName() + " to " + target.getName());
                        return true;
                    } else {
                        throw new NotEnoughItemsException(String.format(
                            "Not enough items in %s. Available: %d, Required: %d",
                            source.getName(), source.getCount(), quantity));
                    }
                }

                int fixedDelay = calculateFixedDelay(10, 10);
                int randomPause = calculateRandomPause(50, 200);
                Thread.sleep(fixedDelay + randomPause);
            }
        } catch (InterruptedException e) {
            return false;
        } finally {
            if (sourceLock.isHeldByCurrentThread()) sourceLock.unlock();
            if (targetLock.isHeldByCurrentThread()) targetLock.unlock();
        }

        return false;
    }
}

import java.util.concurrent.locks.Lock;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

public class LockerTransfer {
    static class Locker {
        Lock lock = new java.util.concurrent.locks.ReentrantLock();
        int count = 0; // Number of items in the locker

        Locker(int initialCount) {
            this.count = initialCount;
        }
    }

    public static boolean move(Locker source, Locker target, int quantity,
                               long timeout, TimeUnit unit) throws NotEnoughItemsException {
        long maxTotalTime = System.currentTimeMillis() + unit.toMillis(timeout);
        while (System.currentTimeMillis() < maxTotalTime) {
            if (!source.lock.tryLock()) { // Attempt to lock immediately
                try {
                    TimeUnit.MILLISECONDS.sleep(fixedDelay() + randomDelay());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return false;
                }
                continue;
            }
            try {
                if (!target.lock.tryLock()) {
                    source.lock.unlock(); // Release the source lock before retrying
                    continue; // Retry after delay
                }
                try {
                    if (source.count < quantity) {
                        throw new NotEnoughItemsException("Source locker does not have enough items.");
                    }
                    source.count -= quantity;
                    target.count += quantity;
                    return true;
                } finally {
                    target.lock.unlock();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); // Restore interrupted status
                return false;
            } finally {
                source.lock.unlock();
            }
        }
        return false; // Timed out after total timeout period
    }

    private static int fixedDelay() {
        return 100; // Fixed delay in milliseconds
    }

    private static int randomDelay() {
        return (int) (Math.random() * 500); // Random delay between 0 and 500 ms
    }

    public static class NotEnoughItemsException extends RuntimeException {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    public static void main(String[] args) {
        Locker source = new Locker(100); // Initial count: 100 items
        Locker target = new Locker(0);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<Boolean>> futures = new ArrayList<>();

        try {
            for (int i = 0; i < 5; i++) { // Submit multiple move tasks
                int qty = 10;
                Future<Boolean> future = executor.submit(() -> {
                    return move(source, target, qty, 2, TimeUnit.SECONDS);
                });
                futures.add(future);
            }

            for (Future<Boolean> future : futures) {
                try {
                    Boolean result = future.get();
                    System.out.println("Move completed: " + result);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                } catch (ExecutionException e) {
                    Throwable cause = e.getCause();
                    if (cause instanceof NotEnoughItemsException) {
                        System.err.println(cause.getMessage());
                    } else {
                        System.err.println("Task failed: " + cause);
                    }
                }
            }

        } finally {
            executor.shutdown();
        }
    }
}

import java.util.Random;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ParcelMover {
    private static class Locker {
        final Lock lock;
        final AtomicInteger parcelCount;

        Locker(int initialCount) {
            this.lock = new ReentrantLock();
            this.parcelCount = new AtomicInteger(initialCount);
        }
    }

    public static boolean move(Locker source, Locker target, int quantity, long timeout, TimeUnit timeUnit)
            throws NotEnoughItemsException {
        if (source == target || quantity <= 0) return true;

        Locker a = (source.hashCode() < target.hashCode()) ? source : target;
        Locker b = (source.hashCode() > target.hashCode()) ? source : target;

        Random random = new Random();
        int attempts = 0;
        long startTime = System.nanoTime();
        long timeoutNanos = timeUnit.toNanos(timeout);

        while (true) {
            long elapsedTime = System.nanoTime() - startTime;
            if (elapsedTime >= timeoutNanos) return false;

            long remainingTime = Math.max(1, timeoutNanos - elapsedTime);
            boolean acquiredA = a.lock.tryLock(remainingTime, TimeUnit.NANOSECONDS);
            if (!acquiredA) {
                long sleepTime = fixedDelayMs(attempts) + random.nextLong(randomDelayMs());
                try {
                    Thread.sleep(sleepTime);
                } catch (InterruptedException e) {
                    return false;
                }
                continue;
            }

            try {
                boolean acquiredB = b.lock.tryLock(0, TimeUnit.MILLISECONDS);
                if (!acquiredB) {
                    a.lock.unlock();
                    continue;
                }

                try {
                    int current = source.parcelCount.get();
                    if (current >= quantity) {
                        source.parcelCount.set(current - quantity);
                        target.parcelCount.addAndGet(quantity);
                        return true;
                    } else {
                        throw new NotEnoughItemsException("Not enough items in source locker");
                    }
                } finally {
                    b.lock.unlock();
                    a.lock.unlock();
                }
            } catch (InterruptedException e) {
                a.lock.unlock();
                Thread.currentThread().interrupt();
                return false;
            }
        }
    }

    private static long fixedDelayMs(int attempts) {
        int base = 250;
        return Math.min(1000, (long) base * Math.pow(2, attempts));
    }

    private static long randomDelayMs() {
        return new Random().nextLong(300);
    }

    public static void main(String[] args) throws InterruptedException {
        Locker source = new Locker(100);
        Locker target = new Locker(0);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        for (int i = 0; i < 5; i++) {
            executor.submit(() -> {
                try {
                    if (move(source, target, 10, 2, TimeUnit.SECONDS)) {
                        System.out.println("Moved successfully");
                    } else {
                        System.out.println("Move timed out");
                    }
                } catch (NotEnoughItemsException e) {
                    System.out.println(e.getMessage());
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);
    }

    public static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }
}

