import java.util.concurrent.TimeUnit;
import java.util.Random;

public class ContainerSwapper {
    static class ElementCount {
        int count = 0;
    }

    static class Container {
        ReentrantLock lock = new ReentrantLock();
        Object[] elements = new Object[10];
    }

    static class InsufficientElementsException extends RuntimeException {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }

    static boolean swap(Container origin, Container target, int numElements,
                        long timeout, TimeUnit unit) throws InterruptedException {
        Random random = new Random();
        long nanoTimeout = unit.toNanos(timeout);
        long deadline = System.nanoTime() + nanoTimeout;

        while (System.nanoTime() < deadline) {
            boolean firstLockAcquired = origin.lock.tryLock(50, TimeUnit.MILLISECONDS);
            if (!firstLockAcquired) continue;

            try {
                boolean secondLockAcquired = target.lock.tryLock(50, TimeUnit.MILLISECONDS);
                if (!secondLockAcquired) {
                    origin.lock.unlock();
                    continue;
                }

                try {
                    if (origin.count < numElements) {
                        throw new InsufficientElementsException("Origin container has insufficient elements");
                    }

                    for (int i = 0; i < numElements; i++) {
                        Object element = origin.elements[i];
                        target.elements[target.count++] = element;
                        origin.elements[i] = null;
                        origin.count--;
                    }

                    return true;
                } finally {
                    origin.lock.unlock();
                    target.lock.unlock();
                }
            } catch (InterruptedException e) {
                throw e;
            }
        }

        return false;
    }

    static long fixedDelay(long delay, TimeUnit unit) throws InterruptedException {
        unit.sleep(delay);
        return delay;
    }

    static long randomDelay(long maxDelay, TimeUnit unit) throws InterruptedException {
        Random random = new Random();
        long delay = random.nextInt((int) maxDelay);
        unit.sleep(delay);
        return delay;
    }

    public static void main(String[] args) throws Exception {
        Container container1 = new Container();
        Container container2 = new Container();

        Runnable task1 = () -> {
            try {
                while (true) {
                    if (!swap(container1, container2, 1, 1, TimeUnit.SECONDS)) {
                        System.out.println("Swap failed or timed out");
                    }
                    fixedDelay(500, TimeUnit.MILLISECONDS);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable task2 = () -> {
            try {
                while (true) {
                    if (!swap(container2, container1, 1, 1, TimeUnit.SECONDS)) {
                        System.out.println("Swap failed or timed out");
                    }
                    randomDelay(500, TimeUnit.MILLISECONDS);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        java.util.concurrent.ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.submit(task1);
        executor.submit(task2);

        try {
            TimeUnit.SECONDS.sleep(10);
        } finally {
            executor.shutdownNow();
            executor.awaitTermination(1, TimeUnit.SECONDS);
        }
    }
}

