        Container containerA = new Container();
        Container containerB = new Container();

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable swapTask1 = () -> {
            try {
                boolean success = swap(
                    containerA, containerB, 5,
                    100, TimeUnit.MILLISECONDS
                );
                System.out.println("Swap 1 completed: " + success);
            } catch (Exception e) {
                System.err.println("Swap 1 failed: " + e.getMessage());
            }
        };

        Runnable swapTask2 = () -> {
            try {
                boolean success = swap(
                    containerB, containerA, 3,
                    100, TimeUnit.MILLISECONDS
                );
                System.out.println("Swap 2 completed: " + success);
            } catch (Exception e) {
                System.err.println("Swap 2 failed: " + e.getMessage());
            }
        };

        Future<?> future1 = executor.submit(swapTask1);
