            future2.get();
        } catch (Exception e) {
            System.err.println("Main thread failed: " + e.getMessage());
        }

        executor.shutdown();
    }

    public static boolean swap(Container origin, Container target, int count,
                              long timeout, TimeUnit unit) throws InsufficientElementsException {
        ReentrantLock lock1 = getContainerLock(origin);
        ReentrantLock lock2 = getContainerLock(target);

        try {
            while (true) {
                if (lock1.tryLock(timeout, unit)) {
                    try {
                        if (lock2.tryLock()) {
                            try {
                                if (origin.getElements().size() < count) {
                                    throw new InsufficientElementsException();
                                }

                                List<Integer> elementsToSwap = new ArrayList<>();
                                for (int i = 0; i < count; i++) {
                                    elementsToSwap.add(origin.removeElement());
                                }

                                for (Integer element : elementsToSwap) {
                                    target.addElement(element);
                                }

                                return true;
                            } finally {
                                lock2.unlock();
                            }
                        }
                    } finally {
                        lock1.unlock();
                    }
                }

                long delay = calculateFixedDelay(50, 100) + 
