                Thread.sleep(delay);
            }
        } catch (InterruptedException e) {
            return false;
        }
    }

    private static ReentrantLock getContainerLock(Container container) {
        return container.getLock();
    }

    private static long calculateFixedDelay(long min, long max) {
        return Math.min(min, max);
