    public static boolean move(Bin source, Bin target, int numWidgets, long timeout, TimeUnit unit)
            throws NotEnoughWidgetsException {
        if (source == target) return true;

        ReentrantLock lock1 = source.lock;
        ReentrantLock lock2 = target.lock;

        long timeoutMillis = unit.toMillis(timeout);
        long deadline = System.currentTimeMillis() + timeoutMillis;

        while (System.currentTimeMillis() < deadline) {
            boolean acquired1 = lock1.tryLock();
            boolean acquired2 = lock2.tryLock();

            if (acquired1 && acquired2) {
                try {
                    if (source.count.get() >= numWidgets) {
                        source.count.set(source.count.get() - numWidgets);
                        target.count.set(target.count.get() + numWidgets);
                        return true;
                    } else {
                        throw new NotEnoughWidgetsException();
                    }
                } finally {
                    lock1.unlock();
                    lock2.unlock();
                }
            }

            if (!acquired1) {
                sleepWithRandomPause(timeoutMillis / 100);
            } else {
                sleepWithRandomPause(timeoutMillis / 100);
                lock1.unlock();
            }
        }

        return false;
    }

    private static void sleep(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static void sleepWithRandomPause(long maxMillis) {
        Random random = new Random();
        long pause = Math.abs(random.nextLong() % maxMillis);
