import java.util.Set;

public class ServerStatusBeforeSplit {
public final Set<String> users;
public final Set<String> queries;

public ServerStatusBeforeSplit() {
users = new HashSet<>();
queries = new HashSet<>();
}

public synchronized void addUser(String u) {
users.add(u);
}

public synchronized void addQuery(String q) {
queries.add(q);
}

public synchronized void removeUser(String u) {
users.remove(u);
}

public synchronized void removeQuery(String q) {
queries.remove(q);
}

public synchronized Set<String> getActiveUsers() {
return new HashSet<>(users);
}

public synchronized Set<String> getActiveQueries() {
return new HashSet<>(queries);
}

public static void main(String[] args) throws InterruptedException {
ServerStatusBeforeSplit status = new ServerStatusBeforeSplit();

Thread t1 = new Thread(() -> {
status.addUser("user1");
status.addQuery("query1");
try {
Thread.sleep(500);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
status.removeUser("user1");
status.removeQuery("query1");
});

Thread t2 = new Thread(() -> {
status.addUser("user2");
status.addQuery("query2");
try {
Thread.sleep(300);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
status.removeUser("user2");
status.removeQuery("query2");
});

t1.start();
t2.start();

t1.join();
t2.join();

System.out.println("Final active users: " + status.getActiveUsers());
System.out.println("Final active queries: " + status.getActiveQueries());
}
}

