    }
}

import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServerStatusBeforeSplit {
    private Set<String> vehicles = new HashSet<>();
    private Set<String> events = new HashSet<>();

    public ServerStatusBeforeSplit() {
        this.vehicles = new HashSet<>();
        this.events = new HashSet<>();
    }

    public synchronized void addUser(String u) {
        vehicles.add(u);
    }

    public synchronized void addQuery(String q) {
        events.add(q);
    }

    public synchronized boolean removeUser(String u) {
        return vehicles.remove(u);
    }

    public synchronized boolean removeQuery(String q) {
        return events.remove(q);
    }

    public static void main(String[] args) {
        final ServerStatusBeforeSplit server = new ServerStatusBeforeSplit();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        try {
            for (int i = 0; i < 2; i++) {
                int threadId = i;
                executor.submit(() -> {
                    String user = "user" + threadId;
                    String query = "query" + threadId;

                    server.addUser(user);
                    System.out.println("Added user: " + user);

                    try {
                        Thread.sleep(100);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }

                    server.addQuery(query);
                    System.out.println("Added query: " + query);

                    try {
                        Thread.sleep(100);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }

                    boolean userRemoved = server.removeUser(user);
                    System.out.println("Removed user: " + user + ", result: " + userRemoved);

                    try {
                        Thread.sleep(100);
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    }

                    boolean queryRemoved = server.removeQuery(query);
                    System.out.println("Removed query: " + query + ", result: " + queryRemoved);
                });
            }
        } finally {
            executor.shutdown();
        }
    }
}

