public class ServerStatusBeforeSplit {
    private final Set<String> users = new HashSet<>();
    private final Set<String> queries = new HashSet<>();

    public synchronized void addUser(String u) {
        users.add(u);
    }

    public synchronized void addQuery(String q) {
        queries.add(q);
    }

    public synchronized void removeUser(String u) {
        users.remove(u);
    }

    public synchronized void removeQuery(String q) {
        queries.remove(q);
    }

    public static void main(String[] args) {
        final ServerStatusBeforeSplit server = new ServerStatusBeforeSplit();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable userTask = () -> {
            try {
                while (true) {
                    String user = "User" + Math.random();
                    server.addUser(user);
                    System.out.println("Added user: " + user);
                    Thread.sleep(1000);
                    server.removeUser(user);
                    System.out.println("Removed user: " + user);
                    Thread.sleep(1000);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable queryTask = () -> {
            try {
                while (true) {
                    String query = "Query" + Math.random();
                    server.addQuery(query);
                    System.out.println("Added query: " + query);
                    Thread.sleep(1500);
                    server.removeQuery(query);
                    System.out.println("Removed query: " + query);
                    Thread.sleep(1500);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        executor.execute(userTask);
        executor.execute(queryTask);

        try {
            while (!Thread.currentThread().isInterrupted()) {
                Thread.sleep(100);
            }
        } catch (InterruptedException e) {
            System.out.println("Main thread interrupted");
            executor.shutdownNow();
        }
    }
}

