import java.util.HashSet;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PersonSet {
    private final Set<Person> persons = new HashSet<>();

    public interface Person {
        String getName();
    }

    public synchronized void insert(Person person) {
        persons.add(person);
    }

    public synchronized boolean contains(Person person) {
        for (Person p : persons) {
            if (p.getName().equals(person.getName())) {
                return true;
            }
        }
        return false;
    }

    public static void main(String[] args) {
        PersonSet personSet = new PersonSet();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            for (int i = 1; i <= 5; i++) {
                String name = "Thread-1-Count-" + i;
                Person person = new Person() {
                    @Override
                    public String getName() {
                        return name;
                    }
                };
                personSet.insert(person);
                boolean exists = personSet.contains(person);
                System.out.println("Thread 1: Inserted and checked for " + name + ". Exists: " + exists);
            }
        };

        Runnable task2 = () -> {
            for (int i = 1; i <= 5; i++) {
                String name = "Thread-2-Count-" + i;
                Person person = new Person() {
                    @Override
                    public String getName() {
                        return name;
                    }
                };
                personSet.insert(person);
                boolean exists = personSet.contains(person);
                System.out.println("Thread 2: Inserted and checked for " + name + ". Exists: " + exists);
            }
        };

        executor.submit(task1);
        executor.submit(task2);

        executor.shutdown();
    }
}

