import java.util.HashSet;
import java.util.Set;

public class PersonSet {
    private final Set<Person> persons = new HashSet<>();

    public synchronized void register(Person person) {
        persons.add(person);
    }

    public synchronized boolean contains(Person person) {
        return persons.contains(person);
    }

    interface Person {
        String getName();
        int getAge();
    }

    public static void main(String[] args) throws InterruptedException {
        final PersonSet set = new PersonSet();

        Thread thread1 = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                try {
                    set.register(new Person() {
                        @Override
                        public String getName() { return "Alice"; }
                        @Override
                        public int getAge() { return 30; }
                    });
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        Thread thread2 = new Thread(() -> {
            for (int i = 0; i < 5; i++) {
                try {
                    set.register(new Person() {
                        @Override
                        public String getName() { return "Bob"; }
                        @Override
                        public int getAge() { return 25; }
                    });
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        thread1.start();
        thread2.start();

        thread1.join();
        thread2.join();

        System.out.println("Total persons registered: " + set.persons.size());
        System.out.println("Contains Alice? " + set.contains(new Person() {
            @Override
            public String getName() { return "Alice"; }
            @Override
            public int getAge() { return 30; }
