        Thread t1 = new Thread(updater);
        Thread t2 = new Thread(retriever);
        Thread t3 = new Thread(remover);

        t1.start();
        t2.start();
        t3.start();

        try {
            t1.join();
            t2.join();
            t3.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
