import java.util.Collections;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PublishingVehicleTracker {
    private final ConcurrentHashMap<String, SafePoint> vehiclePositions = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        PublishingVehicleTracker tracker = new PublishingVehicleTracker();
        ExecutorService executor = Executors.newFixedThreadPool(2);
        try (var scanner = new java.util.Scanner(System.in)) {
            while (true) {
                System.out.print("Enter command: ");
                String input = scanner.nextLine().trim();
                if ("exit".equalsIgnoreCase(input)) break;
                String[] parts = input.split("\\s+");
                executor.submit(() -> processCommand(tracker, parts));
            }
        } finally {
            executor.shutdown();
        }
    }

    private static void processCommand(PublishingVehicleTracker tracker, String[] parts) {
        try {
            switch (parts[0].toLowerCase()) {
                case "add":
                    if (parts.length < 4) throw new IllegalArgumentException("Invalid add command");
                    String id = parts[1];
                    int x = Integer.parseInt(parts[2]);
                    int y = Integer.parseInt(parts[3]);
                    tracker.updatePosition(id, x, y);
                    System.out.println("Vehicle added: " + id);
                    break;
                case "update":
                    if (parts.length < 4) throw new IllegalArgumentException("Invalid update command");
                    id = parts[1];
                    x = Integer.parseInt(parts[2]);
                    y = Integer.parseInt(parts[3]);
                    tracker.updatePosition(id, x, y);
                    System.out.println("Updated position for: " + id);
                    break;
                case "get":
                    if (parts.length < 2) throw new IllegalArgumentException("Invalid get command");
                    id = parts[1];
                    SafePoint point = tracker.getPosition(id);
                    System.out.println("Position of " + id + ": (" + point.x() + ", " + point.y() + ")");
                    break;
                case "print":
                    System.out.println(tracker.getFullMap());
                    break;
                default:
                    throw new IllegalArgumentException("Unknown command");
            }
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        } catch (Exception e) {
            System.err.println("Error processing command: " + e.getMessage());
        }
    }

    public java.util.Map<String, SafePoint> getFullMap() {
        return Collections.unmodifiableMap(new ConcurrentHashMap<>(vehiclePositions));
    }

    public SafePoint getPosition(String id) {
        if (!vehiclePositions.containsKey(id)) throw new IllegalArgumentException("Vehicle not found");
        return vehiclePositions.get(id);
    }

    public void updatePosition(String id, int x, int y) {
        if (!vehiclePositions.containsKey(id)) throw new IllegalArgumentException("Vehicle does not exist");
        vehiclePositions.put(id, new SafePoint(x, y));
    }
}

