import java.util.Map;

public class PublishingVehicleTracker {
    private final Map<String, SafePoint> vehicleMap = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        PublishingVehicleTracker tracker = new PublishingVehicleTracker();
        tracker.addTestVehicles();

        Runnable updaterTask = () -> {
            try {
                while (!Thread.currentThread().isInterrupted()) {
                    tracker.updateLocation("vehicle1", (int)(Math.random() * 100), (int)(Math.random() * 100));
                    tracker.updateLocation("vehicle2", (int)(Math.random() * 100), (int)(Math.random() * 100));
                    Thread.sleep(500);
                }
            } catch (InterruptedException e) {
                System.out.println("Updater thread interrupted");
            }
        };

        Runnable printerTask = () -> {
            try {
                while (!Thread.currentThread().isInterrupted()) {
                    System.out.println("Current vehicle locations: " + tracker.getFullState());
                    Thread.sleep(1000);
                }
            } catch (InterruptedException e) {
                System.out.println("Printer thread interrupted");
            }
        };

        Thread updater = new Thread(updaterTask);
        Thread printer = new Thread(printerTask);

        updater.start();
        printer.start();

        try {
            updater.join();
            printer.join();
        } catch (InterruptedException e) {
            System.out.println("Main thread interrupted");
        }
    }

    private void addTestVehicles() {
        vehicleMap.put("vehicle1", new SafePoint(0, 0));
        vehicleMap.put("vehicle2", new SafePoint(50, 50));
    }

