        return Collections.unmodifiableMap(new CopyOnWriteArrayList<>(vehicleMap.entrySet()).stream()
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue)));
    }

    public SafePoint getLocation(String vehicleId) {
        if (!vehicleMap.containsKey(vehicleId)) {
            throw new IllegalArgumentException("Vehicle not found");
        }
        return vehicleMap.get(vehicleId);
    }

    public void updateLocation(String vehicleId, int x, int y) {
        if (!vehicleMap.containsKey(vehicleId)) {
            throw new IllegalArgumentException("Vehicle not found");
        }
        vehicleMap.put(vehicleId, new SafePoint(x, y));
    }

    private static class SafePoint {
        private final int x;
        private final int y;

        public SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "SafePoint{" +
