import java.util.Collections;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PublishingVehicleTracker {
    private final Map<String, SafePoint> vehicleMap = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        PublishingVehicleTracker tracker = new PublishingVehicleTracker();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            try {
                tracker.updateVehicleWhereabouts("car1", 10, 20);
                Thread.sleep(500);
                SafePoint point = tracker.getVehicleWhereabouts("car1");
                System.out.println("Task1: car1 is at (" + point.x + ", " + point.y + ")");
            } catch (InterruptedException | IllegalArgumentException e) {
                e.printStackTrace();
            }
        };

        Runnable task2 = () -> {
            try {
                tracker.updateVehicleWhereabouts("car2", 30, 40);
                Thread.sleep(1000);
                SafePoint point = tracker.getVehicleWhereabouts("car2");
                System.out.println("Task2: car2 is at (" + point.x + ", " + point.y + ")");
            } catch (InterruptedException | IllegalArgumentException e) {
                e.printStackTrace();
            }
        };

        executor.execute(task1);
        executor.execute(task2);

        try {
            executor.shutdown();
            executor.awaitTermination(1, java.util.concurrent.TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        Map<String, SafePoint> fullMap = tracker.getFullMap();
        System.out.println("Final vehicle locations: " + fullMap);
    }

    public Map<String, SafePoint> getFullMap() {
        return Collections.unmodifiableMap(vehicleMap);
    }

    public SafePoint getVehicleWhereabouts(String id) throws IllegalArgumentException {
        if (id == null || id.isEmpty()) {
            throw new IllegalArgumentException("Invalid vehicle ID");
        }
        return vehicleMap.get(id);
    }

    public void updateVehicleWhereabouts(String id, int x, int y) throws IllegalArgumentException {
        if (id == null || id.isEmpty()) {
            throw new IllegalArgumentException("Invalid vehicle ID");
        }

        vehicleMap.computeIfPresent(id, (k, v) -> {
            return new SafePoint(x, y);
        });

        if (!vehicleMap.containsKey(id)) {
            throw new IllegalArgumentException("Vehicle with ID " + id + " does not exist.");
        }
    }

    private static class SafePoint {
        final int x;
        final int y;

        SafePoint(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }
}
