import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

class Secrets {
private static final Set<Secret> knownSecrets = ConcurrentHashMap.newKeySet();

public static Set<Secret> getKnownSecrets() {
return knownSecrets;
}
}

class Secret {
private final String content;

public Secret(String content) {
this.content = content;
}

@Override
public String toString() {
return "Secret{" +
"content='" + content + '\'' +
'}';
}
}

public class SecretsMain {

public static void main(String[] args) throws InterruptedException {
Thread t1 = new Thread(() -> {
Secret secret = new Secret("secret-1");
Secrets.getKnownSecrets().add(secret);
System.out.println(Thread.currentThread().getName() + " added: " + secret);
});

Thread t2 = new Thread(() -> {
Secret secret = new Secret("secret-2");
Secrets.getKnownSecrets().add(secret);
System.out.println(Thread.currentThread().getName() + " added: " + secret);
});

t1.start();
t2.start();

t1.join();
t2.join();

System.out.println("All secrets:");
for (Secret secret : Secrets.getKnownSecrets()) {
System.out.println(secret);
}

System.out.println("Program finished.");
}
}

