                new Rune(a, Resonance.POSITIVE),
                new Rune(a, Resonance.POSITIVE),
                new Rune(a, Resonance.NEGATIVE),
                new Rune(a, Resonance.NEGATIVE),
                new Rune(b, Resonance.POSITIVE)
        );

        Grimoire grimoire = new Grimoire();

        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Sorting task
        Future<?> sortFuture = executor.submit(() -> {
            Collections.sort(runes, (r1, r2) -> {
                int cmp = r1.getConstellation().compareTo(r2.getConstellation());
                if (cmp != 0) return cmp;
