import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ExecutionException;

public class HarmonyCounter {

    public static int countHarmonies(List<Rune> runeList) {
        if (runeList == null || runeList.isEmpty()) {
            return 0;
        }

        // Step 1: Sort the runes by constellation and then by resonance
        List<Rune> sortedRunes = new ArrayList<>(runeList);
        Collections.sort(sortedRunes, (r1, r2) -> {
            int constellationCompare = r1.constellation().compareTo(r2.constellation());
            if (constellationCompare != 0) {
                return constellationCompare;
            }
            return r1.resonance().compareTo(r2.resonance());
        });

        // Step 2: Group the runes by their constellation
        List<Group> groups = new ArrayList<>();
        if (!sortedRunes.isEmpty()) {
            Group currentGroup = new Group(sortedRunes.get(0).constellation());
            currentGroup.addRune(sortedRunes.get(0));
            for (int i = 1; i < sortedRunes.size(); i++) {
                Rune rune = sortedRunes.get(i);
                if (rune.constellation().equals(currentGroup.constellation())) {
                    currentGroup.addRune(rune);
                } else {
                    groups.add(currentGroup);
                    currentGroup = new Group(rune.constellation());
                    currentGroup.addRune(rune);
                }
            }
            groups.add(currentGroup); // Add the last group
        }

        // Step 3: Split the groups into two batches for parallel processing
        int mid = groups.size() / 2;
        List<Group> firstBatch = new ArrayList<>(groups.subList(0, mid));
        List<Group> secondBatch = new ArrayList<>(groups.subList(mid, groups.size()));

        // Step 4: Use ExecutorService to process each batch in parallel
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<Integer> future1 = executor.submit(() -> countHarmoniesInGroups(firstBatch));
        Future<Integer> future2 = executor.submit(() -> countHarmoniesInGroups(secondBatch));

        int total;
        try {
            int result1 = future1.get();
            int result2 = future2.get();
            total = result1 + result2;
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Error processing harmonies", e);
        } finally {
            executor.shutdown();
        }

        return total;
    }

    private static int countHarmoniesInGroups(List<Group> groups) {
        int count = 0;
        for (Group group : groups) {
            List<Rune> runes = group.runes();
            for (int i = 0; i < runes.size() - 1; i++) {
                Rune current = runes.get(i);
                Rune next = runes.get(i + 1);
                if (!current.resonance().equals(next.resonance())) {
                    count++;
                }
            }
        }
        return count;
    }

    // Inner class to represent a group of runes with the same constellation
    private static class Group {
        private final Constellation constellation;
        private List<Rune> runes;

        public Group(Constellation c) {
            this.constellation = c;
            runes = new ArrayList<>();
        }

        public void addRune(Rune rune) {
            runes.add(rune);
        }

        public Constellation constellation() {
            return constellation;
        }

        public List<Rune> runes() {
            return runes;
        }
    }

    // Helper class for Rune
    static class Rune {
        private final Constellation constellation;
        private final Resonance resonance;

        public Rune(Constellation c, Resonance r) {
            this.constellation = c;
            this.resonance = r;
        }

        public Constellation constellation() { return constellation; }
        public Resonance resonance() { return resonance; }
    }

    // Helper enum for Resonance
    static enum Resonance {
        POSITIVE, NEGATIVE;
    }

    // Helper enum for Constellation
    static enum Constellation {
        A, B, C, D;
    }
}

import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class Main {
    public static void main(String[] args) throws ExecutionException, InterruptedException {
        List<Rune> runes = initializeRunes();
        int count = channelTheGrimoire(runes);
        System.out.println("Total harmonies: " + count);
    }

    private static int channelTheGrimoire(List<Rune> runes) throws ExecutionException, InterruptedException {
        ExecutorService service = Executors.newFixedThreadPool(2);

        // Sort the runes by constellation and then by resonance
        Future<List<Rune>> sortFuture = service.submit(() -> {
            List<Rune> sortedRunes = new java.util.ArrayList<>(runes);
            Collections.sort(sortedRunes, (r1, r2) -> {
                int cmp = r1.getConstellation().compareTo(r2.getConstellation());
                if (cmp != 0) return cmp;
                return r1.getResonance().compareTo(r2.getResonance());
            });
            return sortedRunes;
        });

        List<Rune> sortedRunes = sortFuture.get();

        // Count valid harmonies and populate the Grimoire
        Future<Integer> countFuture = service.submit(() -> {
            Grimoire grimoire = new Grimoire();
            int count = 0;
            for (int i = 0; i < sortedRunes.size(); ) {
                if (i + 1 >= sortedRunes.size()) break;
                Rune r1 = sortedRunes.get(i);
                Rune r2 = sortedRunes.get(i + 1);
                if (r1.getConstellation() == r2.getConstellation() && 
                    r1.getResonance().oppositeOf(r2.getResonance())) {
                    grimoire.addHarmony(new Harmony(r1, r2));
                    count++;
                    i += 2;
                } else {
                    i++;
                }
            }
            return count;
        });

        int total = countFuture.get();
        service.shutdown();
        return total;
    }

    private static List<Rune> initializeRunes() {
        List<Rune> runes = new java.util.ArrayList<>();
        runes.add(new Rune(Constellation.ARIES, Resonance.POSITIVE));
        runes.add(new Rune(Constellation.ARIES, Resonance.NEGATIVE));
        runes.add(new Rune(Constellation.TAURUS, Resonance.POSITIVE));
        runes.add(new Rune(Constellation.TAURUS, Resonance.NEGATIVE));
        return runes;
    }

    public enum Constellation {
        ARIES, TAURUS;
    }

    public enum Resonance {
        POSITIVE, NEGATIVE;

        public boolean oppositeOf(Resonance other) {
            return (this == POSITIVE && other == NEGATIVE) || (this == NEGATIVE && other == POSITIVE);
        }
    }

    static class Rune {
        private Constellation constellation;
        private Resonance resonance;

        public Rune(Constellation constellation, Resonance resonance) {
            this.constellation = constellation;
            this.resonance = resonance;
        }

        public Constellation getConstellation() { return constellation; }
        public Resonance getResonance() { return resonance; }
    }

    static class Harmony {
        private Rune rune1;
        private Rune rune2;

        public Harmony(Rune rune1, Rune rune2) {
            this.rune1 = rune1;
            this.rune2 = rune2;
        }
    }

    static class Grimoire {
        private java.util.List<Harmony> harmonies = new java.util.ArrayList<>();

        public void addHarmony(Harmony harmony) {
            harmonies.add(harmony);
        }

        public int getCount() {
            return harmonies.size();
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;

public class HarmonyCalculator {
    public static int calculateHarmonies(List<Rune> runes) {
        if (runes.isEmpty()) {
            return 0;
        }

        // Create a copy of the list to avoid modifying the original
        List<Rune> sortedRunes = new ArrayList<>(runes);

        // Sort runestones by constellation, then by resonance (positive first)
        Collections.sort(sortedRunes, Comparator.comparing(Rune::getConstellation)
                .thenComparing(Rune::getResonance));

        // Group the sorted runestones by their constellations
        List<List<Rune>> groups = new ArrayList<>();
        Rune previous = sortedRunes.get(0);
        List<Rune> currentGroup = new ArrayList<>();
        currentGroup.add(previous);

        for (int i = 1; i < sortedRunes.size(); i++) {
            Rune current = sortedRunes.get(i);
            if (current.constellation == previous.constellation) {
                currentGroup.add(current);
            } else {
                groups.add(currentGroup);
                currentGroup = new ArrayList<>();
                currentGroup.add(current);
            }
            previous = current;
        }
        // Add the last group
        if (!currentGroup.isEmpty()) {
            groups.add(currentGroup);
        }

        // Use a thread pool to process each group concurrently, up to 2 threads
        ExecutorService executor = Executors.newFixedThreadPool(2);
        AtomicInteger harmonyCount = new AtomicInteger();

        for (List<Rune> group : groups) {
            Runnable task = () -> {
                int positive = 0;
                int negative = 0;
                for (Rune rune : group) {
                    if (rune.resonance == Resonance.POSITIVE) {
                        positive++;
                    } else {
                        negative++;
                    }
                }
                int harmonies = Math.min(positive, negative);
                harmonyCount.addAndGet(harmonies);
            };
            executor.execute(task);
        }

        // Shutdown the executor and wait for all tasks to complete
        executor.shutdown();
        while (!executor.isTerminated()) {
            // Wait for completion
        }

        return harmonyCount.get();
    }
}

class Rune {
    Constellation constellation;
    Resonance resonance;

    public Rune(Constellation constellation, Resonance resonance) {
        this.constellation = constellation;
        this.resonance = resonance;
    }

    public Constellation getConstellation() {
        return constellation;
    }

    public Resonance getResonance() {
        return resonance;
    }
}

