To solve this problem, we need to count the number of harmonies formed by consecutive runes with opposite resonances within the same constellation. Each harmony is identified when two consecutive runes have different resonances.

### Approach
1. **Sort Runes**: First, we sort the list of runes by their constellation and then by their resonance. This ensures that all runes of the same constellation are grouped together and ordered by their resonance.
2. **Group Runes**: After sorting, we group the runes by their constellation. Each group will contain all runes belonging to a specific constellation.
3. **Parallel Processing**: We split these groups into two batches and use parallel processing (with two threads) to count the harmonies in each batch efficiently.
4. **Count Harmonies**: For each group of runes, we check consecutive pairs to see if they form a harmony (i.e., have opposite resonances). The total number of harmonies is the sum from both processed batches.

### Solution Code
```java
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ExecutionException;

public class HarmonyCounter {

    public static int countHarmonies(List<Rune> runeList) {
        if (runeList == null || runeList.isEmpty()) {
            return 0;
        }

        // Step 1: Sort the runes by constellation and then by resonance
        List<Rune> sortedRunes = new ArrayList<>(runeList);
        Collections.sort(sortedRunes, (r1, r2) -> {
            int constellationCompare = r1.constellation().compareTo(r2.constellation());
            if (constellationCompare != 0) {
                return constellationCompare;
            }
            return r1.resonance().compareTo(r2.resonance());
        });

        // Step 2: Group the runes by their constellation
        List<Group> groups = new ArrayList<>();
        if (!sortedRunes.isEmpty()) {
            Group currentGroup = new Group(sortedRunes.get(0).constellation());
            currentGroup.addRune(sortedRunes.get(0));
            for (int i = 1; i < sortedRunes.size(); i++) {
                Rune rune = sortedRunes.get(i);
                if (rune.constellation().equals(currentGroup.constellation())) {
                    currentGroup.addRune(rune);
                } else {
                    groups.add(currentGroup);
                    currentGroup = new Group(rune.constellation());
                    currentGroup.addRune(rune);
                }
            }
            groups.add(currentGroup); // Add the last group
        }

        // Step 3: Split the groups into two batches for parallel processing
        int mid = groups.size() / 2;
        List<Group> firstBatch = new ArrayList<>(groups.subList(0, mid));
        List<Group> secondBatch = new ArrayList<>(groups.subList(mid, groups.size()));

        // Step 4: Use ExecutorService to process each batch in parallel
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<Integer> future1 = executor.submit(() -> countHarmoniesInGroups(firstBatch));
        Future<Integer> future2 = executor.submit(() -> countHarmoniesInGroups(secondBatch));

        int total;
        try {
            int result1 = future1.get();
            int result2 = future2.get();
            total = result1 + result2;
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Error processing harmonies", e);
        } finally {
            executor.shutdown();
        }

        return total;
    }

    private static int countHarmoniesInGroups(List<Group> groups) {
        int count = 0;
        for (Group group : groups) {
            List<Rune> runes = group.runes();
            for (int i = 0; i < runes.size() - 1; i++) {
                Rune current = runes.get(i);
                Rune next = runes.get(i + 1);
                if (!current.resonance().equals(next.resonance())) {
                    count++;
                }
            }
        }
        return count;
    }

    // Inner class to represent a group of runes with the same constellation
    private static class Group {
        private final Constellation constellation;
        private List<Rune> runes;

        public Group(Constellation c) {
            this.constellation = c;
            runes = new ArrayList<>();
        }

        public void addRune(Rune rune) {
            runes.add(rune);
        }

        public Constellation constellation() {
            return constellation;
        }

        public List<Rune> runes() {
            return runes;
        }
    }

    // Helper class for Rune
    static class Rune {
        private final Constellation constellation;
        private final Resonance resonance;

        public Rune(Constellation c, Resonance r) {
            this.constellation = c;
            this.resonance = r;
        }

        public Constellation constellation() { return constellation; }
        public Resonance resonance() { return resonance; }
    }

    // Helper enum for Resonance
    static enum Resonance {
        POSITIVE, NEGATIVE;
    }

    // Helper enum for Constellation
    static enum Constellation {
        A, B, C, D;
    }
}
