        initialPerches.put("A", new Glyph(1, 2));
        initialPerches.put("B", new Glyph(3, 4));

        MysticBeastTracker tracker = new MysticBeastTracker(initialPerches);

        ExecutorService executor = Executors.newFixedThreadPool(5);

        for (int i = 0; i < 5; i++) {
            final int spark = i * 2;
            final int glimmer = i * 3;
            String sigil = String.valueOf((char) ('A' + i));

