                        Glyph perch = tracker.getPerch(sigil);
                        System.out.println("Got " + sigil + ": " + (perch != null ? perch : "null"));
                    }
                } catch (IllegalArgumentException e) {
                    System.err.println(e.getMessage());
                }
            });
        }

        executor.shutdown();
    }
}
