import java.util.Collections;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CelestialCaravanTracker {
    private final Map<String, Starlight> havensMap = new ConcurrentHashMap<>();

    public CelestialCaravanTracker(Map<String, Starlight> initialHavens) {
        if (initialHavens != null) {
            havensMap.putAll(initialHavens);
        }
    }

    public Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(havensMap);
    }

    public Starlight getHaven(String glyph) {
        return havensMap.get(glyph);
    }

    public void setHaven(String glyph, int shimmer, int pulse) {
        if (!havensMap.computeIfPresent(glyph, (k, v) -> new Starlight(shimmer, pulse))) {
            throw new IllegalArgumentException("Beast with glyph '" + glyph + "' does not exist.");
        }
    }

    public Map<String, Starlight> getHavensAsStatic() {
        return Collections.unmodifiableMap(ConcurrentHashMap.copyOf(havensMap));
    }

    public static class Starlight {
        private final int shimmer;
        private final int pulse;

        public Starlight(int shimmer, int pulse) {
            this.shimmer = shimmer;
            this.pulse = pulse;
        }

        @Override
