            return "Starlight{" +
                   "shimmer=" + shimmer +
                   ", pulse=" + pulse +
                   '}';
        }
    }

    public static void main(String[] args) {
        Map<String, Starlight> initialHavens = Map.of(
                "A", new Starlight(10, 20),
                "B", new Starlight(30, 40)
