import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CelestialCaravanTracker {
    private final ConcurrentHashMap<String, Starlight> internalMap;

    public CelestialCaravanTracker(Map<String, Starlight> initialHavens) {
        this.internalMap = new ConcurrentHashMap<>(initialHavens);
    }

    public Map<String, Starlight> getHavens() {
        return Collections.unmodifiableMap(internalMap);
    }

    public Starlight getHaven(String glyph) {
        return internalMap.get(glyph);
    }

    public void setHaven(String glyph, int shimmer, int pulse) {
        if (!internalMap.computeIfPresent(glyph, (key, value) -> new Starlight(shimmer, pulse))) {
            throw new IllegalArgumentException("Beast with glyph '" + glyph + "' does not exist.");
        }
    }

    public Map<String, Starlight> getHavensAsStatic() {
        ConcurrentHashMap<String, Starlight> snapshot = (ConcurrentHashMap<String, Starlight>) internalMap.clone();
        return Collections.unmodifiableMap(snapshot);
    }

    public static class Starlight {
        private final int shimmer;
        private final int pulse;

        public Starlight(int shimmer, int pulse) {
            this.shimmer = shimmer;
            this.pulse = pulse;
        }

        @Override
        public String toString() {
            return "Starlight{" +
                   "shimmer=" + shimmer +
                   ", pulse=" + pulse +
                   '}';
        }
    }

    public static void main(String[] args) {
        Map<String, Starlight> initialHavens = new HashMap<>();
        initialHavens.put("glyph1", new Starlight(10, 20));
        initialHavens.put("glyph2", new Starlight(30, 40));

        CelestialCaravanTracker tracker = new CelestialCaravanTracker(initialHavens);
        ExecutorService executorService = Executors.newFixedThreadPool(5);

        Runnable updateTask1 = () -> {
            try {
                tracker.setHaven("glyph1", 100, 200);
                System.out.println("Updated glyph1 to (100, 200)");
            } catch (IllegalArgumentException e) {
                System.err.println(e.getMessage());
            }
        };

        Runnable updateTask2 = () -> {
            try {
                tracker.setHaven("glyph2", 300, 400);
                System.out.println("Updated glyph2 to (300, 400)");
            } catch (IllegalArgumentException e) {
                System.err.println(e.getMessage());
            }
        };

        Runnable getTask = () -> {
            Map<String, Starlight> currentHavens = tracker.getHavens();
            System.out.println("Current havens: " + currentHavens);
        };

        Runnable staticSnapshotTask = () -> {
            Map<String, Starlight> snapshot = tracker.getHavensAsStatic();
            System.out.println("Static snapshot: " + snapshot);
        };

        Runnable errorTask = () -> {
            try {
                tracker.setHaven("nonexistent", 50, 60);
            } catch (IllegalArgumentException e) {
                System.err.println("Error: " + e.getMessage());
            }
        };

        executorService.execute(updateTask1);
        executorService.execute(updateTask2);
        executorService.execute(getTask);
        executorService.execute(staticSnapshotTask);
        executorService.execute(errorTask);

        executorService.shutdown();
    }
}
