import java.util.concurrent.*;

/**
* Preloader
*
* Using FutureTask to preload data that is needed later
*
* @author Brian Goetz and Tim Peierls
*/
public class Preloader {
// Simulate product information loading
ProductInfo loadProductInfo() throws DataLoadException {
try {
Thread.sleep(2000); // Simulate loading delay
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
throw new DataLoadException();
}
return new ProductInfoImpl("Awesome Product", 99.99);
}

private final FutureTask<ProductInfo> future =
new FutureTask<>(new Callable<ProductInfo>() {
public ProductInfo call() throws DataLoadException {
return loadProductInfo();
}
});
private final Thread thread = new Thread(future);

public void start() {
thread.start();
}

public ProductInfo get() throws DataLoadException, InterruptedException {
try {
return future.get();
} catch (ExecutionException e) {
Throwable cause = e.getCause();
if (cause instanceof DataLoadException)
throw (DataLoadException) cause;
else
throw LaunderThrowable.launderThrowable(cause);
}
}

interface ProductInfo {
String getName();
double getPrice();
}

static class ProductInfoImpl implements ProductInfo {
private final String name;
private final double price;

public ProductInfoImpl(String name, double price) {
this.name = name;
this.price = price;
}

public String getName() {
return name;
}

public double getPrice() {
return price;
}

@Override
public String toString() {
return "ProductInfo{name='" + name + "', price=" + price + "}";
}
}

// Utility class: for throwing unchecked exceptions
static class LaunderThrowable {
static RuntimeException launderThrowable(Throwable t) {
if (t instanceof RuntimeException)
return (RuntimeException) t;
else if (t instanceof Error)
throw (Error) t;
else
throw new IllegalStateException("Not unchecked", t);
}
}

// Main entry point
public static void main(String[] args) {
System.out.println("Starting preloader...");
Preloader preloader = new Preloader();
preloader.start();

try {
System.out.println("Doing something else in the main thread...");
Thread.sleep(1000);

System.out.println("Waiting for product info...");
ProductInfo productInfo = preloader.get();
System.out.println("Loaded product: " + productInfo);
} catch (DataLoadException | InterruptedException e) {
e.printStackTrace();
}
}
}

class DataLoadException extends Exception {
public DataLoadException() {
super("Failed to load product data.");
}
}

