import java.util.concurrent.FutureTask;
import java.util.concurrent.ExecutionException;
import java.util.Random;

public interface Relic {
    // Placeholder for summoned data
}

class RelicCastException extends Exception {
    public RelicCastException(String message) {
        super(message);
    }
}

class PhantomLoader {
    private FutureTask<Relic> futureTask;
    private volatile boolean started;

    public void loadRelic() throws RelicCastException {
        try {
            Thread.sleep(1000); // Simulate a 1-second delay
        } catch (InterruptedException e) {
            throw new RelicCastException("Summoning interrupted");
        }
        return createRelic();
    }

    private Relic createRelic() throws RelicCastException {
        Random random = new Random();
        if (random.nextBoolean()) {
            // Simulate successful creation of a relic
            return new Object() implements Relic {}; // Mock implementation for demonstration
        } else {
