        }
        futureTask = new FutureTask<>(new Callable<Relic>() {
            @Override
            public Relic call() throws Exception {
                return loadRelic();
            }
        });
        Thread backgroundThread = new Thread(futureTask);
        backgroundThread.start();
        started = true;
    }

    public Relic get() throws RelicCastException {
        if (futureTask == null) {
            throw new IllegalStateException("Summoning task has not been started");
        }
        try {
