import java.util.*;
import java.util.concurrent.*;

public class Enchanter {
    interface Talisman {
        int getValue();
    }

    interface SigilNode {
        Talisman compute();
        List<SigilNode> children();
    }

    public static class SimpleTalisman implements Talisman {
        private final int value;

        public SimpleTalisman(int value) {
            this.value = value;
        }

        @Override
        public int getValue() {
            return value;
        }
    }

    public static class SimpleSigilNode implements SigilNode {
        private final Talisman talisman;
        private final List<SigilNode> children;

        public SimpleSigilNode(Talisman talisman, List<SigilNode> children) {
            this.talisman = talisman;
            this.children = children;
        }

        @Override
        public Talisman compute() {
            return talisman;
        }

        @Override
        public List<SigilNode> children() {
            return children;
        }
    }

    private final ExecutorService executor;

    public Enchanter(ExecutorService executor) {
        this.executor = executor;
    }

    public List<Integer> sequentialWeave(List<Talisman> talismans) {
        List<Integer> results = new ArrayList<>();
        for (Talisman talisman : talismans) {
            results.add(talisman.getValue());
        }
        return results;
    }

    public CompletableFuture<List<Integer>> parallelConjure(List<Talisman> talismans) {
        CompletionService<Integer> completionService = new ExecutorCompletionService<>(executor);
        List<Future<Integer>> futures = new ArrayList<>();

        for (Talisman talisman : talismans) {
            futures.add(completionService.submit(() -> talisman.getValue()));
        }

        return CompletableFuture.supplyAsync(() -> {
            List<Integer> results = new ArrayList<>();
            for (Future<Integer> future : futures) {
                results.add(future.get());
            }
            return results;
        }, executor);
    }

    public int recursiveWeave(SigilNode node) {
        int result = node.compute().getValue();
        for (SigilNode child : node.children()) {
            result += recursiveWeave(child);
        }
        return result;
    }

    private CompletableFuture<Integer> processNode(SigilNode node, ExecutorService executor) {
        CompletableFuture<Integer> future = new CompletableFuture<>();
        executor.submit(() -> {
            try {
                int value = node.compute().getValue();
                List<CompletableFuture<Integer>> childFutures = new ArrayList<>();
                for (SigilNode child : node.children()) {
                    childFutures.add(processNode(child, executor));
                }
                int sum = value;
                for (CompletableFuture<Integer> childFuture : childFutures) {
                    sum += childFuture.get();
                }
                future.complete(sum);
            } catch (Exception e) {
                future.completeExceptionally(e);
            }
        });
        return future;
    }

    public CompletableFuture<Integer> parallelRecursiveConjure(SigilNode node) {
        return processNode(node, executor);
    }

    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        Enchanter enchanter = new Enchanter(executor);

        SigilNode leaf1 = new SimpleSigilNode(new SimpleTalisman(1), Collections.emptyList());
        SigilNode leaf2 = new SimpleSigilNode(new SimpleTalisman(2), Collections.emptyList());
        SigilNode parent = new SimpleSigilNode(new SimpleTalisman(3), Arrays.asList(leaf1, leaf2));

        List<Talisman> talismans = Arrays.asList(
            new SimpleTalisman(4),
            new SimpleTalisman(5)
        );

        // Sequential processing
        System.out.println("Sequential Weave: " + enchanter.sequentialWeave(talismans));
        System.out.println("Recursive Weave: " + enchanter.recursiveWeave(parent));

        // Parallel processing
        List<Integer> parallelResult = enchanter.parallelConjure(talismans).get();
        System.out.println("Parallel Conjure: " + parallelResult);

        CompletableFuture<Integer> recursiveParallelResult = enchanter.parallelRecursiveConjure(parent);
        System.out.println("Recursive Parallel Conjure: " + recursiveParallelResult.get());

        executor.shutdown();
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletionService;
import java.util.concurrent.ExecutorCompletionService;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.InterruptedException;

public class Main {

    public interface Talisman {
        Result enchant();
    }

    public interface SigilNode {
        Result compute();
        List<SigilNode> children();
    }

    public static class Result {
        private final String value;

        public Result(String value) { this.value = value; }
        @Override
        public String toString() { return "Result{" + value + "}"; }
    }

    // Sequential processing for Talismans
    public static List<Result> sequentialWeave(List<Talisman> talismans) {
        List<Result> results = new ArrayList<>();
        for (Talisman t : talismans) {
            Result r = t.enchant();
            results.add(r);
        }
        return results;
    }

    // Parallel processing for Talismans
    public static List<Result> parallelConjure(List<Talisman> talismans, ExecutorService executor) {
        List<Future<Result>> futures = new ArrayList<>();
        for (Talisman t : talismans) {
            Callable<Result> task = () -> t.enchant();
            Future<Result> future = executor.submit(task);
            futures.add(future);
        }
        List<Result> results = new ArrayList<>();
        for (Future<Result> f : futures) {
            try {
                Result r = f.get();
                results.add(r);
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
        }
        return results;
    }

    // Sequential processing for SigilNode tree
    public static List<Result> recursiveComputeSequential(SigilNode node) {
        List<Result> results = new ArrayList<>();
        Result r = node.compute();
        results.add(r);
        for (SigilNode child : node.children()) {
            results.addAll(recursiveComputeSequential(child));
        }
        return results;
    }

    // Parallel processing for SigilNode tree
    public static List<Result> recursiveComputeParallel(SigilNode node, ExecutorService executor) {
        List<Result> results = new ArrayList<>();
        Result r = node.compute();
        results.add(r);
        CompletionService<Result> completionService = new ExecutorCompletionService<>(executor);
        for (SigilNode child : node.children()) {
            Callable<Result> task = () -> recursiveComputeParallel(child, executor);
            completionService.submit(task);
        }
        int numChildren = node.children().size();
        for (int i = 0; i < numChildren; i++) {
            try {
                Future<Result> future = completionService.take();
                Result childResult = future.get();
                results.add(childResult);
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
        }
        return results;
    }

    public static void main(String[] args) {
        // Example usage:

        List<Talisman> talismans = List.of(
            () -> new Result("T1"),
            () -> new Result("T2")
        );

        ExecutorService executor = Executors.newFixedThreadPool(2);

        System.out.println("\nSequential Weave:");
        List<Result> seqResults = sequentialWeave(talismans);
        seqResults.forEach(System.out::println);

        System.out.println("\nParallel Conjure:");
        List<Result> parallelResults = parallelConjure(talismans, executor);
        parallelResults.forEach(System.out::println);

        SigilNode child1 = new SigilNode() {
            @Override
            public Result compute() { return new Result("C1"); }
            @Override
            public List<SigilNode> children() { return Collections.emptyList(); }
        };
        SigilNode child2 = new SigilNode() {
            @Override
            public Result compute() { return new Result("C2"); }
            @Override
            public List<SigilNode> children() { return Collections.emptyList(); }
        };
        SigilNode root = new SigilNode() {
            @Override
            public Result compute() { return new Result("R1"); }
            @Override
            public List<SigilNode> children() { return List.of(child1, child2); }
        };

        System.out.println("\nRecursive Compute Sequential:");
