import java.util.concurrent.*;

public class Enchanter {
    interface Talisman {
        int getValue();
    }

    interface SigilNode {
        Talisman compute();
        List<SigilNode> children();
    }

    public static class SimpleTalisman implements Talisman {
        private final int value;

