        public int getValue() {
            return value;
        }
    }

    public static class SimpleSigilNode implements SigilNode {
        private final Talisman talisman;
        private final List<SigilNode> children;

        public SimpleSigilNode(Talisman talisman, List<SigilNode> children) {
            this.talisman = talisman;
            this.children = children;
        }

        @Override
        public Talisman compute() {
            return talisman;
        }

        @Override
        public List<SigilNode> children() {
            return children;
        }
    }

    private final ExecutorService executor;

    public Enchanter(ExecutorService executor) {
        this.executor = executor;
    }

    public List<Integer> sequentialWeave(List<Talisman> talismans) {
        List<Integer> results = new ArrayList<>();
        for (Talisman talisman : talismans) {
            results.add(talisman.getValue());
        }
        return results;
    }

    public CompletableFuture<List<Integer>> parallelConjure(List<Talisman> talismans) {
        CompletionService<Integer> completionService = new ExecutorCompletionService<>(executor);
        List<Future<Integer>> futures = new ArrayList<>();

        for (Talisman talisman : talismans) {
            futures.add(completionService.submit(() -> talisman.getValue()));
        }

        return CompletableFuture.supplyAsync(() -> {
            List<Integer> results = new ArrayList<>();
            for (Future<Integer> future : futures) {
                results.add(future.get());
            }
            return results;
        }, executor);
    }

    public int recursiveWeave(SigilNode node) {
        int result = node.compute().getValue();
        for (SigilNode child : node.children()) {
            result += recursiveWeave(child);
        }
        return result;
    }

    private CompletableFuture<Integer> processNode(SigilNode node, ExecutorService executor) {
        CompletableFuture<Integer> future = new CompletableFuture<>();
        executor.submit(() -> {
            try {
                int value = node.compute().getValue();
                List<CompletableFuture<Integer>> childFutures = new ArrayList<>();
                for (SigilNode child : node.children()) {
