import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentSkipListSet;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EnchantmentConjuration {
    interface Talisman {
        void enchant();
        String getId();
    }

    interface SigilNode<T> {
        T compute();
        List<SigilNode<T>> getChildSigils();
    }

    static class SequentialEnchanter {
        void weaveTalismans(List<? extends Talisman> talismans) {
            for (Talisman t : talismans) {
                t.enchant();
            }
        }

        <T> Set<T> traverseGrove(SigilNode<T> root) {
            return computeRecursive(root, new ConcurrentSkipListSet<>());
        }

        private <T> Set<T> computeRecursive(SigilNode<T> node, Set<T> results) {
            T result = node.compute();
            results.add(result);
            for (SigilNode<T> child : node.getChildSigils()) {
                computeRecursive(child, results);
            }
            return results;
        }
    }

    static class ParallelEnchanter {
        void weaveTalismans(List<? extends Talisman> talismans, ExecutorService executor) {
            for (final Talisman t : talismans) {
                executor.execute(() -> t.enchant());
            }
            executor.shutdown();
        }

        <T> Set<T> traverseGrove(SigilNode<T> root, ExecutorService executor) {
            final Set<T> results = new ConcurrentSkipListSet<>();
            computeParallel(root, executor, results);
            executor.shutdown();
            return results;
        }

        private <T> void computeParallel(SigilNode<T> node, ExecutorService executor, Set<T> results) {
            T result = node.compute();
            results.add(result);
            List<SigilNode<T>> children = node.getChildSigils();
            for (final SigilNode<T> child : children) {
                executor.execute(() -> computeParallel(child, executor, results));
            }
        }
    }

    public static void main(String[] args) {
        SequentialEnchanter sequential = new SequentialEnchanter();
        ParallelEnchanter parallel = new ParallelEnchanter();

        // Example with Talismans
        List<Talisman> talismans = List.of(
                (Talisman) () -> System.out.println("Enchanting 1"),
                (Talisman) () -> System.out.println("Enchanting 2")
        );

        sequential.weaveTalismans(talismans);

        ExecutorService executor = Executors.newFixedThreadPool(2);
        parallel.weaveTalismans(talismans, executor);

        // Example with SigilNodes
        SigilNode<String> root = new SigilNode<String>() {
            @Override
            public String compute() { return "Root"; }
            @Override
            public List<SigilNode<String>> getChildSigils() {
                return List.of(new SigilNode<String>() {
                    @Override
                    public String compute() { return "Child1"; }
                    @Override
                    public List<SigilNode<String>> getChildSigils() { return List.of(); }
                }, new SigilNode<String>() {
                    @Override
                    public String compute() { return "Child2"; }
                    @Override
                    public List<SigilNode<String>> getChildSigils() { return List.of(); }
                });
            }
        };

