import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.ArrayList;
import java.util.List;

public class SpellCaster {

    public interface Charm {
        Result invoke();
    }

    public interface RuneNode<T extends RuneNode> {
        boolean isCharm();
        List<T> getChildren();
        void setResult(Result result);
        Result getResult();
        default void compute() {
            if (isCharm()) {
                setResult(((Charm)this).invoke());
            } else {
                for (T child : getChildren()) {
                    child.compute();
                }
                setResult(collectResults());
            }
        }
        Result collectResults();
    }

    public static class Result {
        private String value;
        public Result(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    public static void processRuneSequential(RuneNode<?> rune) {
        if (rune.isCharm()) {
            rune.setResult(((Charm)rune).invoke());
        } else {
            for (RuneNode<?> child : rune.getChildren()) {
                processRuneSequential(child);
            }
            rune.setResult(rune.collectResults());
        }
    }

    public static void processRuneParallel(RuneNode<?> rune, ExecutorService executor) {
        if (rune.isCharm()) {
            rune.setResult(((Charm)rune).invoke());
        } else {
            ConcurrentLinkedQueue<Result> results = new ConcurrentLinkedQueue<>();
            for (final RuneNode<?> child : rune.getChildren()) {
                Runnable task = () -> {
                    processRuneParallel(child, executor);
                    results.add(child.getResult());
                };
                executor.submit(task);
            }
            while (!results.containsAll(rune.getChildren().size())) {}
            rune.setResult(rune.collectResults());
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Sample rune structure
        RuneNode<?> charm1 = new Charm() {
            @Override
            public Result invoke() { return new Result("Charm 1"); }
        };

        RuneNode<?> charm2 = new Charm() {
            @Override
            public Result invoke() { return new Result("Charm 2"); }
        };

        class CompoundRune implements RuneNode<CompoundRune> {
            private List<CompoundRune> children = new ArrayList<>();
            private Result result;

            public CompoundRune add(CompoundRune child) {
                this.children.add(child);
                return this;
            }

            @Override
            public boolean isCharm() { return false; }
            @Override
            public List<CompoundRune> getChildren() { return children; }
            @Override
            public void setResult(Result result) { this.result = result; }
            @Override
            public Result getResult() { return result; }
            @Override
            public Result collectResults() {
                StringBuilder sb = new StringBuilder();
                for (CompoundRune child : getChildren()) {
                    sb.append(child.getResult().getValue()).append(" ");
                }
                return new Result(sb.toString());
            }
        }

        CompoundRune runeTree = new CompoundRune()
            .add(charm1)
            .add(new CompoundRune()
                .add(charm2));

        // Sequential processing
        processRuneSequential(runeTree);
        System.out.println("Sequential result: " + runeTree.getResult().getValue());

        // Parallel processing
        processRuneParallel(runeTree, executor);
        System.out.println("Parallel result: " + runeTree.getResult().getValue());

        executor.shutdown();
    }
}

