public class SpellCaster {

    public interface Charm {
        Result invoke();
    }

    public interface RuneNode<T extends RuneNode> {
        boolean isCharm();
        List<T> getChildren();
        void setResult(Result result);
        Result getResult();
        default void compute() {
            if (isCharm()) {
                setResult(((Charm)this).invoke());
            } else {
                for (T child : getChildren()) {
                    child.compute();
                }
                setResult(collectResults());
            }
        }
        Result collectResults();
    }

    public static class Result {
        private String value;
        public Result(String value) { this.value = value; }
        public String getValue() { return value; }
    }

    public static void processRuneSequential(RuneNode<?> rune) {
        if (rune.isCharm()) {
            rune.setResult(((Charm)rune).invoke());
        } else {
            for (RuneNode<?> child : rune.getChildren()) {
                processRuneSequential(child);
            }
            rune.setResult(rune.collectResults());
        }
    }

    public static void processRuneParallel(RuneNode<?> rune, ExecutorService executor) {
        if (rune.isCharm()) {
            rune.setResult(((Charm)rune).invoke());
        } else {
            ConcurrentLinkedQueue<Result> results = new ConcurrentLinkedQueue<>();
            for (final RuneNode<?> child : rune.getChildren()) {
                Runnable task = () -> {
                    processRuneParallel(child, executor);
                    results.add(child.getResult());
                };
                executor.submit(task);
            }
            while (!results.containsAll(rune.getChildren().size())) {}
            rune.setResult(rune.collectResults());
        }
    }

