import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.Supplier;

public class ConcurrentSummoner {

    interface Talisman<T> {
        T activate() throws InterruptedException;
    }

    interface SigilNode<T> extends Talisman<T> {
        List<SigilNode<T>> getChildSigils();
    }

    private static <T> T processSequential(List<? extends Talisman<T>> talismans) throws InterruptedException {
        List<T> results = new ArrayList<>();
        for (Talisman<T> talisman : talismans) {
            results.add(talisman.activate());
        }
        return aggregate(results);
    }

    private static <T> T processParallel(List<? extends Talisman<T>> talismans, ExecutorService executor) throws InterruptedException, ExecutionException {
        List<Future<T>> futures = new ArrayList<>();
        for (Talisman<T> talisman : talismans) {
            Future<T> future = executor.submit(() -> talisman.activate());
            futures.add(future);
        }
        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            results.add(future.get());
        }
        return aggregate(results);
    }

    private static <T> T processRecursive(SigilNode<T> root, boolean parallel, ExecutorService executor) throws InterruptedException, ExecutionException {
        if (root == null) return null;

        List<SigilNode<T>> children = root.getChildSigils();

        List<Future<T>> futures = new ArrayList<>();
        for (SigilNode<T> child : children) {
            if (parallel) {
                Future<T> future = executor.submit(() -> processRecursive(child, parallel, executor));
                futures.add(future);
            } else {
                processRecursive(child, parallel, executor);
            }
        }

        List<T> results = new ArrayList<>();
        results.add(root.activate());

        for (Future<T> future : futures) {
            results.add(future.get());
        }

        return aggregate(results);
    }

    private static <T> T aggregate(List<T> results) {
        if (results.isEmpty()) return null;
        return results.get(0); // Simplified aggregation logic
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ExecutorService executor = Executors.newFixedThreadPool(2);

        List<Talisman<String>> talismans = new ArrayList<>();
        talismans.add(() -> "Fire");
        talismans.add(() -> "Water");
        talismans.add(() -> "Earth");

        // Sequential processing
        String seqResult = processSequential(talismans);
        System.out.println("Sequential Result: " + seqResult);

        // Parallel processing
        String parallelResult = processParallel(talismans, executor);
        System.out.println("Parallel Result: " + parallelResult);

        // Recursive processing example with a simple SigilNode implementation
