public class TreasureTransfer {
    public interface Vault {
        long getTreasure();
        void setTreasure(long amount);
    }

    public interface GoldAmount {
        long getValue();
    }

    public static class SimpleVault implements Vault {
        private long treasure;

        public SimpleVault(long initialTreasure) {
            this.treasure = initialTreasure;
        }

        @Override
        public long getTreasure() {
            return treasure;
        }

        @Override
        public void setTreasure(long amount) {
            this.treasure = amount;
        }
    }

    public static class SimpleGoldAmount implements GoldAmount {
        private final long value;

        public SimpleGoldAmount(long value) {
            this.value = value;
        }

        @Override
        public long getValue() {
            return value;
        }
    }

    public static class InsufficientTreasureException extends RuntimeException {
        public InsufficientTreasureException(String message) {
            super(message);
        }
    }

    public static class TransferHelper {
        public static void transfer(Vault source, Vault destination, GoldAmount amount) throws InsufficientTreasureException {
            List<Object> locks = new ArrayList<>();
            if (source.hashCode() != destination.hashCode()) {
                if (source.hashCode() < destination.hashCode()) {
                    locks.add(source);
                    locks.add(destination);
                } else {
                    locks.add(destination);
                    locks.add(source);
                }
            } else {
                int cmp = System.identityHashCode(source) - System.identityHashCode(destination);
                if (cmp <= 0) {
                    locks.add(source);
                    locks.add(destination);
                } else {
                    locks.add(destination);
                    locks.add(source);
                }
            }

            Object firstLock = locks.get(0);
            Object secondLock = locks.get(1);

            synchronized (firstLock) {
                synchronized (secondLock) {
                    long amountValue = amount.getValue();
                    if (source.getTreasure() < amountValue) {
                        throw new InsufficientTreasureException("Insufficient funds");
                    }
                    source.setTreasure(source.getTreasure() - amountValue);
                    destination.setTreasure(destination.getTreasure() + amountValue);
                }
            }
        }
    }

    public static void main(String[] args) {
        Vault vaultA = new SimpleVault(100);
        Vault vaultB = new SimpleVault(50);

        try {
            TransferHelper.transfer(vaultA, vaultB, new SimpleGoldAmount(50));
            System.out.println("Transfer A->B successful");
        } catch (InsufficientTreasureException e) {
            System.err.println(e.getMessage());
        }

