class TransferHelper {
    static synchronized void performTransfer(Vault source, Vault destination, int amount) 
            throws InsufficientGoldException {
        Object lock1 = (source.hashCode() <= destination.hashCode()) ? source : destination;
        Object lock2 = (source.hashCode() != destination.hashCode()) ? 
                (lock1 == source ? destination : source) : new Object();

        synchronized (lock1) {
            synchronized (lock2) {
                if (source.getBalance() < amount) {
                    throw new InsufficientGoldException("Insufficient gold in source vault");
                }
                source.debit(amount);
                destination.credit(amount);
            }
        }
