public class TreasureTransfer {
    public interface Vault {
        GoldAmount getTreasure() throws InsufficientTreasureException;
        void setTreasure(GoldAmount amount);
    }

    public interface GoldAmount {
        int getValue();
    }

    public static class InsufficientTreasureException extends RuntimeException {
        public InsufficientTreasureException(String message) {
            super(message);
        }
    }

    private static class TreasureTransferHelper {
        private final Object secondaryLock = new Object();

        void checkAndTransfer(Vault source, Vault destination, GoldAmount amount) throws InsufficientTreasureException {
            int sourceHash = System.identityHashCode(source);
            int destHash = System.identityHashCode(destination);

            if (sourceHash < destHash) {
                synchronized (source) {
                    synchronized (destination) {
                        transfer(source, destination, amount);
                    }
                }
            } else if (destHash < sourceHash) {
                synchronized (destination) {
                    synchronized (source) {
                        transfer(source, destination, amount);
                    }
                }
            } else {
                synchronized (secondaryLock) {
                    synchronized (source) {
                        synchronized (destination) {
                            transfer(source, destination, amount);
                        }
                    }
                }
            }
        }

        private void transfer(Vault source, Vault destination, GoldAmount amount) throws InsufficientTreasureException {
            if (source.getTreasure().getValue() < amount.getValue()) {
                throw new InsufficientTreasureException("Insufficient treasure in source vault");
            }
            int transferValue = amount.getValue();
            source.setTreasure(new SimpleGoldAmount(source.getTreasure().getValue() - transferValue));
            destination.setTreasure(new SimpleGoldAmount(destination.getTreasure().getValue() + transferValue));
        }
    }

