            if (treasure == null || treasure.getValue() < 0) {
                throw new InsufficientTreasureException("Vault is empty or has negative amount");
            }
            return treasure;
        }

        @Override
        public void setTreasure(GoldAmount amount) {
            this.treasure = amount;
        }
    }

