import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class TreasureTransfer {
    public interface Vault {
        GoldAmount getTreasure() throws InsufficientTreasureException;
        void setTreasure(GoldAmount amount);
    }

    public interface GoldAmount {
        int getValue();
    }

