            this.source = source;
            this.destination = destination;
            this.amount = amount;
        }

        void performTransfer() throws InsufficientGemsException {
            Object lock1, lock2;
            if (source.getId().hashCode() < destination.getId().hashCode()) {
                lock1 = source;
                lock2 = destination;
            } else if (source.getId().hashCode() > destination.getId().hashCode()) {
                lock1 = destination;
                lock2 = source;
            } else {
                lock1 = new Object();
                lock2 = new Object();
            }

            synchronized (lock1) {
                synchronized (lock2) {
                    if (source.getGems().getValue() < amount.getValue()) {
                        throw new InsufficientGemsException("Insufficient gems in source hoard");
                    }
                    source.transfer(destination, amount);
                }
            }
        }
    }

