                locks[0] = locks[1];
                locks[1] = temp;
            }

            // Handle tie-breaker
            boolean acquiredFirstLock = false;
            boolean acquiredSecondLock = false;

            try {
                synchronized (locks[0]) {
                    acquiredFirstLock = true;
                    if (source.hashCode() == destination.hashCode()) {
                        synchronized (this) { // Tie-breaker lock
                            acquiredSecondLock = true;
                        }
                    }

