                        } catch (InsufficientCrystalsException e) {
                            throw e;
                        }
                        destination.deposit(amount);
                    }
                }
            } finally {
                if (acquiredSecondLock) {
                    synchronized (this) {
                        // Release tie-breaker lock
                    }
                }
                if (acquiredFirstLock) {
                    synchronized (locks[0]) {
                        // Release primary lock
                    }
                }
            }
        }

        private Object getLock(VaultNode node) {
