import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class CrystalTransfer {
    public interface VaultNode {
        int getIdentityHash();
        Lock getLocker();
        CrystalAmount getBalance();
        void setBalance(CrystalAmount balance);
    }

    public interface CrystalAmount {
        long getValue();
        void setValue(long value);
    }

    public static class InsufficientCrystalsException extends RuntimeException {
        public InsufficientCrystalsException(String message) {
            super(message);
        }
    }

    private static class TransferRite {
        private final VaultNode fromNode;
        private final VaultNode toNode;
        private final CrystalAmount amount;

        public TransferRite(VaultNode fromNode, VaultNode toNode, CrystalAmount amount) {
            this.fromNode = fromNode;
            this.toNode = toNode;
            this.amount = amount;
        }

        public void transfer() throws InsufficientCrystalsException {
            if (fromNode.getBalance().getValue() < amount.getValue()) {
                throw new InsufficientCrystalsException("Insufficient crystals in source vault");
            }

            fromNode.setBalance(new CrystalAmountImpl(fromNode.getBalance().getValue() - amount.getValue()));
            toNode.setBalance(new CrystalAmountImpl(toNode.getBalance().getValue() + amount.getValue()));
        }
    }

    public static void transfer(final VaultNode nodeA, final VaultNode nodeB, final CrystalAmount amount) {
        final Lock lockerA = nodeA.getLocker();
        final Lock lockerB = nodeB.getLocker();

        if (nodeA.getIdentityHash() < nodeB.getIdentityHash()) {
            lockAndTransfer(lockerA, lockerB, nodeA, nodeB, amount);
        } else if (nodeB.getIdentityHash() < nodeA.getIdentityHash()) {
            lockAndTransfer(lockerB, lockerA, nodeB, nodeA, amount);
        } else {
            Lock tieBreakerLock = new ReentrantLock();
            try {
                tieBreakerLock.lock();
                lockAndTransfer(lockerA, lockerB, nodeA, nodeB, amount);
            } finally {
                tieBreakerLock.unlock();
            }
        }
    }

    private static void lockAndTransfer(Lock firstLocker, Lock secondLocker,
                                        VaultNode fromNode, VaultNode toNode, CrystalAmount amount) {
        try {
            firstLocker.lock();
            try {
                secondLocker.lock();
                new TransferRite(fromNode, toNode, amount).transfer();
            } finally {
                secondLocker.unlock();
            }
        } finally {
            firstLocker.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        VaultNode nodeA = new VaultNodeImpl(100);
        VaultNode nodeB = new VaultNodeImpl(50);

        Runnable transferTask = () -> {
            try {
                CrystalTransfer.transfer(nodeA, nodeB, new CrystalAmountImpl(25));
            } catch (InsufficientCrystalsException e) {
                System.out.println(e.getMessage());
            }
        };

        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(2);
        executor.execute(transferTask);
        executor.execute(transferTask);

        Thread.sleep(1000);
        executor.shutdown();
    }

    private static class VaultNodeImpl implements VaultNode {
        private final Lock locker = new ReentrantLock();
        private CrystalAmount balance;

        public VaultNodeImpl(long initialBalance) {
            this.balance = new CrystalAmountImpl(initialBalance);
        }

        @Override
        public int getIdentityHash() {
            return System.identityHashCode(this);
        }

        @Override
        public Lock getLocker() {
            return locker;
        }

        @Override
        public CrystalAmount getBalance() {
            return balance;
        }

        @Override
        public void setBalance(CrystalAmount balance) {
            this.balance = balance;
        }
    }

