        public synchronized void withdraw(CrystalAmount amount) throws InsufficientCrystalsException {
            long crystals = amount.getValue();
            if (balance < crystals) {
                throw new InsufficientCrystalsException("Insufficient crystals in vault: " + id);
            }
            balance -= crystals;
        }

        @Override
        public synchronized void deposit(CrystalAmount amount) {
            balance += amount.getValue();
