        public static void transfer(VaultNode from, VaultNode to, CrystalAmount amount) throws InsufficientCrystalsException {
            VaultNode firstLock;
            VaultNode secondLock;

            if (from.hashCode() < to.hashCode()) {
                firstLock = from;
                secondLock = to;
            } else if (to.hashCode() < from.hashCode()) {
                firstLock = to;
                secondLock = from;
            } else {
                synchronized (TIE_BREAKER_LOCK) {
                    firstLock = from;
                    secondLock = to;
                }
