                        firstLock.withdraw(amount);
                        secondLock.deposit(amount);
                    } catch (InsufficientCrystalsException e) {
                        throw new InsufficientCrystalsException("Transfer failed: " + e.getMessage());
                    }
                }
            }
        }
    }

