public class OrbVault {
    private final int maxCapacity;
    private final Semaphore availableSlots;
    private final Semaphore availableOrbs;
    private final ReentrantLock lock = new ReentrantLock();
    private final Queue<Orb> vaultQueue = new LinkedList<>();

    public OrbVault(int maxCapacity) {
        if (maxCapacity <= 0) {
            throw new IllegalArgumentException("Max capacity must be positive.");
        }
        this.maxCapacity = maxCapacity;
        availableSlots = new Semaphore(maxCapacity);
        availableOrbs = new Semaphore(0);
    }

    public void put(Orb x) throws InterruptedException {
        availableSlots.acquire();
        lock.lock();
        try {
            vaultQueue.add(x);
            System.out.println("Put orb: " + x.toString() + ", remaining slots: " + (maxCapacity - vaultQueue.size()));
        } finally {
            lock.unlock();
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        lock.lock();
        try {
            Orb taken = vaultQueue.remove();
            System.out.println("Taken orb: " + taken.toString() + ", remaining orbs: " + (vaultQueue.size()));
            return taken;
        } finally {
            lock.unlock();
        }
    }

    public boolean isEmpty() {
        lock.lock();
        try {
            return vaultQueue.isEmpty();
        } finally {
            lock.unlock();
        }
    }

    public boolean isFull() {
        lock.lock();
        try {
            return vaultQueue.size() == maxCapacity;
        } finally {
            lock.unlock();
        }
    }

