import java.util.concurrent.Semaphore;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Queue;
import java.util.LinkedList;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;

public class OrbVault {
    private final int maxCapacity;
    private final Semaphore availableSlots;
    private final Semaphore availableOrbs;
    private final ReentrantLock lock = new ReentrantLock();
    private final Queue<Orb> vaultQueue = new LinkedList<>();

    public OrbVault(int maxCapacity) {
        if (maxCapacity <= 0) {
            throw new IllegalArgumentException("Max capacity must be positive.");
        }
        this.maxCapacity = maxCapacity;
        availableSlots = new Semaphore(maxCapacity);
        availableOrbs = new Semaphore(0);
    }

    public void put(Orb x) throws InterruptedException {
        availableSlots.acquire();
        lock.lock();
        try {
            vaultQueue.add(x);
            System.out.println("Put orb: " + x.toString() + ", remaining slots: " + (maxCapacity - vaultQueue.size()));
        } finally {
            lock.unlock();
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        lock.lock();
        try {
            Orb taken = vaultQueue.remove();
            System.out.println("Taken orb: " + taken.toString() + ", remaining orbs: " + (vaultQueue.size()));
            return taken;
        } finally {
            lock.unlock();
        }
    }

    public boolean isEmpty() {
        lock.lock();
        try {
            return vaultQueue.isEmpty();
        } finally {
            lock.unlock();
        }
    }

    public boolean isFull() {
        lock.lock();
        try {
            return vaultQueue.size() == maxCapacity;
        } finally {
            lock.unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        OrbVault vault = new OrbVault(3);
        ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(2);

        Runnable sorcererTask = () -> {
            try {
                Orb orb1 = new Orb("Orb-1");
                vault.put(orb1);

                Orb taken1 = vault.take();
                System.out.println("Sorcerer took: " + taken1.toString());

                Orb orb2 = new Orb("Orb-2");
                vault.put(orb2);

                if (!vault.isEmpty()) {
                    Orb taken2 = vault.take();
                    System.out.println("Sorcerer took: " + taken2.toString());
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        executor.execute(sorcererTask);
        executor.execute(sorcererTask);

        executor.shutdown();
        while (!executor.isTerminated()) {
            // Wait for tasks to complete
        }

        System.out.println("Final vault state: " + (vault.isEmpty() ? "empty" : "contains orbs"));
    }
}

class Orb {
    private String name;

    public Orb(String name) {
        this.name = name;
    }

    @Override
    public String toString() {
        return name;
    }
}
