        this.name = name;
    }

    public String getName() {
        return name;
    }
}

public class CrystalCarousel {
    private final int size;
    private final Crystal[] buffer;
    private int head; // next position to take from
    private int tail; // next position to put into

    private final Semaphore availableCrystals;
    private final Semaphore freeSlots;

    public CrystalCarousel(int size) {
        this.size = size;
        buffer = new Crystal[size];
        head = 0;
        tail = 0;
        availableCrystals = new Semaphore(0);
        freeSlots = new Semaphore(size);
    }

    public void put(Crystal crystal) throws InterruptedException {
        freeSlots.acquire();
        synchronized (this) {
            int indexToPut = (tail % size);
            buffer[indexToPut] = crystal;
            tail++;
        }
        availableCrystals.release();
    }

    public Crystal take() throws InterruptedException {
        availableCrystals.acquire();
        synchronized (this) {
            int indexToTake = (head % size);
            Crystal crystal = buffer[indexToTake];
            buffer[indexToTake] = null; // Optional: clean up
            head++;
            return crystal;
        }
    }

    public boolean isEmpty() {
        return availableCrystals.availablePermits() == 0;
    }

    public boolean isFull() {
        return freeSlots.availablePermits() == 0;
    }

