import java.util.concurrent.Semaphore;

class CrystalCarousel {
    private static final int CAPACITY = 5;
    private Crystal[] crystals;
    private int index;
    private Semaphore slotsAvailable;
    private Semaphore crystalsAvailable;

    public CrystalCarousel(int capacity) {
        this.crystals = new Crystal[capacity];
        this.index = 0;
        this.slotsAvailable = new Semaphore(capacity);
        this.crystalsAvailable = new Semaphore(0);
    }

    public void put(Crystal x) throws InterruptedException {
        slotsAvailable.acquire();
        crystals[index] = x;
        index = (index + 1) % crystals.length;
        crystalsAvailable.release();
    }

    public Crystal take() throws InterruptedException {
        crystalsAvailable.acquire();
        int currentIndex = (index - 1 + crystals.length) % crystals.length;
        Crystal crystal = crystals[currentIndex];
        crystals[currentIndex] = null;
        index = currentIndex;
        slotsAvailable.release();
        return crystal;
    }

    public boolean isEmpty() {
        return crystalsAvailable.availablePermits() == 0;
    }

    public boolean isFull() {
        return slotsAvailable.availablePermits() == 0;
    }
}

