import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;
import java.util.concurrent.locks.ReentrantLock;

class Crystal {
    String name;

    Crystal(String name) {
        this.name = name;
    }
}

class CrystalCarousel {
    private final int SIZE = 5;
    private final Semaphore freeSlots = new Semaphore(SIZE);
    private final Semaphore availableCrystals = new Semaphore(0);
    private final Crystal[] buffer = new Crystal[SIZE];
    private int head = 0, tail = 0;
    private final ReentrantLock lock = new ReentrantLock();

    public void put(Crystal x) throws InterruptedException {
        freeSlots.acquire();
        lock.lock();
        try {
            buffer[head] = x;
            head = (head + 1) % SIZE;
            availableCrystals.release();
        } finally {
            lock.unlock();
        }
    }

    public Crystal take() throws InterruptedException {
        availableCrystals.acquire();
        lock.lock();
        try {
            Crystal x = buffer[tail];
            tail = (tail + 1) % SIZE;
            freeSlots.release();
            return x;
        } finally {
            lock.unlock();
        }
    }

    public boolean isEmpty() {
        return availableCrystals.availablePermits() == 0;
    }

    public boolean isFull() {
        return freeSlots.availablePermits() == 0;
    }
}

public class Main {
    public static void main(String[] args) {
        CrystalCarousel crystalCarousel = new CrystalCarousel();

        ExecutorService service = Executors.newFixedThreadPool(2);
        try {
            // Producer thread
            service.submit(() -> {
                for (int i = 0; i < 5; i++) {
                    String crystalName = "Crystal" + i;
                    System.out.println("Producing: " + crystalName);
                    crystalCarousel.put(new Crystal(crystalName));
                }
            });

            // Consumer thread
            service.submit(() -> {
                for (int i = 0; i < 5; i++) {
                    Crystal c = crystalCarousel.take();
                    System.out.println("Consuming: " + c.name);
                }
            });
        } finally {
            service.shutdown();
        }
    }
}

