import java.util.concurrent.Semaphore;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

class Crystal {
    private String name;

    public Crystal(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

public class CrystalCarousel {
    private final int size;
    private final Crystal[] buffer;
    private int head; // next position to take from
    private int tail; // next position to put into

    private final Semaphore availableCrystals;
    private final Semaphore freeSlots;

    public CrystalCarousel(int size) {
        this.size = size;
        buffer = new Crystal[size];
        head = 0;
        tail = 0;
        availableCrystals = new Semaphore(0);
        freeSlots = new Semaphore(size);
    }

    public void put(Crystal crystal) throws InterruptedException {
        freeSlots.acquire();
        synchronized (this) {
            int indexToPut = (tail % size);
            buffer[indexToPut] = crystal;
            tail++;
        }
        availableCrystals.release();
    }

    public Crystal take() throws InterruptedException {
        availableCrystals.acquire();
        synchronized (this) {
            int indexToTake = (head % size);
            Crystal crystal = buffer[indexToTake];
            buffer[indexToTake] = null; // Optional: clean up
            head++;
            return crystal;
        }
    }

    public boolean isEmpty() {
        return availableCrystals.availablePermits() == 0;
    }

    public boolean isFull() {
        return freeSlots.availablePermits() == 0;
    }

    public static void main(String[] args) throws Exception {
        final CrystalCarousel carousel = new CrystalCarousel(5);
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    Crystal crystal = new Crystal("Crystal" + i);
                    System.out.println("Putting: " + crystal.getName());
                    carousel.put(crystal);
                    Thread.sleep(100); // Simulate work
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.submit(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    Crystal crystal = carousel.take();
                    System.out.println("Taken: " + crystal.getName());
                    Thread.sleep(200); // Simulate work
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(100);
        }
        System.out.println("All tasks completed.");
    }
}
