class PotionLoop {
    private final Object lock = new Object();
    private final Potion[] buffer;
    private int head;
    private int tail;
    private final java.util.concurrent.Semaphore availableSpace;
    private final java.util.concurrent.Semaphore availablePotions;

    public PotionLoop(int capacity) {
        this.buffer = new Potion[capacity];
        this.head = 0;
        this.tail = 0;
        this.availableSpace = new java.util.concurrent.Semaphore(capacity);
        this.availablePotions = new java.util.concurrent.Semaphore(0);
    }

    public void put(Potion x) throws InterruptedException {
        availableSpace.acquire();
        synchronized (lock) {
            buffer[tail] = x;
            tail = (tail + 1) % buffer.length;
        }
        availablePotions.release();
    }

    public Potion take() throws InterruptedException {
        availablePotions.acquire();
        Potion potion;
        synchronized (lock) {
            potion = buffer[head];
            head = (head + 1) % buffer.length;
        }
        availableSpace.release();
        return potion;
    }

    public boolean isEmpty() {
        return availablePotions.availablePermits() == 0;
    }

    public boolean isFull() {
        return availableSpace.availablePermits() == 0;
    }
}

