import java.util.concurrent.Semaphore;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class PotionLoop {
    private static final int DEFAULT_SIZE = 3;

    private final Lock lock = new ReentrantLock();
    private final Semaphore slotsAvailable;
    private final Semaphore potionsAvailable;

    private final Potion[] buffer;
    private int head, tail;

    public PotionLoop(int size) {
        if (size <= 0) throw new IllegalArgumentException("Size must be positive");
        buffer = new Potion[size];
        slotsAvailable = new Semaphore(size);
        potionsAvailable = new Semaphore(0);
        head = tail = 0;
    }

    public void put(Potion potion) throws InterruptedException {
        slotsAvailable.acquire();
        lock.lock();
        try {
            buffer[tail] = potion;
            tail = (tail + 1) % buffer.length;
        } finally {
            lock.unlock();
        }
        potionsAvailable.release();
    }

    public Potion take() throws InterruptedException {
        potionsAvailable.acquire();
        lock.lock();
        try {
            Potion potion = buffer[head];
            head = (head + 1) % buffer.length;
            return potion;
        } finally {
            lock.unlock();
        }
    }

    public boolean isEmpty() {
        lock.lock();
        try {
            return head == tail && potionsAvailable.availablePermits() == 0;
        } finally {
            lock.unlock();
        }
    }

    public boolean isFull() {
        lock.lock();
        try {
            int nextTail = (tail + 1) % buffer.length;
            return nextTail == head && slotsAvailable.availablePermits() == 0;
        } finally {
            lock.unlock();
        }
    }

    public static class Potion {
        private final String name;

        public Potion(String name) {
            this.name = name;
        }

        @Override
        public String toString() {
            return "Potion{" + name + "}";
        }
    }

    public static void main(String[] args) throws InterruptedException {
        PotionLoop loop = new PotionLoop(DEFAULT_SIZE);
        Runnable producer = () -> {
            int count = 0;
            while (count < 5) {
                try {
                    loop.put(new Potion("Potion" + count));
                    System.out.println("Produced: " + count++);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable consumer = () -> {
            int received = 0;
            while (received < 5) {
                try {
                    Potion potion = loop.take();
                    System.out.println("Consumed: " + potion);
                    received++;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        java.util.concurrent.ExecutorService executor =
                java.util.concurrent.Executors.newFixedThreadPool(2);
        executor.execute(producer);
        executor.execute(consumer);
        executor.shutdown();
        while (!executor.isTerminated()) {
            Thread.sleep(100);
        }
    }
}
