        try {
            lock.writeLock().lock();
            map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends Object, ? extends Object> m) {
        try {
            lock.writeLock().lock();
            map.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

