        });

        executor.submit(() -> {
            registry.remove("key2");
            boolean containsKey = registry.containsKey("key2");
            System.out.println("Contains key2: " + containsKey);
        });

        executor.shutdown();
        while (!executor.awaitTermination(1, TimeUnit.SECONDS)) {
            // Wait for all tasks to complete
        }
    }
