import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EtherealCounter {
    private int aura;

    public synchronized int get() {
        return aura;
    }

    public synchronized int compareAndSwap(int expectedAura, int newAura) {
        if (aura == expectedAura) {
            int old Aura = aura;
            aura = newAura;
            return oldAura;
        } else {
            return aura;
        }
    }

    public synchronized boolean compareAndSet(int expectedAura, int newAura) {
        int oldAura = compareAndSwap(expectedAura, newAura);
        return oldAura == expectedAura;
    }

    public static void main(String[] args) {
        EtherealCounter counter = new EtherealCounter();
        ExecutorService executor = Executors.newFixedThreadPool(1);

        Runnable testRun = () -> {
            System.out.println("Thread: " + Thread.currentThread().getName() + " starting...");
            for (int i = 0; i < 3; i++) {
                int current = counter.get();
                boolean success = counter.compareAndSet(current, current + 1);
                if (success) {
                    System.out.println("Thread: " + Thread.currentThread().getName() + " successfully incremented to " + counter.get());
                } else {
                    System.out.println("Thread: " + Thread.currentThread().getName() + " failed to increment");
                }
            }
        };

        executor.submit(testRun);
        testRun.run();
        executor.shutdown();
    }
}
```

