class Relic {
    private static final Relic INSTANCE = new Relic();

    private Relic() {}

    public static Relic getInstance() {
        return INSTANCE;
    }

    void invokeSpell() {
        System.out.println("Incantation: Abra Kadabra!");
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        java.util.concurrent.ExecutorService executor = 
            java.util.concurrent.Executors.newFixedThreadPool(3);

        for (int i = 0; i < 5; i++) {
            java.lang.Runnable task = () -> {
                Relic.getInstance().invokeSpell();
            };
            executor.submit(task);
        }

        executor.shutdown();
        while (!executor.awaitTermination(1, java.util.concurrent.TimeUnit.SECONDS)) {}

        System.out.println("Ritual complete.");
    }
}

public class SingletonRelicDemo {
    public static void main(String[] args) throws InterruptedException {
        int numThreads = 3;
        CountDownLatch latch = new CountDownLatch(numThreads);

        Runnable task = () -> {
            SingletonRelic.getInstance().invokeSpell();
            latch.countDown();
        };

        Thread thread1 = new Thread(task);
        Thread thread2 = new Thread(task);
        Thread thread3 = new Thread(task);

        thread1.start();
        thread2.start();
        thread3.start();

        latch.await();
        System.out.println("Ritual complete.");
    }

    private static class SingletonRelic {
        private static final SingletonRelic RELIC = new SingletonRelic();

        private SingletonRelic() {}

        public static SingletonRelic getInstance() {
            return RELIC;
        }

        public void invokeSpell() {
            System.out.println("Abracadabra!");
        }
    }
}

