import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

class MutableOrb {
    private int x;
    private int y;

    public MutableOrb(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() { return x; }
    public int getY() { return y; }
    public void setX(int x) { this.x = x; }
    public void setY(int y) { this.y = y; }

    public MutableOrb copy() {
        return new MutableOrb(this.x, this.y);
    }
}

class ChronomanticDragonTracker {
    private Map<String, MutableOrb> constellation;

    public ChronomanticDragonTracker(Map<String, MutableOrb> initialConstellation) {
        this.constellation = deepClone(initialConstellation);
    }

    private static Map<String, MutableOrb> deepClone(Map<String, MutableOrb> original) {
        Map<String, MutableOrb> copy = new HashMap<>();
        for (Map.Entry<String, MutableOrb> entry : original.entrySet()) {
            copy.put(entry.getKey(), entry.getValue().copy());
        }
        return copy;
    }

    public synchronized Map<String, MutableOrb> getConstellations() {
        return Collections.unmodifiableMap(deepClone(constellation));
    }

    public synchronized MutableOrb getOrb(String sigil) {
        if (!constellation.containsKey(sigil)) {
            return null;
        }
        return constellation.get(sigil).copy();
    }

    public synchronized void setOrb(String sigil, int shimmerX, int shimmerY) {
        MutableOrb orb = constellation.get(sigil);
        if (orb == null) {
            throw new IllegalArgumentException("Sigil not found: " + sigil);
        }
        orb.setX(shimmerX);
        orb.setY(shimmerY);
    }

