        Map<String, MutableOrb> initial = new HashMap<>();
        initial.put("DRAGON1", new MutableOrb(100, 200));
        initial.put("DRAGON2", new MutableOrb(300, 400));

        ChronomanticDragonTracker tracker = new ChronomanticDragonTracker(initial);

        Runnable task1 = () -> {
            System.out.println("Thread 1: Getting DRAGON1 location");
            MutableOrb dragon1 = tracker.getOrb("DRAGON1");
            if (dragon1 != null) {
                System.out.println("Thread 1: Dragon1 at (" + dragon1.getX() + ", " + dragon1.getY() + ")");
            }
        };

        Runnable task2 = () -> {
            try {
                Thread.sleep(500);
                System.out.println("Thread 2: Updating DRAGON1 location");
                tracker.setOrb("DRAGON1", 500, 600);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        };

        Runnable task3 = () -> {
            System.out.println("Main thread: Getting updated constellation");
            Map<String, MutableOrb> constellations = tracker.getConstellations();
            for (Map.Entry<String, MutableOrb> entry : constellations.entrySet()) {
                System.out.println("Main thread: " + entry.getKey() + " at (" + 
                                  entry.getValue().getX() + ", " + 
                                  entry.getValue().getY() + ")");
            }
        };

        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(2);
        executor.execute(task1);
        executor.execute(task2);
        task3.run(); // Run on main thread
        executor.shutdown();
    }
}

