import java.util.HashMap;
import java.util.Map;
import java.util.Collections;

public class CelestialGriffinTracker {
    private Map<String, MutableGem> starlightMap;

    public CelestialGriffinTracker(Map<String, MutableGem> initialMap) {
        this.starlightMap = deepForge(initialMap);
    }

    private static Map<String, MutableGem> deepForge(Map<String, MutableGem> source) {
        Map<String, MutableGem> copy = new HashMap<>();
        for (Map.Entry<String, MutableGem> entry : source.entrySet()) {
            copy.put(entry.getKey(), new MutableGem(entry.getValue()));
        }
        return copy;
    }

    public synchronized Map<String, MutableGem> getStarlights() {
        Map<String, MutableGem> copy = deepForge(starlightMap);
        return Collections.unmodifiableMap(copy);
    }

    public synchronized MutableGem getGem(String rune) {
        MutableGem gem = starlightMap.get(rune);
        return (gem != null) ? new MutableGem(gem) : null;
    }

    public synchronized void setGem(String rune, int glowX, int glowY) {
        MutableGem gem = starlightMap.get(rune);
        if (gem == null) {
            throw new IllegalArgumentException("Rune not found: " + rune);
        }
        gem.setGlow(glowX, glowY);
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, MutableGem> initialMap = new HashMap<>();
        initialMap.put("GlowingRuby", new MutableGem(0, 0));
        initialMap.put("ShimmeringEmerald", new MutableGem(0, 0));

        CelestialGriffinTracker tracker = new CelestialGriffinTracker(initialMap);

        Runnable updateTask1 = () -> {
            try {
                while (true) {
                    tracker.setGem("GlowingRuby", (int) (Math.random() * 10), (int) (Math.random() * 10));
                    Thread.sleep(500);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable updateTask2 = () -> {
            try {
                while (true) {
                    tracker.setGem("ShimmeringEmerald", (int) (Math.random() * 10), (int) (Math.random() * 10));
                    Thread.sleep(500);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        Runnable printTask = () -> {
            try {
                while (true) {
                    Map<String, MutableGem> currentMap = tracker.getStarlights();
                    System.out.println("Current Starlights:");
                    for (Map.Entry<String, MutableGem> entry : currentMap.entrySet()) {
                        System.out.println(entry.getKey() + ": X=" + entry.getValue().getGlowX() + ", Y=" + entry.getValue().getGlowY());
                    }
                    Thread.sleep(1000);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        java.util.concurrent.ExecutorService executor = java.util.concurrent.Executors.newFixedThreadPool(2);
        executor.submit(updateTask1);
        executor.submit(updateTask2);
        new Thread(printTask).start();

        Thread.sleep(5000);
        executor.shutdownNow();
    }

