import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CelestialGriffinTracker {
    private final Map<String, MutableGem> starlightMap;

    public CelestialGriffinTracker(Map<String, MutableGem> initialMap) {
        this.starlightMap = deepForge(initialMap);
    }

    private static Map<String, MutableGem> deepForge(Map<String, MutableGem> map) {
        Map<String, MutableGem> copy = new HashMap<>();
        for (Map.Entry<String, MutableGem> entry : map.entrySet()) {
            copy.put(entry.getKey(), entry.getValue().copy());
        }
        return copy;
    }

    public synchronized Map<String, MutableGem> getStarlights() {
        return Collections.unmodifiableMap(deepForge(this.starlightMap));
    }

    public synchronized MutableGem getGem(String rune) {
        MutableGem gem = this.starlightMap.get(rune);
        return gem != null ? gem.copy() : null;
    }

    public synchronized void setGem(String rune, int glowX, int glowY) {
        MutableGem gem = this.starlightMap.get(rune);
        if (gem == null) {
            throw new IllegalArgumentException("Rune not found: " + rune);
        }
        gem.setGlow(glowX, glowY);
    }

    private static class MutableGem {
        private int glowX;
        private int glowY;

        public MutableGem(int glowX, int glowY) {
            this.glowX = glowX;
            this.glowY = glowY;
        }

        public void setGlow(int glowX, int glowY) {
            this.glowX = glowX;
            this.glowY = glowY;
        }

        public MutableGem copy() {
            return new MutableGem(this.glowX, this.glowY);
        }
    }

