import java.util.Random;
import java.util.concurrent.locks.ReentrantLock;

public class SummonChaosOrbs {
    public static void main(String[] args) {
        int numberOfOrbs = 5;
        Orb[] orbs = new Orb[numberOfOrbs];
        for (int i = 0; i < numberOfOrbs; i++) {
            orbs[i] = new Orb(100);
        }

        FluxThread thread1 = new FluxThread(orbs, new Random());
        FluxThread thread2 = new FluxThread(orbs, new Random());

        thread1.start();
        thread2.start();

        try {
            thread1.join();
            thread2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static class Orb {
        private final ReentrantLock lock = new ReentrantLock();
        private int mana;

        public Orb(int initialMana) {
            this.mana = initialMana;
        }

        public synchronized int getMana() {
            return mana;
        }

        protected void setMana(int mana) {
            this.mana = mana;
        }

        public boolean lock() {
            try {
                return lock.tryLock();
            } catch (Exception e) {
                return false;
            }
        }

        public void unlock() {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }

    public static class EtherealFlux {
        public static void transferEnergy(Orb from, Orb to, int amount) throws InsufficientManaException {
            if (!from.lock() || !to.lock()) {
                throw new RuntimeException("Failed to acquire locks");
            }

            try {
                if (amount < 0) {
                    throw new IllegalArgumentException();
                }

                if (from.getMana() < amount) {
                    throw new InsufficientManaException();
                }

                from.setMana(from.getMana() - amount);
                to.setMana(to.getMana() + amount);

            } finally {
                from.unlock();
                to.unlock();
            }
        }

        private static void ensureOrder(Orb first, Orb second) {
            if (first.hashCode() > second.hashCode()) {
                Orb temp = first;
                first = second;
                second = temp;
            }
        }

        public static void transferEnergyWithLockOrdering(Orb from, Orb to, int amount) throws InsufficientManaException {
            ensureOrder(from, to);
            transferEnergy(from, to, amount);
        }
    }

    public static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random;

        public FluxThread(Orb[] orbs, Random random) {
            this.orbs = orbs;
            this.random = random;
        }

        @Override
        public void run() {
            int iterations = 10;
            for (int i = 0; i < iterations; i++) {
                int fromIndex = random.nextInt(orbs.length);
                int toIndex = random.nextInt(orbs.length);

                while (fromIndex == toIndex) {
                    toIndex = random.nextInt(orbs.length);
                }

                Orb fromOrb = orbs[fromIndex];
                Orb toOrb = orbs[toIndex];

                int maxManaToTransfer = Math.min(fromOrb.getMana(), 10);
                int manaAmount = random.nextInt(maxManaToTransfer);

                try {
                    EtherealFlux.transferEnergyWithLockOrdering(fromOrb, toOrb, manaAmount);
                } catch (InsufficientManaException e) {
                    // Ignored
                }
            }
        }
    }

    public static class InsufficientManaException extends RuntimeException {
        private static final long serialVersionUID = 1L;
    }
}

public class SummonChaosOrbs {
    static class Orb {
        private int mana;

        public Orb(int initialMana) {
            this.mana = initialMana;
        }

        synchronized void adjustMana(int amount) {
            mana += amount;
        }

        int getMana() {
            return mana;
        }
    }

    static class EtherealFlux {
        static void transferEnergy(Orb from, Orb to, int amount) throws InsufficientManaException {
            if (from == to) {
                return;
            }
            Orb first = from.hashCode() < to.hashCode() ? from : to;
            Orb second = from.hashCode() < to.hashCode() ? to : from;

            synchronized (first) {
                synchronized (second) {
                    if (from.mana < amount) {
                        throw new InsufficientManaException();
                    }
                    from.adjustMana(-amount);
                    to.adjustMana(amount);
                }
            }
        }
    }

    static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random;

        public FluxThread(Orb[] orbs) {
            this.orbs = orbs;
            this.random = new Random();
        }

        @Override
        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIndex, toIndex;
                do {
                    fromIndex = random.nextInt(orbs.length);
                    toIndex = random.nextInt(orbs.length);
                } while (fromIndex == toIndex);

                Orb from = orbs[fromIndex];
                Orb to = orbs[toIndex];
                int amount = random.nextInt(100) + 1;

                try {
                    EtherealFlux.transferEnergy(from, to, amount);
                } catch (InsufficientManaException e) {
                    // Ignore exception
                }
            }
        }
    }

    public static void main(String[] args) {
        final int NUM_ORBS = 5;
        final int INITIAL_MANA = 100;
        Orb[] orbs = new Orb[NUM_ORBS];
        for (int i = 0; i < NUM_ORBS; i++) {
            orbs[i] = new Orb(INITIAL_MANA);
        }

        FluxThread thread1 = new FluxThread(orbs);
        FluxThread thread2 = new FluxThread(orbs);

        thread1.start();
        thread2.start();

        try {
            thread1.join();
            thread2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        for (int i = 0; i < orbs.length; i++) {
            System.out.println("Orb " + i + " has " + orbs[i].getMana() + " mana.");
        }
    }

    static class InsufficientManaException extends Exception {
    }
}

import java.util.concurrent.TimeUnit;

public class SummonChaosOrbs {
    private static final int NUM_ORBS = 5;
    private static final int INITIAL_MANA = 100;
    private static final int ITERATIONS_PER_THREAD = 10;

    public static void main(String[] args) throws InterruptedException {
        Orb[] orbs = new Orb[NUM_ORBS];
        for (int i = 0; i < NUM_ORBS; i++) {
            orbs[i] = new Orb(INITIAL_MANA);
        }

        System.out.println("Initial state: " + getOrbStates(orbs));

        FluxThread thread1 = new FluxThread(orbs);
        FluxThread thread2 = new FluxThread(orbs);

        thread1.start();
        thread2.start();

        thread1.join();
        thread2.join();

        TimeUnit.SECONDS.sleep(1); // Wait for threads to finish

        System.out.println("Final state: " + getOrbStates(orbs));
    }

    private static String getOrbStates(Orb[] orbs) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < orbs.length; i++) {
            sb.append("Orb ").append(i).append(": ").append(orbs[i].getMana()).append(", ");
        }
        return sb.toString().replaceAll(", $", "");
    }

    static class Orb {
        private int mana;

        public Orb(int initialMana) {
            this.mana = initialMana;
        }

        public synchronized int getMana() {
            return mana;
        }

        public synchronized void addMana(ManaShard amount) {
            mana += amount.getAmount();
        }

        public synchronized boolean removeMana(ManaShard amount) {
            if (mana < amount.getAmount()) {
                return false;
            }
            mana -= amount.getAmount();
            return true;
        }
    }

    static class EtherealFlux {
        private EtherealFlux() {} // Private constructor to prevent instantiation

        public static void transferEnergy(Orb from, Orb to, ManaShard amount) throws InsufficientManaException {
            synchronized (from) {
                synchronized (to) {
                    if (!from.removeMana(amount)) {
                        throw new InsufficientManaException();
                    }
                    to.addMana(amount);
                }
            }
        }
    }

    static class FluxThread extends Thread {
        private final Orb[] orbs;

        public FluxThread(Orb[] orbs) {
            this.orbs = orbs;
        }

        @Override
        public void run() {
            Random random = new java.util.Random();
            for (int i = 0; i < ITERATIONS_PER_THREAD; i++) {
                int fromIndex = random.nextInt(NUM_ORBS);
                int toIndex = random.nextInt(NUM_ORBS);
                while (toIndex == fromIndex) {
                    toIndex = random.nextInt(NUM_ORBS);
                }
                ManaShard amount = new ManaShard(random.nextInt(10));
                try {
                    EtherealFlux.transferEnergy(orbs[fromIndex], orbs[toIndex], amount);
                } catch (InsufficientManaException e) {
                    // Ignore and continue
                }
            }
        }
    }

    static class ManaShard {
        private final int amount;

        public ManaShard(int amount) {
            this.amount = amount;
        }

        public int getAmount() {
            return amount;
        }
    }

    static class InsufficientManaException extends Exception {}
}

