        thread2.start();

        thread1.join();
        thread2.join();

        TimeUnit.SECONDS.sleep(1); // Wait for threads to finish

        System.out.println("Final state: " + getOrbStates(orbs));
    }

    private static String getOrbStates(Orb[] orbs) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < orbs.length; i++) {
            sb.append("Orb ").append(i).append(": ").append(orbs[i].getMana()).append(", ");
        }
        return sb.toString().replaceAll(", $", "");
    }

