            this.mana = initialMana;
        }

        public synchronized int getMana() {
            return mana;
        }

        public synchronized void addMana(ManaShard amount) {
            mana += amount.getAmount();
        }

        public synchronized boolean removeMana(ManaShard amount) {
            if (mana < amount.getAmount()) {
                return false;
            }
            mana -= amount.getAmount();
            return true;
        }
    }

    static class EtherealFlux {
        private EtherealFlux() {} // Private constructor to prevent instantiation

        public static void transferEnergy(Orb from, Orb to, ManaShard amount) throws InsufficientManaException {
            synchronized (from) {
                synchronized (to) {
                    if (!from.removeMana(amount)) {
                        throw new InsufficientManaException();
                    }
                    to.addMana(amount);
                }
            }
        }
    }

