import java.util.Random;
import java.util.ArrayList;

public class GoblinGoldShuffle {
    private static final int POUCH_COUNT = 5;
    private static final int THREAD_COUNT = 2;
    private static final int ITERATIONS_PER_THREAD = 10;

    private static ArrayList<GoblinPouch> pouches = new ArrayList<>();

    public static void main(String[] args) {
        // Initialize all pouches with default value
        for (int i = 0; i < POUCH_COUNT; i++) {
            pouches.add(new GoblinPouch(100));
        }

        // Create and start trade threads
        TradeThread[] threads = new TradeThread[THREAD_COUNT];
        Random random = new Random();

        for (int i = 0; i < THREAD_COUNT; i++) {
            threads[i] = new TradeThread(random);
            threads[i].start();
        }

        // Wait for all threads to complete
        for (TradeThread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    static class TradeThread extends Thread {
        private Random random;

        public TradeThread(Random random) {
            this.random = random;
        }

        @Override
        public void run() {
            for (int i = 0; i < ITERATIONS_PER_THREAD; i++) {
                // Select two distinct random pouches
                int fromIndex = random.nextInt(POUCH_COUNT);
                int toIndex = fromIndex;
                while (toIndex == fromIndex) {
                    toIndex = random.nextInt(POUCH_COUNT);
                }

                GoblinPouch from = pouches.get(fromIndex);
                GoblinPouch to = pouches.get(toIndex);

                // Generate a random transfer amount
                int amount = random.nextInt(50) + 1; // 1-50 clumps

                try {
                    SneakyTrade.transferGold(from, to, amount);
                } catch (InsufficientGoldException e) {
                    // Ignore the exception and continue
                }

                // Introduce some delay to allow interleaving of threads
                try {
                    Thread.sleep(1);
                } catch (InterruptedException e) {
                    this.interrupt();
                }
            }
        }
    }

    static class GoblinPouch {
        private int gold;

        public GoblinPouch(int initialGold) {
            this.gold = initialGold;
        }

        synchronized void addGold(int amount) {
            gold += amount;
        }

        synchronized void removeGold(int amount) throws InsufficientGoldException {
            if (gold >= amount) {
                gold -= amount;
            } else {
                throw new InsufficientGoldException("Insufficient gold in pouch");
            }
        }

        public int getGold() {
            return gold;
        }
    }

    static class SneakyTrade {
        static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            // Ensure consistent lock order
            if (from.hashCode() < to.hashCode()) {
                synchronized (from) {
                    synchronized (to) {
                        from.removeGold(amount.getValue());
                        to.addGold(amount.getValue());
                    }
                }
            } else {
                synchronized (to) {
                    synchronized (from) {
                        from.removeGold(amount.getValue());
                        to.addGold(amount.getValue());
                    }
                }
            }
        }
    }

    static class GoldClump {
        private int value;

        public GoldClump(int value) {
            this.value = value;
        }

        public int getValue() {
            return value;
        }
    }

    static class InsufficientGoldException extends Exception {
        public InsufficientGoldException(String message) {
            super(message);
        }
    }
}

import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.Random;

public class GoblinGoldShuffle {
    private static final int POUCH_COUNT = 5;
    private static final int SWAP_ITERATIONS = 10;
    private static final int MAX_AMOUNT = 100;

    private static final GoblinPouch[] pouches = new GoblinPouch[POUCH_COUNT];

    public static void main(String[] args) {
        for (int i = 0; i < POUCH_COUNT; i++) {
            pouches[i] = new GoblinPouch(100);
        }

        TradeThread thread1 = new TradeThread();
        TradeThread thread2 = new TradeThread();

        thread1.start();
        thread2.start();
    }

    static class GoblinPouch {
        private final ReentrantLock lock = new ReentrantLock();
        private AtomicInteger goldAmount;

        GoblinPouch(int initialGold) {
            this.goldAmount = new AtomicInteger(initialGold);
        }

        public int getGold() {
            return goldAmount.get();
        }

        protected ReentrantLock getLock() {
            return lock;
        }
    }

    static class TradeThread extends Thread {
        private final Random random = new Random();

        @Override
        public void run() {
            for (int iteration = 0; iteration < SWAP_ITERATIONS; iteration++) {
                int fromIndex, toIndex;
                do {
                    fromIndex = random.nextInt(POUCH_COUNT);
                    toIndex = random.nextInt(POUCH_COUNT);
                } while (fromIndex == toIndex);

                GoblinPouch from = pouches[fromIndex];
                GoblinPouch to = pouches[toIndex];

                int amount = random.nextInt(MAX_AMOUNT) + 1;

                try {
                    SneakyTrade.transferGold(from, to, new GoldClump(amount));
                } catch (InsufficientGoldException e) {
                    // Ignore and continue
                }
            }
        }
    }

    static class SneakyTrade {
        static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            ReentrantLock fromLock = from.getLock();
            ReentrantLock toLock = to.getLock();

            try {
                boolean fromAcquired = false;
                boolean toAcquired = false;

                try {
                    fromAcquired = fromLock.tryLock(10, java.util.concurrent.TimeUnit.MILLISECONDS);
                    if (!fromAcquired) throw new InterruptedException();

                    toAcquired = toLock.tryLock(10, java.util.concurrent.TimeUnit.MILLISECONDS);
                    if (!toAcquired) throw new InterruptedException();

                } catch (InterruptedException e) {
                    throw new InsufficientGoldException("Could not acquire locks in time");
                }

                try {
                    int transferAmount = amount.getAmount();
                    if (from.goldAmount.get() < transferAmount) {
                        throw new InsufficientGoldException("Insufficient gold to transfer");
                    }

                    from.goldAmount.addAndGet(-transferAmount);
                    to.goldAmount.addAndGet(transferAmount);
                } finally {
                    if (toAcquired) toLock.unlock();
                    if (fromAcquired) fromLock.unlock();
                }
            } catch (InterruptedException e) {
                throw new InsufficientGoldException("Transfer interrupted");
            }
        }
    }

    static class GoldClump {
        private final int amount;

        GoldClump(int amount) {
            this.amount = amount;
        }

        public int getAmount() {
            return amount;
        }
    }

    static class InsufficientGoldException extends Exception {
        InsufficientGoldException(String message) {
            super(message);
        }
    }
}

import java.util.Random;

public class GoblinGoldShuffle {
    public static void main(String[] args) {
        int numThreads = 2;
        int numPouches = 5;

        GoblinPouch[] allPouches = new GoblinPouch[numPouches];
        for (int i = 0; i < numPouches; i++) {
            allPouches[i] = new GoblinPouch(100);
        }

        TradeThread[] threads = new TradeThread[numThreads];
        Random rand = new Random();

        for (int i = 0; i < numThreads; i++) {
            threads[i] = new TradeThread(allPouches, numPouches, rand.nextInt());
        }

        for (TradeThread thread : threads) {
            thread.start();
        }

        for (TradeThread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
        }

        System.out.println("Final balances:");
        for (int i = 0; i < numPouches; i++) {
            System.out.println("Pouch " + i + ": " + allPouches[i].getBalance());
        }
    }

    private static class TradeThread extends Thread {
        private final GoblinPouch[] allPouches;
        private final int numPouches;
        private final Random random;

        public TradeThread(GoblinPouch[] allPouches, int numPouches, int seed) {
            this.allPouches = allPouches;
            this.numPouches = numPouches;
            this.random = new Random(seed);
        }

        @Override
        public void run() {
            for (int i = 0; i < 10; i++) {
                int fromIndex = random.nextInt(numPouches);
                int toIndex = random.nextInt(numPouches);

                while (toIndex == fromIndex) {
                    toIndex = random.nextInt(numPouches);
                }

                GoblinPouch from = allPouches[fromIndex];
                GoblinPouch to = allPouches[toIndex];

                try {
                    SneakyTrade.transferGold(from, to, new GoldClump(random.nextInt(50) + 1));
                } catch (InsufficientGoldException e) {
                    // Do nothing
                }
            }
        }
    }

    private static class GoblinPouch {
        private int balance;

        public GoblinPouch(int initialBalance) {
            this.balance = initialBalance;
        }

        public int getBalance() {
            return balance;
        }

        public void increaseBalance(GoldClump amount) {
            balance += amount.getAmount();
        }

        public void decreaseBalance(GoldClump amount) throws InsufficientGoldException {
            if (balance < amount.getAmount()) {
                throw new InsufficientGoldException();
            }
            balance -= amount.getAmount();
        }
    }

    private static class SneakyTrade {
        public static void transferGold(GoblinPouch from, GoblinPouch to, GoldClump amount) throws InsufficientGoldException {
            synchronized (from) {
                synchronized (to) {
                    if (from.getBalance() >= amount.getAmount()) {
                        from.decreaseBalance(amount);
                        to.increaseBalance(amount);
                    } else {
                        throw new InsufficientGoldException();
                    }
                }
            }
        }
    }

    private static class GoldClump {
        private final int amount;

        public GoldClump(int amount) {
            this.amount = amount;
        }

        public int getAmount() {
            return amount;
        }
    }

    public static class InsufficientGoldException extends Exception {
        private static final long serialVersionUID = 1L;

        public InsufficientGoldException() {
            super("Insufficient gold in the source pouch.");
        }
    }
}

