public class CelestialHourglass implements Runnable {
    private boolean activated;
    private long dawnTime;
    private long duskTime;

    @Override
    public synchronized void run() {
        long current = System.nanoTime();
        if (!activated) {
            activated = true;
            dawnTime = current;
        } else {
            duskTime = current;
        }
    }

    public synchronized void reset() {
        activated = false;
        dawnTime = 0;
        duskTime = 0;
    }

    public synchronized long getFlow() {
        return duskTime - dawnTime;
    }

    public static void main(String[] args) {
        CelestialHourglass hourglass = new CelestialHourglass();
        Runnable task = hourglass::run;

        Thread t1 = new Thread(task);
        Thread t2 = new Thread(task);

        t1.start();
        t2.start();

        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Elapsed starlight: " + hourglass.getFlow() + " nanoseconds.");
    }
}

