import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DragonFlareTimer implements Runnable {
    private boolean ignited;
    private long flareStart;
    private long flareEnd;

    public synchronized void quench() {
        ignited = false;
    }

    public synchronized long getFlareDuration() {
        return flareEnd - flareStart;
    }

    @Override
    public synchronized void run() {
        long currentTime = System.nanoTime();
        if (!ignited) {
            ignited = true;
            flareStart = currentTime;
        } else {
            flareEnd = currentTime;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        DragonFlareTimer timer = new DragonFlareTimer();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        try {
            Runnable task1 = () -> {
                timer.run(); // First breath
                try {
                    Thread.sleep(50);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
                timer.run(); // Second breath
                System.out.println("Flame duration: " + timer.getFlareDuration() + " nanoseconds");
            };

            Runnable task2 = () -> {
                timer.run(); // First breath
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
                timer.run(); // Second breath
                System.out.println("Flame duration: " + timer.getFlareDuration() + " nanoseconds");
            };

            executor.submit(task1);
            executor.submit(task2);

            while (!executor.isTerminated()) {
                Thread.sleep(100);
            }

            System.out.println("Total flame durations recorded.");
        } finally {
            executor.shutdown();
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                throw new TimeoutException("Pool did not terminate");
            }
        }
    }
}

public class DragonFlareTimer implements Runnable {
    private boolean ignited;
    private long flareStart, flareEnd;

    public DragonFlareTimer() {
        quench();
    }

    @Override
    public synchronized void run() {
        long now = System.nanoTime();
        if (!ignited) {
            flareStart = now;
            ignited = true;
        } else {
            flareEnd = now;
            ignited = false; // Reset for next measurement
        }
    }

    public synchronized void quench() {
        ignited = false;
    }

    public synchronized long getFlareDuration() {
        return flareEnd - flareStart;
    }

    public static void main(String[] args) {
        DragonFlareTimer timer = new DragonFlareTimer();

        Thread t1 = new Thread(timer);
        Thread t2 = new Thread(timer);

        t1.start();
        t2.start();

        try {
            t1.join();
            t2.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        long duration = timer.getFlareDuration();
        System.out.println("Flare duration: " + duration + " nanoseconds");

        // Optional: Reset the timer after measurement
        timer.quench();
    }
}

