import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class EnchantedCAS {
    private final AtomicInteger value = new AtomicInteger(0);

    public int compareAndSwap(int expected, int newValue) {
        while (true) {
            int current = value.get();
            if (current != expected) {
                return current;
            }
            boolean success = value.compareAndSet(expected, newValue);
            if (success) {
                return expected; // Original was expected
            }
        }
    }

    public int getValue() {
        return value.get();
    }
}

class PixieDustCounter {
    private final EnchantedCAS enchantedCas;

    public PixieDustCounter() {
        this.enchantedCas = new EnchantedCAS();
    }

    public int getDustLevel() {
        return enchantedCas.getValue();
    }

    public void sprinkle() {
        while (true) {
            int current = getDustLevel();
            int next = current + 1;
            int original = enchantedCas.compareAndSwap(current, next);
            if (original == current) {
                break;
            }
        }
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        PixieDustCounter counter = new PixieDustCounter();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                counter.sprinkle();
            }
        };

        executor.submit(task);
        executor.submit(task);

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);

        System.out.println("Final dust level: " + counter.getDustLevel());
    }
}

