import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class QuantumCAS {
    private volatile int shardLevel = 0;

    public int compareAndSwap(int expected, int newValue) {
        if (shardLevel == expected) {
            shardLevel = newValue;
        }
        return expected;
    }
}

public class StarlightShardCounter {
    private final QuantumCAS quantumCAS;

    public StarlightShardCounter() {
        this.quantumCAS = new QuantumCAS();
    }

    public int getShardLevel() {
        return quantumCAS.shardLevel;
    }

    public void gatherShard() {
        while (true) {
            int current = getShardLevel();
            int next = current + 1;
            if (quantumCAS.compareAndSwap(current, next) == current) {
                break;
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        StarlightShardCounter counter = new StarlightShardCounter();

        Runnable task = () -> {
            for (int i = 0; i < 1000; i++) {
                counter.gatherShard();
            }
        };

        ExecutorService executor = Executors.newFixedThreadPool(2);
        executor.execute(task);
        executor.execute(task);

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.MINUTES);

        System.out.println("Final starlight shard level: " + counter.getShardLevel());
    }
}
