            try {
                if (!transfer(accountA, accountB, new DollarAmount(30), 5, TimeUnit.SECONDS)) {
                    System.out.println("Transfer timed out");
                }
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            }
        };

        Runnable anotherTask = () -> {
            try {
                if (!transfer(accountB, accountA, new DollarAmount(20), 5, TimeUnit.SECONDS)) {
                    System.out.println("Transfer timed out");
                }
            } catch (InsufficientFundsException e) {
                System.out.println(e.getMessage());
            }
        };

        var executor = Executors.newFixedThreadPool(2);
        executor.submit(transferTask);
        executor.submit(anotherTask);
        executor.shutdown();

        try {
            while (!executor.isTerminated()) {
                Thread.sleep(100);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static boolean transfer(Account source, Account destination, DollarAmount amount,
                                  long timeout, TimeUnit unit) throws InsufficientFundsException {
        if (source == destination) return true;

        var accounts = new Account[]{source, destination};
        java.util.Arrays.sort(accounts, (a1, a2) -> Long.compare(a1.id, a2.id));

        var lock1 = accounts[0].lock;
        var lock2 = accounts[1].lock;

        for (int i = 0; i < 5; i++) {
            if (lock1.tryLock(timeout, unit)) {
                try {
                    if (lock2.tryLock()) {
                        try {
                            if (source.getBalance().amount >= amount.amount) {
                                source.withdraw(amount);
                                destination.deposit(amount);
                                return true;
                            } else {
                                throw new InsufficientFundsException("Insufficient funds in source account");
                            }
                        } finally {
                            lock2.unlock();
                        }
                    } else {
                        long delay = calculateFixedDelay(1, 50) + calculateRandomDelay(0, 2);
                        try { TimeUnit.MILLISECONDS.sleep(delay); } catch (InterruptedException e) {}
                    }
                } finally {
                    lock1.unlock();
                }
            } else {
                return false;
            }
        }
        return false;
    }

    private static long calculateFixedDelay(int min, int max) {
        return new Random().nextInt(max - min + 1) + min;
    }

    private static long calculateRandomDelay(int min, int max) {
        return new Random().nextInt(max - min + 1) + min;
    }

