                        new DollarAmount(amount), 
                        timeout, 
                        TimeUnit.SECONDS
                    );
                    if (success) {
                        System.out.println("Transfer of " + amount + " successful");
                    } else {
                        System.out.println("Transfer failed due to timeout");
                    }
                } catch (InsufficientFundsException e) {
                    System.out.println(e.getMessage());
                }
            });
        }

        executor.shutdown();
    }

    static class TransferService {
        public boolean transfer(Account source, Account destination, DollarAmount amount,
                                long timeout, TimeUnit unit) throws InsufficientFundsException {
            ReentrantLock lock1 = null;
            ReentrantLock lock2 = null;

            try {
                long nanos = unit.toNanos(timeout);

                int attempts = 0;
                while (attempts++ < 3) {
                    lock1 = source.lock();
                    if (!lock1.tryLock(nanos, TimeUnit.NANOSECONDS)) {
                        return false;
                    }

                    lock2 = destination.lock();
                    if (!lock2.tryLock(nanos, TimeUnit.NANOSECONDS)) {
                        lock1.unlock();
                        delay(nanos);
                        continue;
                    }

                    try {
                        if (source.getBalance().compareTo(amount) < 0) {
                            throw new InsufficientFundsException(
                                "Insufficient funds in source account"
                            );
                        }

                        source.withdraw(amount);
                        destination.deposit(amount);
                        return true;
                    } finally {
                        lock1.unlock();
                        lock2.unlock();
                    }
                }

            } catch (TimeoutException | InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            } finally {
                if (lock1 != null && lock1.isHeldByCurrentThread()) lock1.unlock();
                if (lock2 != null && lock2.isHeldByCurrentThread()) lock2.unlock();
            }

            return false;
        }

        private void delay(long timeout) throws InterruptedException {
            long fixed = calculateFixedDelay(timeout);
            int random = ThreadLocalRandom.current().nextInt(0, 3);
            TimeUnit.MILLISECONDS.sleep(fixed + random);
        }

        private long calculateFixedDelay(long timeout) {
            return timeout / 10;
