    public static boolean transfer(Account source, Account destination, DollarAmount amount,
                                  long timeout, TimeUnit unit) {
        long timeoutMs = unit.toMillis(timeout);
        int maxRetries = 5;

        Random random = new Random();

        for (int retry = 0; retry < maxRetries; retry++) {
            boolean acquiredSource = false;
            boolean acquiredDestination = false;

            try {
                acquiredSource = source.lock.tryLock(timeoutMs, TimeUnit.MILLISECONDS);
                if (!acquiredSource) break;

                acquiredDestination = destination.lock.tryLock(timeoutMs, TimeUnit.MILLISECONDS);
                if (acquiredDestination) {
                    if (source.getBalance().compareTo(amount) >= 0) {
                        source.debit(amount);
                        destination.credit(amount);
                        return true;
                    } else {
                        throw new InsufficientFundsException("Insufficient funds in source account");
                    }
                }

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            } finally {
                if (acquiredSource) source.lock.unlock();
                if (acquiredDestination) destination.lock.unlock();
            }

            long delay = calculateFixedDelay() + calculateRandomDelay(random);
            try {
                TimeUnit.MILLISECONDS.sleep(delay);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        return false;
    }

