                if (!isEmpty()) { // This check is theoretically redundant due to semaphores
                    result = (E) buffer[tail];
                    tail = (tail + 1) % buffer.length;
                    count--;
                }
            } finally {
                lock.unlock();
                spaceSemaphore.release();
            }
            return result;
        }

        public boolean isEmpty() {
            return count == 0;
        }

        public boolean isFull() {
            return count == buffer.length;
