import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class MyAppThread extends Thread {
    private static final String DEFAULT_NAME = "MyAppThread";
    private static final AtomicInteger threadNumber = new AtomicInteger(1);
    private static final Logger logger = Logger.getLogger(MyAppThread.class.getName());

    private static volatile boolean debugLifecycle = false;
    public static AtomicInteger created = new AtomicInteger(0);
    public static AtomicInteger alive = new AtomicInteger(0);

    public MyAppThread() {
        super(DEFAULT_NAME + "-" + threadNumber.getAndIncrement());
        created.incrementAndGet();
        setUncaughtExceptionHandler((thread, exception) -> {
            logger.severe("Uncaught exception in thread " + thread.getName() + ": " + exception.getMessage());
        });
    }

    public MyAppThread(Runnable target) {
        this();
        super(target);
    }

    @Override
    public void run() {
        if (debugLifecycle) {
            logger.info("Starting thread: " + getName());
        }
        try {
            alive.incrementAndGet();
            super.run();
        } finally {
            alive.decrementAndGet();
            if (debugLifecycle) {
                logger.info("Terminating thread: " + getName());
            }
        }
    }

    public static int getCreated() {
        return created.get();
    }

    public static int getAlive() {
        return alive.get();
    }

    public static void setDebug(boolean debug) {
        debugLifecycle = debug;
    }

    public static class MyTask implements Runnable {
        private final String taskName;

        public MyTask(String name) {
            this.taskName = name;
        }

        @Override
        public void run() {
            try {
                logger.info(taskName + " is running on thread: " + Thread.currentThread().getName());
                Thread.sleep(100);
            } catch (InterruptedException e) {
                logger.warning("Task interrupted: " + taskName);
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        setDebug(true);

        // Create and start two custom threads
        MyAppThread thread1 = new MyAppThread(new MyTask("Task 1"));
        MyAppThread thread2 = new MyAppThread(new MyTask("Task 2"));

        thread1.start();
        thread2.start();

        // Use executor service to manage additional threads
        ExecutorService executor = Executors.newFixedThreadPool(3);
        for (int i = 0; i < 3; i++) {
            int taskNumber = i + 1;
            executor.submit(new MyTask("Executor Task " + taskNumber));
        }

        // Wait for custom threads to finish
        thread1.join();
        thread2.join();

        // Shutdown executor and wait for tasks to complete
        executor.shutdown();
