}

import java.time.LocalDateTime;
import java.util.concurrent.TimeUnit;

public class MyAppThread extends Thread {
    private static final String DEFAULT_NAME = "MyAppThread";
    private static final AtomicInteger created = new AtomicInteger(0);
    private static final AtomicInteger alive = new AtomicInteger(0);
    private static final AtomicInteger threadNameCounter = new AtomicInteger(0);
    private static volatile boolean debugLifecycle = false;

    // Logger implementation
    private static final class Logger {
        private static void log(String level, String message) {
            System.out.println("[" + LocalDateTime.now() + "] " + level + ": " + message);
        }
    }

    public MyAppThread() {
        this(DEFAULT_NAME + threadNameCounter.getAndIncrement());
        created.getAndIncrement();
    }

    public MyAppThread(Runnable target) {
        this(DEFAULT_NAME + threadNameCounter.getAndIncrement(), target);
    }

    public MyAppThread(String name) {
        super(name);
        created.getAndIncrement();
    }

    public MyAppThread(String name, Runnable target) {
        super(name);
        setTarget(target);
        created.getAndIncrement();
    }

    public static int getCreatedCount() {
        return created.get();
    }

    public static int getActiveCount() {
        return alive.get();
    }

    public static void setDebug(boolean debug) {
        debugLifecycle = debug;
    }

    @Override
    public void run() {
        try {
            if (debugLifecycle) {
                Logger.log("INFO", "Thread " + getName() + " is starting.");
            }
            alive.incrementAndGet();
            super.run();
        } finally {
            alive.decrementAndGet();
            if (debugLifecycle) {
                Logger.log("INFO", "Thread " + getName() + " terminated.");
            }
        }
    }

    static {
        // Set default uncaught exception handler
        Thread.setDefaultUncaughtExceptionHandler((thread, throwable) -> {
            Logger.log("SEVERE", "Uncaught exception in thread " + thread.getName() +
                    ": " + throwable.toString());
        });
    }

