import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class PrimeGenerator implements Runnable {
    private volatile boolean cancelled = false;
    private final List<Integer> primes = new CopyOnWriteArrayList<>();
    private ExecutorService executor;
    private ScheduledExecutorService scheduler;

    public void start() {
        executor = Executors.newSingleThreadExecutor();
        scheduler = Executors.newScheduledThreadPool(1);

        executor.submit(this);

        // Schedule cancellation after 1 second
        scheduler.schedule(() -> cancel(), 1, TimeUnit.SECONDS);
    }

    public void cancel() {
        cancelled = true;
    }

    @Override
    public void run() {
        int count = 0;
        int number = 2;

        while (!cancelled && count < 10) {
            if (isPrime(number)) {
                primes.add(number);
                count++;
            }
            number++;

            try {
                Thread.sleep(1); // Minimal delay to prevent busy looping
            } catch (InterruptedException e) {
                break;
            }
        }
    }

    private boolean isPrime(int num) {
        if (num <= 1) return false;
        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }

    public List<Integer> getPrimes() {
        return primes;
    }

    public static void main(String[] args) throws InterruptedException {
        PrimeGenerator generator = new PrimeGenerator();
        generator.start();

        // Allow some time for generation
        TimeUnit.SECONDS.sleep(2);

        generator.cancel();
        System.out.println("Generated primes: " + generator.getPrimes());
    }
}

