import java.util.Objects;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class StripedMap {
    private static final int N_LOCKS = 16;
    private final Node[] buckets;
    private final Object[] locks;

    public static class Node {
        final Object key;
        Object value;
        Node next;

        Node(Object key, Object value) {
            this.key = key;
            this.value = value;
        }
    }

    public StripedMap(int numBuckets) {
        buckets = new Node[numBuckets];
        locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private int hashIndex(Object key) {
        return Objects.hashCode(key) % buckets.length;
    }

    public Object get(Object key) {
        int index = hashIndex(key);
        Object lock = locks[index % N_LOCKS];
        synchronized (lock) {
            Node current = buckets[index];
            while (current != null) {
                if (current.key.equals(key)) {
                    return current.value;
                }
                current = current.next;
            }
            return null;
        }
    }

    public void put(Object key, Object value) {
        int index = hashIndex(key);
        Object lock = locks[index % N_LOCKS];
        synchronized (lock) {
            Node current = buckets[index];
            while (current != null) {
                if (current.key.equals(key)) {
                    current.value = value;
                    return;
                }
                current = current.next;
            }
            buckets[index] = new Node(key, value);
        }
    }

    public void clear() {
        for (int i = 0; i < buckets.length; i++) {
            Object lock = locks[i % N_LOCKS];
            synchronized (lock) {
                buckets[i] = null;
            }
        }
    }

    public static void main(String[] args) {
        final StripedMap map = new StripedMap(16);
        ExecutorService executor = Executors.newFixedThreadPool(4);

        Runnable task = () -> {
            for (int i = 0; i < 3; i++) {
                int key = (int) (Math.random() * 2);
                double value = Math.random();
                map.put(key, value);
                System.out.println("Thread " + Thread.currentThread().getId() +
                        " put key: " + key + ", value: " + value);
            }
        };

        Runnable getTask = () -> {
            for (int i = 0; i < 3; i++) {
                int key = (int) (Math.random() * 2);
                Object value = map.get(key);
                System.out.println("Thread " + Thread.currentThread().getId() +
                        " got key: " + key + ", value: " + value);
            }
        };

        for (int i = 0; i < 4; i++) {
            executor.submit(task);
            executor.submit(getTask);
        }

        executor.shutdown();
        while (!executor.isTerminated()) {
        }

        System.out.println("Clearing the map...");
        map.clear();

        System.out.println("Map after clear: " + map.get(0));
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.CountDownLatch;

public class StripedMap<K, V> {

    private static final int N_LOCKS = 16;

    private final Node<K, V>[] buckets;
    private final Object[] locks;

    public StripedMap(int numBuckets) {
        if (numBuckets <= 0) {
            throw new IllegalArgumentException("Number of buckets must be positive");
        }
        this.buckets = new Node[numBuckets];
        for (int i = 0; i < numBuckets; i++) {
            buckets[i] = null;
        }
        this.locks = new Object[N_LOCKS];
        for (int i = 0; i < N_LOCKS; i++) {
            locks[i] = new Object();
        }
    }

    private int computeHashIndex(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        return Math.abs(key.hashCode()) % buckets.length;
    }

    public V get(K key) {
        int hashIndex = computeHashIndex(key);
        Object lock = locks[hashIndex % N_LOCKS];
        synchronized (lock) {
            Node<K, V> current = buckets[hashIndex];
            while (current != null) {
                if (current.key.equals(key)) {
                    return current.value;
                }
                current = current.next;
            }
            return null;
        }
    }

    public V put(K key, V value) {
        int hashIndex = computeHashIndex(key);
        Object lock = locks[hashIndex % N_LOCKS];
        synchronized (lock) {
            Node<K, V> current = buckets[hashIndex];
            while (current != null) {
                if (current.key.equals(key)) {
                    V oldValue = current.value;
                    current.value = value;
                    return oldValue;
                }
                current = current.next;
            }
            Node<K, V> newNode = new Node<>(key, value, buckets[hashIndex]);
            buckets[hashIndex] = newNode;
            return null;
        }
    }

    public void clear() {
        for (int l = 0; l < N_LOCKS; l++) {
            Object lock = locks[l];
            synchronized (lock) {
                int i;
                for (i = l; i < buckets.length; i += N_LOCKS) {
                    buckets[i] = null;
                }
            }
        }
    }

    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> next;

        Node(K key, V value, Node<K, V> next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        StripedMap<String, String> map = new StripedMap<>(64);

        ExecutorService executor = Executors.newFixedThreadPool(4);
        CountDownLatch latch = new CountDownLatch(5); // 5 tasks

        // Task 1: Put some keys
        executor.submit(() -> {
            for (int i = 0; i < 10; i++) {
                String key = "key" + i;
                String value = "value" + i;
                map.put(key, value);
            }
            latch.countDown();
        });

        // Task 2: Get some keys
        executor.submit(() -> {
            for (int i = 0; i < 10; i++) {
                String key = "key" + i;
                System.out.println("Got: " + map.get(key));
            }
            latch.countDown();
        });

        // Task 3: Put some overlapping keys
        executor.submit(() -> {
            for (int i = 5; i < 15; i++) {
                String key = "key" + i;
                String value = "newvalue" + i;
                map.put(key, value);
            }
            latch.countDown();
        });

        // Task 4: Get some overlapping keys
        executor.submit(() -> {
            for (int i = 5; i < 15; i++) {
                String key = "key" + i;
                System.out.println("Got after update: " + map.get(key));
            }
            latch.countDown();
        });

        // Task 5: Clear the map
        executor.submit(() -> {
            try {
                Thread.sleep(1000); // Wait for other tasks to complete
                map.clear();
                System.out.println("Map cleared");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            latch.countDown();
        });

        // Wait for all tasks to finish
        latch.await();

        executor.shutdownNow(); // Force shutdown after testing

        System.out.println("Main thread exiting");
    }

}

