import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class MainClass {
    private static class Point {
        public final int x;
        public final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    private static class PointDistanceTask implements Runnable {
        private final AtomicInteger totalDistance;

        PointDistanceTask(AtomicInteger totalDistance) {
            this.totalDistance = totalDistance;
        }

        @Override
        public void run() {
            List<Point> points = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                int x = (int) (Math.random() * 3);
                int y = (int) (Math.random() * 3);
                points.add(new Point(x, y));
            }

            double sum = 0;
            for (int i = 0; i < points.size(); i++) {
                for (int j = i + 1; j < points.size(); j++) {
                    Point p1 = points.get(i);
                    Point p2 = points.get(j);
                    double dx = p2.x - p1.x;
                    double dy = p2.y - p1.y;
                    sum += Math.sqrt(dx * dx + dy * dy);
                }
            }

            totalDistance.addAndGet(sum);
        }
    }

    public static void main(String[] args) {
        AtomicInteger totalDistance = new AtomicInteger(0);
        ExecutorService executor = Executors.newFixedThreadPool(5);

        try {
            for (int i = 0; i < 5; i++) {
                executor.submit(new PointDistanceTask(totalDistance));
            }
        } finally {
            executor.shutdown();
        }

        while (!executor.isTerminated()) {
            try {
                executor.awaitTermination(1, TimeUnit.SECONDS);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        System.out.println("Total distance: " + totalDistance.get());
    }
}

