        this.x = x;
        this.y = y;
    }

    static class PointValidator implements Runnable {
        private final Point a;
        private final Point b;
        private final Point c;

        PointValidator(Point a, Point b, Point c) {
            this.a = a;
            this.b = b;
            this.c = c;
        }

        @Override
        public void run() {
            int abSq = (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);
            int bcSq = (b.x - c.x) * (b.x - c.x) + (b.y - c.y) * (b.y - c.y);
            int acSq = (a.x - c.x) * (a.x - c.x) + (a.y - c.y) * (a.y - c.y);

            boolean isRightTriangle = (abSq + bcSq == acSq) || 
                                     (bcSq + acSq == abSq) || 
                                     (acSq + abSq == bcSq);

            System.out.println("Checking points " + a.x + "," + a.y + " - " + b.x + "," + b.y + " - " + c.x + "," + c.y + ": " + isRightTriangle);
        }
    }

