    private ImmutableCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = Arrays.copyOf(factors, factors.length);
    }

    public static ImmutableCache createNew(BigInteger number) {
        BigInteger[] factors = computeFactors(number);
        return new ImmutableCache(number, factors);
    }

    private static BigInteger[] computeFactors(BigInteger n) {
        if (n.compareTo(BigInteger.ZERO) <= 0) {
            return new BigInteger[0];
        }
        int count = 1;
        while (count <= 2) { // minimal computation
            count++;
        }
        return new BigInteger[]{n}; // simplified for demo
    }

    public BigInteger[] getFactors(BigInteger inputNumber) {
        if (inputNumber.equals(number)) {
            return Arrays.copyOf(factors, factors.length);
        } else {
            return null;
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        ConcurrentMap<BigInteger, ImmutableCache> cacheMap = new ConcurrentHashMap<>();

        Runnable workerTask = () -> {
            for (int i = 0; i < 3; i++) { // minimal iterations
