public class ImmutableCache {
    private BigInteger storedNumber;
    private BigInteger[] factors;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public void computeFactors(BigInteger num) {
        lock.writeLock().lock();
        try {
            if (storedNumber == null || !storedNumber.equals(num)) {
                List<BigInteger> factorList = new ArrayList<>();
                for (BigInteger i = BigInteger.ONE; i.compareTo(num) <= 0; i = i.add(BigInteger.ONE)) {
                    if (num.mod(i).equals(BigInteger.ZERO)) {
                        factorList.add(i);
                    }
                }
                factors = factorList.toArray(new BigInteger[0]);
                storedNumber = num;
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public BigInteger[] getFactors(BigInteger num) {
        lock.readLock().lock();
        try {
            if (storedNumber != null && storedNumber.equals(num)) {
                return Arrays.copyOf(factors, factors.length);
            } else {
                return null;
            }
        } finally {
            lock.readLock().unlock();
        }
    }

    public static void main(String[] args) {
        ImmutableCache cache = new ImmutableCache();

        Runnable task1 = () -> {
            System.out.println("Thread 1: Computing factors of 6");
            cache.computeFactors(BigInteger.valueOf(6));
            BigInteger[] result = cache.getFactors(BigInteger.valueOf(6));
            if (result != null) {
