import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicReference;

public class ImmutableCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public ImmutableCache(BigInteger number, BigInteger[] factors) {
        this.number = number;
        this.factors = Arrays.copyOf(factors, factors.length);
    }

    public BigInteger getNumber() {
        return number;
    }

    public BigInteger[] getFactors() {
        return Arrays.copyOf(factors, factors.length);
    }
}

class CacheManager {
    private final AtomicReference<ImmutableCache> cacheRef;

    public CacheManager() {
        this.cacheRef = new AtomicReference<>();
    }

    public ImmutableCache getCurrentCache() {
        return cacheRef.get();
    }

    public void updateCache(ImmutableCache newCache) {
        while (true) {
            ImmutableCache current = cacheRef.get();
            if (current == null || !current.getNumber().equals(newCache.getNumber())) {
                if (cacheRef.compareAndSet(current, newCache)) {
                    break;
                }
            } else {
                // Cache already contains this number; no update needed
                break;
            }
        }
    }

    private static BigInteger[] computeFactors(BigInteger number) {
        List<BigInteger> factors = new ArrayList<>();
        for (BigInteger i = BigInteger.ONE; i.compareTo(number.sqrt().add(BigInteger.ONE)) <= 0; i = i.add(BigInteger.ONE)) {
            if (number.mod(i).equals(BigInteger.ZERO)) {
                factors.add(i);
                BigInteger otherFactor = number.divide(i);
                if (!otherFactor.equals(i)) { // Avoid duplicates for perfect squares
                    factors.add(otherFactor);
                }
            }
        }
        Collections.sort(factors);
        return factors.toArray(new BigInteger[0]);
    }

    public static void main(String[] args) throws InterruptedException {
        int poolSize = 2;
        ExecutorService executor = Executors.newFixedThreadPool(poolSize);
        CacheManager manager = new CacheManager();

        List<BigInteger> numbersToProcess = Arrays.asList(
            BigInteger.valueOf(6),
            BigInteger.valueOf(8),
            BigInteger.valueOf(10)
        );

        for (final BigInteger num : numbersToProcess) {
            executor.submit(() -> {
                while (true) {
                    ImmutableCache currentCache = manager.getCurrentCache();
                    if (currentCache != null && currentCache.getNumber().equals(num)) {
                        // Factors are already in cache
                        break;
                    } else {
                        // Compute factors and update cache
                        BigInteger[] factors = computeFactors(num);
                        ImmutableCache newCache = new ImmutableCache(num, factors);
                        manager.updateCache(newCache);
                        continue; // Check again to ensure successful update
                    }
                }
            });
        }

        executor.shutdown();
        while (!executor.isTerminated()) {}
    }
}

