import java.util.AbstractList;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ImproveList<E> extends AbstractList<E> {
    private final List<E> delegate;
    private final Object lock = new Object();

    public ImproveList(List<E> delegate) {
        this.delegate = delegate;
    }

    @Override
    public boolean add(E e) {
        synchronized (lock) {
            return delegate.add(e);
        }
    }

    @Override
    public void add(int index, E element) {
        synchronized (lock) {
            delegate.add(index, element);
        }
    }

    @Override
    public boolean addAll(Collection<? extends E> c) {
        synchronized (lock) {
            return delegate.addAll(c);
        }
    }

    @Override
    public boolean addAll(int index, Collection<? extends E> c) {
        synchronized (lock) {
            return delegate.addAll(index, c);
        }
    }

    @Override
    public E remove(int index) {
        synchronized (lock) {
            return delegate.remove(index);
        }
    }

    @Override
    public boolean remove(Object o) {
        synchronized (lock) {
            return delegate.remove(o);
        }
    }

    @Override
    public boolean removeAll(Collection<?> c) {
        synchronized (lock) {
            return delegate.removeAll(c);
        }
    }

    @Override
    public boolean retainAll(Collection<?> c) {
        synchronized (lock) {
            return delegate.retainAll(c);
        }
    }

    @Override
    public void clear() {
        synchronized (lock) {
            delegate.clear();
        }
    }

    @Override
    public E set(int index, E element) {
        synchronized (lock) {
            return delegate.set(index, element);
        }
    }

    @Override
    public int size() {
        return delegate.size();
    }

    @Override
    public boolean contains(Object o) {
        return delegate.contains(o);
    }

    @Override
    public Object[] toArray() {
        return delegate.toArray();
    }

    @Override
    public <T> T[] toArray(T[] a) {
        return delegate.toArray(a);
    }

    @Override
    public int indexOf(Object o) {
        return delegate.indexOf(o);
    }

    @Override
    public int lastIndexOf(Object o) {
        return delegate.lastIndexOf(o);
    }

    @Override
    public boolean isEmpty() {
        return delegate.isEmpty();
    }

    @Override
    public Iterator<E> iterator() {
        return new Iterator<E>() {
            private final Iterator<E> delegateIterator = delegate.iterator();

            @Override
            public boolean hasNext() {
                return delegateIterator.hasNext();
            }

            @Override
            public E next() {
                return delegateIterator.next();
            }

            @Override
            public void remove() {
                synchronized (lock) {
                    delegateIterator.remove();
                }
            }
        };
    }

    public boolean putIfAbsent(E element) {
        synchronized (lock) {
            if (!delegate.contains(element)) {
                add(element);
                return true;
            }
            return false;
        }
    }

    public static void main(String[] args) {
        List<String> list = new ImproveList<>(new ArrayList<>());
        ExecutorService service = Executors.newFixedThreadPool(2);

        Runnable task = () -> {
            for (int i = 0; i < 3; i++) {
                boolean added = list.putIfAbsent("test");
                System.out.println("Thread " + Thread.currentThread().getName() + " added: " + added);
            }
        };

        service.submit(task);
        service.submit(task);

        service.shutdown();
        try {
