import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

interface Account {
    DollarAmount getBalance();
    void deposit(DollarAmount amount);
    void withdraw(DollarAmount amount) throws InsufficientFundsException;
}

interface DollarAmount {
    int getValue();
}

class TransferHelper {
    public void transfer(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
        Object lock1 = from;
        Object lock2 = to;
        if (lock1.hashCode() > lock2.hashCode()) {
            Object temp = lock1;
            lock1 = lock2;
            lock2 = temp;
        }
        synchronized (lock1) {
            synchronized (lock2) {
                checkBalance(from, amount);
                from.withdraw(amount);
                to.deposit(amount);
            }
        }
    }

    private void checkBalance(Account account, DollarAmount amount) throws InsufficientFundsException {
        if (account.getBalance().getValue() < amount.getValue()) {
            throw new InsufficientFundsException("Insufficient funds: " + amount.getValue());
        }
    }
}

class AccountImpl implements Account {
    private int balance;

    public AccountImpl(int initialBalance) {
        this.balance = initialBalance;
    }

    @Override
    public DollarAmount getBalance() {
        return () -> balance;
    }

    @Override
    public void deposit(DollarAmount amount) {
        this.balance += amount.getValue();
    }

    @Override
    public void withdraw(DollarAmount amount) throws InsufficientFundsException {
        if (balance < amount.getValue()) {
            throw new InsufficientFundsException("Insufficient funds: " + amount.getValue());
        }
        this.balance -= amount.getValue();
    }
}

class DollarAmountImpl implements DollarAmount {
    private int value;

    public DollarAmountImpl(int value) {
        this.value = value;
    }

    @Override
    public int getValue() {
