import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

interface Account {
    int getBalance();
    void setBalance(int balance);
}

interface DollarAmount {
    int getValue();
    DollarAmount add(DollarAmount other);
    DollarAmount subtract(DollarAmount other);
}

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

class TransferHelper {
    private static final Object TIE_BREAKER = new Object();

    synchronized void transfer(Account source, Account destination, DollarAmount amount) throws InsufficientFundsException {
        int hash1 = System.identityHashCode(source);
        int hash2 = System.identityHashCode(destination);

        if (hash1 != hash2) {
            if (hash1 < hash2) {
                synchronized (source) {
                    synchronized (destination) {
                        checkAndTransfer(source, destination, amount);
                    }
                }
            } else {
                synchronized (destination) {
                    synchronized (source) {
                        checkAndTransfer(source, destination, amount);
                    }
                }
            }
        } else {
            synchronized (source) {
                synchronized (TIE_BREAKER) {
                    checkAndTransfer(source, destination, amount);
                }
            }
        }
    }

    private void checkAndTransfer(Account source, Account destination, DollarAmount amount) throws InsufficientFundsException {
        int required = amount.getValue();
        if (source.getBalance() < required) {
            throw new InsufficientFundsException("Insufficient funds in source account");
        }
        source.setBalance(source.getBalance() - required);
        destination.setBalance(destination.getBalance() + required);
    }
}

