import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class AccountTransfer {
    public interface Account {
        DollarAmount getBalance();
        void debit(DollarAmount amount);
        void credit(DollarAmount amount);
    }

    public interface DollarAmount {
        int value();
    }

    static class InsufficientFundsException extends Exception {}

    static class TransferHelper {
        private static final Object tieBreaker = new Object();

        public static void transfer(Account from, Account to, DollarAmount amount) throws InsufficientFundsException {
            int hashFrom = System.identityHashCode(from);
            int hashTo = System.identityHashCode(to);

            if (hashFrom < hashTo) {
                synchronized (from) {
                    synchronized (to) {
                        validateBalanceAndTransfer(from, amount);
                        from.debit(amount);
                        to.credit(amount);
                    }
                }
            } else if (hashTo < hashFrom) {
                synchronized (to) {
                    synchronized (from) {
                        validateBalanceAndTransfer(from, amount);
                        from.debit(amount);
                        to.credit(amount);
                    }
                }
            } else {
                synchronized (tieBreaker) {
                    synchronized (from) {
                        synchronized (to) {
                            validateBalanceAndTransfer(from, amount);
                            from.debit(amount);
                            to.credit(amount);
                        }
                    }
                }
            }
        }

        private static void validateBalanceAndTransfer(Account from, DollarAmount amount) throws InsufficientFundsException {
            if (from.getBalance().value() < amount.value()) {
                throw new InsufficientFundsException();
            }
        }
    }

    static class SimpleAccount implements Account {
        private DollarAmount balance;

        public SimpleAccount(DollarAmount initialBalance) {
            this.balance = initialBalance;
        }

        @Override
        public synchronized DollarAmount getBalance() {
            return balance;
        }

        @Override
        public synchronized void debit(DollarAmount amount) {
            int current = balance.value();
            int debitAmount = amount.value();
            if (current < debitAmount) {
                throw new InsufficientFundsException();
            }
            this.balance = new FixedDollarAmount(current - debitAmount);
        }

        @Override
        public synchronized void credit(DollarAmount amount) {
            int current = balance.value();
            int creditAmount = amount.value();
            this.balance = new FixedDollarAmount(current + creditAmount);
        }
    }

    static class FixedDollarAmount implements DollarAmount {
        private final int value;

        public FixedDollarAmount(int value) {
            this.value = value;
        }

        @Override
        public int value() {
            return value;
        }
    }

    public static void main(String[] args) {
        Account accountA = new SimpleAccount(new FixedDollarAmount(100));
        Account accountB = new SimpleAccount(new FixedDollarAmount(50));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable transferAB = () -> {
            try {
                TransferHelper.transfer(accountA, accountB, new FixedDollarAmount(50));
                System.out.println("Transfer A->B: $50");
            } catch (InsufficientFundsException e) {
                System.err.println("Insufficient funds in A for transfer to B");
            }
        };

        Runnable transferBA = () -> {
            try {
                TransferHelper.transfer(accountB, accountA, new FixedDollarAmount(30));
                System.out.println("Transfer B->A: $30");
            } catch (InsufficientFundsException e) {
                System.err.println("Insufficient funds in B for transfer to A");
            }
        };

        executor.submit(transferAB);
        executor.submit(transferBA);

        executor.shutdown();
    }
}

