    public MonitorVehicleTracker(Map<String, MutablePoint> initialMap) {
        this.vehicleLocations = deepCopy(initialMap);
    }

    public synchronized Map<String, MutablePoint> getLocations() {
        return Collections.unmodifiableMap(deepCopy(vehicleLocations));
    }

    public synchronized MutablePoint getLocation(String id) {
        if (!vehicleLocations.containsKey(id)) {
