        Map<String, MutablePoint> copy = new HashMap<>();
        for (Map.Entry<String, MutablePoint> entry : originalMap.entrySet()) {
            String key = entry.getKey();
            MutablePoint value = entry.getValue();
            copy.put(key, new MutablePoint(value.x, value.y));
