import java.util.Collections;
import java.util.ConcurrentMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DelegatingVehicleTracker {
    private final ConcurrentMap<String, Point> vehicles;

    public DelegatingVehicleTracker(Map<String, Point> initialLocations) {
        this.vehicles = new ConcurrentHashMap<>(initialLocations);
    }

    public Point getVehicleLocation(String id) {
        return vehicles.get(id);
    }

    public void setVehicleLocation(String id, Point location) {
        vehicles.compute(id, (k, v) -> {
            if (v == null) {
                throw new IllegalArgumentException("Vehicle not found: " + id);
            }
            return location;
        });
    }

    public Map<String, Point> getAllLocationsLive() {
        return Collections.unmodifiableMap(vehicles);
    }

    public Map<String, Point> getAllLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(vehicles));
    }

    public static void main(String[] args) {
        Map<String, Point> initial = new HashMap<>();
        initial.put("A", new Point(1, 2));
        initial.put("B", new Point(3, 4));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            try {
                Thread.sleep(100);
                tracker.setVehicleLocation("A", new Point(5, 6));
                System.out.println("Thread 1 updated A to (5,6)");
                Point aLoc = tracker.getVehicleLocation("A");
                System.out.println("Thread 1 retrieved A's location: " + aLoc);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        executor.submit(() -> {
            try {
                Thread.sleep(200);
                Point bLoc = tracker.getVehicleLocation("B");
                System.out.println("Thread 2 retrieved B's location: " + bLoc);
                tracker.setVehicleLocation("C", new Point(7, 8)); // This should throw an exception
            } catch (IllegalArgumentException e) {
                System.out.println("Thread 2 caught exception: " + e.getMessage());
            }
        });

        executor.submit(() -> {
            try {
                Thread.sleep(150);
                Map<String, Point> snapshot = tracker.getAllLocationsSnapshot();
                System.out.println("Snapshot in thread 3: " + snapshot);
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private static class Point {
        int x;
        int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }
}

