    }

    public Point getVehicleLocation(String id) {
        return vehicles.get(id);
    }

    public void setVehicleLocation(String id, Point location) {
        boolean success = vehicles.replace(id, location);
        if (!success) {
            throw new IllegalArgumentException("Vehicle not found: " + id);
        }
    }

    public Map<String, Point> getAllLocationsLive() {
        return Collections.unmodifiableMap(vehicles);
    }

    public Map<String, Point> getAllLocationsSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(vehicles));
    }

    public static class Point {
        int x;
        int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    public static void main(String[] args) {
        Map<String, Point> initial = new HashMap<>();
        initial.put("V1", new Point(0, 0));
        initial.put("V2", new Point(1, 1));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initial);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable task1 = () -> {
            for (int i = 0; i < 3; i++) {
                Point current = tracker.getVehicleLocation("V1");
                System.out.println("Thread 1: V1 is at " + current);
                int newX = current.x + 1;
                int newY = current.y + 1;
                tracker.setVehicleLocation("V1", new Point(newX, newY));
                System.out.println("Thread 1 set V1 to (" + newX + "," + newY + ")");
            }
        };

        Runnable task2 = () -> {
            for (int i = 0; i < 3; i++) {
                Point current = tracker.getVehicleLocation("V2");
                System.out.println("Thread 2: V2 is at " + current);
                int newX = current.x - 1;
                int newY = current.y - 1;
                tracker.setVehicleLocation("V2", new Point(newX, newY));
                System.out.println("Thread 2 set V2 to (" + newX + "," + newY + ")");
            }
        };

        executor.submit(task1);
        executor.submit(task2);

        executor.shutdown();
        try {
            if (!executor.awaitTermination(1, TimeUnit.MINUTES)) {
                executor.shutdownNow();
                throw new TimeoutException("Tasks did not finish in time.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return;
        }

        System.out.println("\nFinal vehicle locations:");
        Map<String, Point> snapshot = tracker.getAllLocationsSnapshot();
        for (Map.Entry<String, Point> entry : snapshot.entrySet()) {
            System.out.println(entry.getKey() + " is at " + entry.getValue());
        }
    }

    private static class TimeoutException extends RuntimeException {
        public TimeoutException(String message) {
            super(message);
        }
    }
}

import java.util.concurrent.ConcurrentHashMap;
