import java.util.Map;

public class DelegatingVehicleTracker {
    private final Map<String, String> concurrentMap = new ConcurrentHashMap<>();

    public DelegatingVehicleTracker(Map<String, String> initialLocations) {
        concurrentMap.putAll(initialLocations);
    }

    public String getLocation(String vehicleId) {
        return concurrentMap.get(vehicleId);
    }

    public boolean setLocation(String vehicleId, String location) {
        return concurrentMap.computeIfPresent(vehicleId, (id, loc) -> {
            concurrentMap.put(id, location);
            return null;
        }) != null;
    }

    public Map<String, String> allLocations() {
        return Map.copyOf(concurrentMap);
    }

    public Map<String, String> snapshotAllLocations() {
        return Map.copyOf(concurrentMap);
    }

    public static void main(String[] args) {
        Map<String, String> initialLocations = new ConcurrentHashMap<>();
        initialLocations.put("Vehicle1", "LocationA");
        initialLocations.put("Vehicle2", "LocationB");

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable updateTask = () -> {
            String[] locations = {"NewLocation1", "NewLocation2"};
            while (true) {
                try {
                    for (String vehicle : tracker.allLocations().keySet()) {
                        int randomIndex = (int) (Math.random() * 2);
                        boolean success = tracker setLocation(vehicle, locations[randomIndex]);
                        System.out.println("Updated " + vehicle + " to " + locations[randomIndex] + ": " + success);
                    }
                } catch (Exception e) {
                    break;
                }
            }
        };

        Runnable readTask = () -> {
            while (true) {
                try {
                    System.out.println("\nCurrent Locations:");
                    tracker.allLocations().forEach((k, v) -> 
                        System.out.println(k + " at " + v)
                    );
                    TimeUnit.SECONDS.sleep(1);
                } catch (Exception e) {
                    break;
                }
            }
        };

        executor.execute(updateTask);
        executor.execute(readTask);

        try {
            TimeUnit.SECONDS.sleep(5);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        executor.shutdownNow();
        System.out.println("\nFinal Locations:");
        tracker.snapshotAllLocations().forEach((k, v) -> 
            System.out.println(k + " at " + v)
        );
    }
}

