import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ArkLoader {

    public static Ark loadTheArk(List<Animal> candidates) {
        // Step 1: Sort the animals by species and then by gender (male before female)
        List<Animal> sorted = new ArrayList<>(candidates);
        sorted.sort(Comparator.comparing(Animal::getSpecies).thenComparing(a -> a.getGender()));

        // Step 2: Group animals by species
        List<List<Animal>> groups = new ArrayList<>();
        if (!sorted.isEmpty()) {
            String currentSpecies = sorted.get(0).getSpecies();
            List<Animal> currentGroup = new ArrayList<>();
            for (Animal animal : sorted) {
                if (animal.getSpecies().equals(currentSpecies)) {
                    currentGroup.add(animal);
                } else {
                    groups.add(currentGroup);
                    currentGroup = new ArrayList<>();
                    currentSpecies = animal.getSpecies();
                    currentGroup.add(animal);
                }
            }
            groups.add(currentGroup); // Add the last group
        }

        // Step 3: Create an Ark to hold all pairs
        Ark ark = new Ark();

        // Use a fixed thread pool for parallel processing of each species group
        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (List<Animal> group : groups) {
            final List<Animal> speciesGroup = group;
            executor.submit(() -> {
                int malesCount = 0;
                int femalesCount = 0;
                for (Animal animal : speciesGroup) {
                    if (animal.getGender() == Gender.MALE) {
                        malesCount++;
                    } else {
                        femalesCount++;
                    }
                }
                int pairsPossible = Math.min(malesCount, femalesCount);

                int maleIndex = 0;
                int femaleIndex = speciesGroup.size() - 1;

                for (int i = 0; i < pairsPossible; i++) {
                    // Find the next male
                    while (maleIndex <= femaleIndex && speciesGroup.get(maleIndex).getGender() != Gender.MALE) {
                        maleIndex++;
                    }
                    if (maleIndex > femaleIndex) break;

                    // Find the previous female
                    while (femaleIndex >= maleIndex && speciesGroup.get(femaleIndex).getGender() != Gender.FEMALE) {
                        femaleIndex--;
                    }
                    if (femaleIndex < maleIndex) break;

                    Animal male = speciesGroup.get(maleIndex);
                    Animal female = speciesGroup.get(femaleIndex);

                    Pair pair = new Pair(male, female);
                    ark.addPair(pair);

                    maleIndex++;
                    femaleIndex--;
                }
            });
        }

        // Shutdown the executor and wait for all tasks to complete
        executor.shutdown();
        try {
            if (!executor.awaitTermination(1, TimeUnit.MINUTES)) {
                throw new RuntimeException("Tasks did not complete in time");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Interrupted while waiting for tasks", e);
        }

        return ark;
    }
}

class Ark {
    private List<Pair> pairList;

    public Ark() {
        this.pairList = Collections.synchronizedList(new CopyOnWriteArrayList<>());
    }

    public void addPair(Pair pair) {
        synchronized (pairList) { // Ensuring thread-safe addition
            pairList.add(pair);
        }
    }

    public List<Pair> getPairs() {
        return new ArrayList<>(pairList); // Return a copy to prevent modification
    }
}

