        List<Animal> sorted = new ArrayList<>(candidates);
        sorted.sort(new AnimalComparator());

        Ark ark = new Ark();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Runnable pairCreator = () -> {
            Map<String, Integer> counts = new HashMap<>();
            for (Animal animal : sorted) {
                String key = animal.getSpecies().toString();
                if (!counts.containsKey(key)) {
                    counts.put(key, 0);
                }
                int current = counts.get(key);
                if ((current % 2 == 0 && animal.getGender() == Gender.MALE) ||
                    (current % 2 != 0 && animal.getGender() == Gender.FEMALE)) {
                    counts.put(key, current + 1);
                } else {
                    try {
                        Thread.sleep(50);
                    } catch (InterruptedException e) {}
                }
            }

            for (Map.Entry<String, Integer> entry : counts.entrySet()) {
                int pairs = entry.getValue() / 2;
                for (int i = 0; i < pairs; i++) {
