            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {}
            System.out.println("Ark contains: " + ark.getPairs().size() + " pairs");
        };

        executor.submit(pairCreator);
        executor.submit(pairCounter);
        executor.shutdown();

        return ark.getPairs().size();
