import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

public class TimeTaskRunner {
    public static void timeTasks(int n, Runnable task) throws InterruptedException {
        CountDownLatch startLatch = new CountDownLatch(1);
        CountDownLatch endLatch = new CountDownLatch(n);

        Runnable workerRunnable = () -> {
            try {
                startLatch.await();
                for (int i = 0; i < n; i++) {
                    task.run();
                    endLatch.countDown();
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Worker interrupted", e);
            }
        };

        Thread workerThread = new Thread(workerRunnable);
        workerThread.start();

        startLatch.countDown();

        long startTime = System.nanoTime();

        try {
            endLatch.await();
        } catch (InterruptedException e) {
            throw new RuntimeException("Main thread interrupted", e);
        }

        long endTime = System.nanoTime();
        double duration = (endTime - startTime) / 1e6;
        System.out.println(String.format("Tasks completed in %.3f seconds.", duration));
    }

    public static void main(String[] args) throws InterruptedException {
        timeTasks(5, () -> {
            try {
                TimeUnit.MILLISECONDS.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Task interrupted", e);
            }
        });
    }
}

