    }

    public boolean remove(Object o) {
        synchronized (set) {
            if (set.remove(o)) {
                try {
                    semaphore.release();
                    return true;
                } catch (Exception e) {
                    // Ignore exception as release should always succeed
                }
            }
            return false;
        }
    }
}

