        boolean removed = set.remove(o);
        if (removed) {
            try {
                semaphore.release();
            } catch (IllegalStateException e) {
                // This should not happen as removal implies a permit was acquired earlier
                throw new RuntimeException("Failed to release permit after removal", e);
            }
        }
        return removed;
    }

