                } catch (Exception e) {
                    System.out.println("Remove interrupted");
                    return;
                }
                System.out.println("Removed " + value + ": " + removed);
            } catch (Exception e) {
                System.out.println("Error in remove task: " + e.getMessage());
            }
        };

        // Submit multiple tasks
        for (int i=0; i<6; i++) {
            executor.submit(addTask);
        }
        for (int i=0; i<3; i++) {
