import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ArrayBlockingQueue;

public class PrimeNumberProducerConsumer {

    public static void main(String[] args) {
        // Create a BlockingQueue with sufficient capacity to hold primes and sentinel
        BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(3);

        // Instantiate producer and consumer threads
        Thread producerThread = new Thread(new PrimeProducer(queue));
        Thread consumerThread = new Thread(new Consumer(queue));

        // Start both threads
        producerThread.start();
        consumerThread.start();

        try {
            // Wait for the consumer to finish processing
            consumerThread.join();
            // Interrupt the producer after consumer has finished
            producerThread.interrupt();
            // Ensure producer thread exits cleanly
            producerThread.join();
        } catch (InterruptedException e) {
            System.out.println("Main thread was interrupted.");
        }
    }

    static class PrimeProducer implements Runnable {
        private final BlockingQueue<Integer> queue;
        private int targetPrimes = 2;

        PrimeProducer(BlockingQueue<Integer> queue) {
            this.queue = queue;
        }

        @Override
        public void run() {
            try {
                int primesProduced = 0;
                while (primesProduced < targetPrimes && !Thread.currentThread().isInterrupted()) {
                    // Determine the starting candidate for the next prime
                    int candidate = 2;
                    if (!queue.isEmpty()) {
                        Integer lastPrime = queue.peek();
                        if (lastPrime != null) {
                            candidate = lastPrime + 1;
                        }
                    }
                    while (true) {
                        if (isPrime(candidate)) {
                            queue.put(candidate);
                            primesProduced++;
                            break;
                        }
                        candidate++;
                        // Check for interruption
                        if (Thread.currentThread().isInterrupted()) {
                            return;
                        }
                    }
                }
                // Add a sentinel value to signal end of production
                queue.put(null);
            } catch (InterruptedException e) {
                System.out.println("Producer was interrupted.");
            }
        }

        private boolean isPrime(int num) {
            if (num <= 1) {
                return false;
            }
            for (int i = 2; i <= Math.sqrt(num); i++) {
                if (num % i == 0) {
                    return false;
                }
            }
            return true;
        }
    }

    static class Consumer implements Runnable {
        private final BlockingQueue<Integer> queue;

        Consumer(BlockingQueue<Integer> queue) {
            this.queue = queue;
        }

        @Override
        public void run() {
            try {
                while (true) {
                    Integer prime = queue.take();
                    if (prime == null) {
                        // Sentinel indicates end of primes
                        break;
                    }
                    System.out.println("Consumed prime: " + prime);
                }
            } catch (InterruptedException e) {
                System.out.println("Consumer was interrupted.");
            }
        }
    }
}

import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ArrayBlockingQueue;

public class PrimeProducer extends Thread {
    private BlockingQueue<Integer> queue;
    private volatile boolean running = true;

    public PrimeProducer(BlockingQueue<Integer> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            int count = 0;
            while (count < 2 && running) {
                if (Thread.currentThread().isInterrupted()) {
                    break;
                }
                int prime = generateNextPrime();
                queue.put(prime);
                count++;
            }
        } catch (InterruptedException e) {
            // Restore interrupted status
            Thread.currentThread().interrupt();
        } finally {
            running = false;
        }
    }

    private synchronized int generateNextPrime() {
        static int last = 1;
        while (true) {
            last++;
            if (isPrime(last)) {
                return last;
            }
        }
    }

    private boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    public void stopProduction() {
        running = false;
        this.interrupt();
    }
}

class Consumer extends Thread {
    private BlockingQueue<Integer> queue;

    public Consumer(BlockingQueue<Integer> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            int count = 0;
            while (!Thread.currentThread().isInterrupted()) {
                Integer prime = queue.poll(1, java.util.concurrent.TimeUnit.SECONDS);
                if (prime != null) {
                    System.out.println("Consumed prime: " + prime);
                    count++;
                    if (count >= 2) {
                        break;
                    }
                } else {
                    // Timeout occurred, check for interruption
                    if (Thread.currentThread().isInterrupted()) {
                        break;
                    }
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(2);
        PrimeProducer producer = new PrimeProducer(queue);
        Consumer consumer = new Consumer(queue);

        producer.start();
        consumer.start();

        // Wait for producer to finish or up to 5 seconds
        producer.join(5000);
        if (producer.isAlive()) {
            System.out.println("Interrupting producer...");
            producer.stopProduction();
        }

        // Wait for consumer to finish processing available primes
        consumer.join();

        System.out.println("Main thread exiting.");
    }
}

