            try {
                Integer prime = queue.take();
                if (prime == null) {
                    break; // Poison pill indicates end of production
                }
                System.out.println("Consumed: " + prime);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt(); // Restore interrupted status
                break;
            }
        }
    }
}

