import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.Consumer;

public class ConcurrentProcessor {
    public interface Element<T> {
        T process();
    }

    public interface Node<T> {
        T compute();
        List<Node<T>> getChildren();
    }

    private static final ExecutorService executor = Executors.newFixedThreadPool(2);

    public <T> List<T> processSequential(List<Element<T>> elements) {
        List<T> results = new ArrayList<>();
        for (Element<T> element : elements) {
            results.add(element.process());
        }
        return results;
    }

    public <T> List<T> processParallel(List<Element<T>> elements) {
        List<Future<T>> futures = new ArrayList<>();
        try {
            for (Element<T> element : elements) {
                Future<T> future = executor.submit(() -> element.process());
                futures.add(future);
            }
            return collectResults(futures);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private <T> List<T> collectResults(List<Future<T>> futures) throws Exception {
        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            results.add(future.get());
        }
        return results;
    }

    public <T> List<T> processTreeSequential(Node<T> root) {
        List<T> results = new ArrayList<>();
        processNode(root, results);
        return results;
    }

    private <T> void processNode(Node<T> node, List<T> results) {
        T value = node.compute();
        results.add(value);
        for (Node<T> child : node.getChildren()) {
            processNode(child, results);
        }
    }

    public <T> List<T> processTreeParallel(Node<T> root) {
        List<Future<List<T>>> futures = new ArrayList<>();
        try {
            CompletableFuture<List<T>> future = CompletableFuture.supplyAsync(() -> {
                List<T> results = new ArrayList<>();
                results.add(root.compute());
                for (Node<T> child : root.getChildren()) {
                    CompletableFuture<List<T>> childFuture =
                        processChild(child);
                    results.addAll(childFuture.get());
                }
                return results;
            }, executor);
            futures.add(future);
            return collectTreeResults(futures);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private <T> CompletableFuture<List<T>> processChild(Node<T> child) {
        return CompletableFuture.supplyAsync(() -> {
            List<T> results = new ArrayList<>();
            results.add(child.compute());
            for (Node<T> grandchild : child.getChildren()) {
                results.addAll(processChild(grandchild).join());
            }
            return results;
        }, executor);
    }

    private <T> List<T> collectTreeResults(List<Future<List<T>>> futures) throws Exception {
        List<T> results = new ConcurrentLinkedQueue<>();
        for (Future<List<T>> future : futures) {
            List<T> partialResults = future.get();
            results.addAll(partialResults);
        }
        return results;
    }

    public static void main(String[] args) {
        List<Element<String>> elements = List.of(
            () -> "A",
            () -> "B",
            () -> "C"
        );

        Node<Integer> root = new Node<Integer>() {
            @Override
            public Integer compute() { return 1; }
            @Override
            public List<Node<Integer>> getChildren() {
                return List.of(
                    new Node<Integer>() {
                        @Override
                        public Integer compute() { return 2; }
                        @Override
                        public List<Node<Integer>> getChildren() {
                            return List.of(
                                new Node<Integer>() {
                                    @Override
                                    public Integer compute() { return 3; }
                                    @Override
                                    public List<Node<Integer>> getChildren() {
                                        return List.of();
                                    }
                                }
                            );
                        }
                    },
                    new Node<Integer>() {
                        @Override
                        public Integer compute() { return 4; }
                        @Override
                        public List<Node<Integer>> getChildren() {
                            return List.of();
                        }
                    }
                );
            }
        };

        ConcurrentProcessor processor = new ConcurrentProcessor();

        // Sequential processing example
        System.out.println("Sequential element results: " + processor.processSequential(elements));
        System.out.println("Sequential tree results: " + processor.processTreeSequential(root));

        // Parallel processing example
        try {
            System.out.println("Parallel element results: " + processor.processParallel(elements));
            System.out.println("Parallel tree results: " + processor.processTreeParallel(root));
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ConcurrentProcessor {
    interface Element<T> {
        T compute();
    }

    interface Node<T> extends Element<List<T>> {
        List<Node<T>> getChildren();
    }

    public static <T> List<T> processSequentially(List<? extends Element<T>> elements) {
        List<T> results = new ArrayList<>();
        for (Element<T> element : elements) {
            results.add(element.compute());
        }
        return results;
    }

    public static <T> List<T> processParallel(List<? extends Element<T>> elements, ExecutorService executor) {
        List<T> results = Collections.synchronizedList(new ArrayList<>());
        for (Element<T> element : elements) {
            executor.submit(() -> results.add(element.compute()));
        }
        try {
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        return results;
    }

    public static <T> List<T> processTreeSequentially(Node<T> root) {
        List<T> results = new ArrayList<>();
        computeNode(root, results);
        return results;
    }

    private static <T> void computeNode(Node<T> node, List<T> results) {
        List<T> currentResults = node.compute();
        results.addAll(currentResults);
        for (Node<T> child : node.getChildren()) {
            computeNode(child, results);
        }
    }

    public static <T> List<T> processTreeParallel(Node<T> root, ExecutorService executor) {
        List<T> results = Collections.synchronizedList(new ArrayList<>());
        computeNodeParallel(root, executor, results);
        try {
            executor.shutdown();
            executor.awaitTermination(1, TimeUnit.MINUTES);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        return results;
    }

    private static <T> void computeNodeParallel(Node<T> node, ExecutorService executor, List<T> results) {
        executor.submit(() -> {
            List<T> currentResults = node.compute();
            synchronized (results) {
                results.addAll(currentResults);
            }
            for (Node<T> child : node.getChildren()) {
                computeNodeParallel(child, executor, results);
            }
        });
    }

    public static void main(String[] args) {
        Node<String> leaf1 = new SimpleNode<>("Leaf 1", Collections.emptyList());
        Node<String> leaf2 = new SimpleNode<>("Leaf 2", Collections.emptyList());
        Node<String> internalNode = new SimpleNode<>("Internal", List.of(leaf1, leaf2));
        Node<String> root = new SimpleNode<>("Root", List.of(internalNode));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        List<Node<String>> nodes = List.of(root);
        List<String> sequentialResult = processTreeSequentially(root);
        List<String> parallelResult = processTreeParallel(root, executor);

        System.out.println("Sequential result: " + sequentialResult);
        System.out.println("Parallel result: " + parallelResult);
    }

    private static class SimpleNode<T> implements Node<T> {
        private final String name;
        private final List<Node<T>> children;

        public SimpleNode(String name, List<Node<T>> children) {
            this.name = name;
            this.children = children;
        }

        @Override
        public List<T> compute() {
            return List.of(name);
        }

        @Override
        public List<Node<T>> getChildren() {
            return children;
        }
    }
}

