}

class Node implements Element {
    private List<Node> children = new ArrayList<>();
    private final Element element;

    public Node(Element element) {
        this.element = element;
    }

    public void addChild(Node child) {
        children.add(child);
    }

    @Override
    public String compute() {
        return element.compute();
    }

    public List<Node> getChildNodes() {
        return children;
    }
}

class SequentialProcessor {
    public List<String> process(List<Element> elements) {
        List<String> results = new ArrayList<>();
        for (Element element : elements) {
            results.add(element.compute());
        }
        return results;
    }

    public List<String> process(Node root) {
        List<String> results = new ArrayList<>();
        processTree(root, results);
        return results;
    }

    private void processTree(Node node, List<String> results) {
        if (node == null) return;
        results.add(node.compute());
        for (Node child : node.getChildNodes()) {
            processTree(child, results);
        }
    }
}

class ParallelProcessor {
    private final ExecutorService executor;

    public ParallelProcessor(ExecutorService executor) {
        this.executor = executor;
    }

    public List<String> process(List<Element> elements) {
        ConcurrentLinkedQueue<String> resultsQueue = new ConcurrentLinkedQueue<>();
        CountDownLatch latch = new CountDownLatch(elements.size());

        for (Element element : elements) {
            executor.submit(() -> {
                String result = element.compute();
                resultsQueue.add(result);
                latch.countDown();
            });
        }

        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        return new ArrayList<>(resultsQueue);
    }
}

