import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public Lock getReadLock() { return lock.readLock(); }
    public Lock getWriteLock() { return lock.writeLock(); }

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public V get(Object key) {
        try {
            getReadLock().lock();
            return map.get(key);
        } finally {
            getReadLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        try {
            getReadLock().lock();
            return map.containsKey(key);
        } finally {
            getReadLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        try {
            getReadLock().lock();
            return map.containsValue(value);
        } finally {
            getReadLock().unlock();
        }
    }

    public int size() {
        try {
            getReadLock().lock();
            return map.size();
        } finally {
            getReadLock().unlock();
        }
    }

    public boolean isEmpty() {
        try {
            getReadLock().lock();
            return map.isEmpty();
        } finally {
            getReadLock().unlock();
        }
    }

    public V put(K key, V value) {
        try {
            getWriteLock().lock();
            return map.put(key, value);
        } finally {
            getWriteLock().unlock();
        }
    }

    public V remove(Object key) {
        try {
            getWriteLock().lock();
            return map.remove(key);
        } finally {
            getWriteLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> m) {
        try {
            getWriteLock().lock();
            map.putAll(m);
        } finally {
            getWriteLock().unlock();
        }
    }

    public void clear() {
        try {
            getWriteLock().lock();
            map.clear();
        } finally {
            getWriteLock().unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ReadWriteMap<String, String> rwMap = new ReadWriteMap<>(new HashMap<>());

        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable writerTask = () -> {
            try {
                System.out.println("Starting writer task");
                for (int i = 0; i < 2; i++) {
                    Thread.sleep(100);
                    rwMap.put("key" + i, "value" + i);
                }
            } catch (InterruptedException e) {
                System.err.println("Writer interrupted: " + e);
            }
        };

        Runnable readTask = () -> {
            try {
                System.out.println("Starting read task");
                for (int i = 0; i < 2; i++) {
                    Thread.sleep(100);
                    System.out.println("Read: " + rwMap.get("key" + i));
                }
            } catch (InterruptedException e) {
                System.err.println("Reader interrupted: " + e);
            }
        };

        Runnable removeTask = () -> {
            try {
                System.out.println("Starting remove task");
                for (int i = 0; i < 2; i++) {
                    Thread.sleep(150);
                    rwMap.remove("key" + i);
                }
            } catch (InterruptedException e) {
                System.err.println("Remove task interrupted: " + e);
            }
        };

        executor.submit(writerTask);
        executor.submit(readTask);
        executor.submit(removeTask);

        executor.shutdown();
    }
}

